import {NavController} from 'ionic-angular';
import {HttpHelper} from './../../../util/HttpHelper';
import {ChangeDetectorRef, Component} from '@angular/core';
import {NativeService} from './../../../util/NativeService';
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";

declare var $: any;

@Component({
  selector: 'selector-WateringDayTimerPage',
  templateUrl: 'wateringDayTimer.html'
})

export class WateringDayTimerPage {
  pandaLoading: any = null;
  //0x00 -> Day
  //0x01 -> Week
  switchIndex: any = -1;
  intervalTime: any = "1";
  weekDays = [
    {day: "星期一", checked: false, val: 1},
    {day: "星期二", checked: false, val: 2},
    {day: "星期三", checked: false, val: 4},
    {day: "星期四", checked: false, val: 8},
    {day: "星期五", checked: false, val: 16},
    {day: "星期六", checked: false, val: 32},
    {day: "星期日", checked: false, val: 64}
  ];
  pickerAry: any = null;
  connectedDevice: any = null;

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController, public cd: ChangeDetectorRef, private  commandFactory: CommandFactory, private translate: TranslateService) {
  }

  ionViewWillEnter() {
    let self = this;

    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }

    self.weekDays = self.commandFactory.getWeekDays();
    self.intervalTime = "1";
    let pickerAry = [];
    let colAry = [];
    for (let i = 1; i <= 15; i++) {
      colAry.push(i.toString());
    }
    pickerAry.push(colAry);

    self.pickerAry = pickerAry;
    let dayWord = self.translate.get("common.day")["value"];
    let dayWords = self.translate.get("common.day2")["value"];
    let tempday = dayWord;
    // let res_d3 = self.commandFactory.readlocalProtocol(ProtocolType.First_d3, self.connectedDevice);
    //   if (res_d3.day == 1) {
    //     tempday = dayWord;
    //   }else{
    //     tempday = dayWords;
    //   }
    //   //有选择性的传入每列数组数据，先插入的先显示
    //   $('#pageColpicker').coolpicker({
    //     columnSpace: 15
    //   }).coolpicker(
    //     'loadData',
    //     [
    //       pickerAry[0],
    //       [tempday]
    //     ]
    //   );
    //   //设置选择值
    //   $('#pageColpicker').coolpicker('setValue', [res_d3.day, tempday]);
    //
    // $('#pageColpicker').coolpicker({
    //   columnSpace: 0,
    //   onRollCompleted: function (columnIndex, value) {
    //     AppConfig.consoleLog('column:' + columnIndex + ',value:' + value);
    //     if (columnIndex == 0) {
    //       let timeS = self.getValue();
    //       if (value == 1) {
    //         tempday = dayWord;
    //       }else{
    //         tempday = dayWords;
    //       }
    //       $('#pageColpicker').coolpicker(
    //         'loadData',
    //         [
    //           pickerAry[0],
    //           [tempday]
    //         ]
    //       )
    //       $('#pageColpicker').coolpicker('setValue', [value, dayWords]);
    //     }
    //   }
    // })


    let res_d3 = self.commandFactory.readlocalProtocol(ProtocolType.First_d3, self.connectedDevice);
    if (res_d3.day == 1) {
      tempday = dayWord;
    } else {
      tempday = dayWords;
    }
    $('#pageColpicker').coolpicker({
      columnSpace: 0,
      onRollCompleted: function (columnIndex, value) {
        AppConfig.consoleLog('column:' + columnIndex + ',value:' + value);
        if (columnIndex == 0) {
          let timeS = self.getValue();
          if (value == 0 || value == 1) {
            tempday = dayWord;
          } else {
            tempday = dayWords;
          }
          $('#pageColpicker').coolpicker(
            'loadData',
            [
              pickerAry[0],
              [tempday]
            ]
          )
          $('#pageColpicker').coolpicker('setValue', [value, tempday]);
        }
      }
    }).coolpicker(
      'loadData',
      [
        pickerAry[0],
        [tempday]
      ]
    );
    $('#pageColpicker').coolpicker('setValue', [res_d3.day, 123]);
  }

  ionViewDidEnter() {
    let self = this;
    //self.showPandaLoading();
    let res_d3 = self.commandFactory.readlocalProtocol(ProtocolType.First_d3, self.connectedDevice);
    // self.commandFactory.readRemote(ProtocolType.First_d3, (success_d3) => {
    //   AppConfig.consoleLog(success_d3);
    //   let res_d3 = success_d3;
    self.commandFactory.editCommand2(res_d3);
    self.selectedTab(res_d3.type);
    if (res_d3.type == 0 && res_d3.day > 0) {
      self.intervalTime = res_d3.day.toString();
      self.hidePandaLoading();
    } else {
      self.initStationWaterIng(res_d3.week);
    }
    //}, null, self.connectedDevice);
  }

  //初始化站点浇水日初始值
  initStationWaterIng(days) {
    let self = this;
    //分解按天模式数字
    let selectWeek = [];
    if (self.findWeekDaysIsInclude(days)) {
      selectWeek.push(days);
    } else {
      let nearlyFloor = null;
      let goWhile = true;
      let countWhile = 0;
      let weekDayVal = days;
      while (goWhile) {
        if (self.findWeekDaysIsInclude(weekDayVal)) {
          goWhile = false;
          selectWeek.push(weekDayVal);
        } else {
          nearlyFloor = self.findWeekDaysNearlyFloor(weekDayVal);
          if (nearlyFloor) {
            selectWeek.push(nearlyFloor.val);
            weekDayVal = weekDayVal - nearlyFloor.val;
          } else {
            goWhile = false;
          }
        }
      }
    }
    AppConfig.consoleLog(selectWeek)
    //初始化按天模式
    for (let i = 0; i < self.weekDays.length; i++) {
      for (let j = 0; j < selectWeek.length; j++) {
        if (self.weekDays[i].val == selectWeek[j]) {
          self.weekDays[i].checked = true;
          break;
        }
      }
    }

    self.hidePandaLoading();

  }

  //查询当前Val是否包含在weekDays
  findWeekDaysIsInclude(val) {
    let self = this;
    let include = false;
    self.weekDays.forEach((item) => {
      if (val == item.val)
        include = true;
    });
    return include;
  }

  //查找Weekdays中比当前值小的最大值
  findWeekDaysNearlyFloor(val) {
    let nearlyItem: any = null;
    let self = this;
    self.weekDays.forEach((item) => {
      if (item.val < val) {
        nearlyItem = item;
      }
    });
    return nearlyItem;
  }

  selectedChecked(item) {
    if (item.checked)
      item.checked = false;
    else
      item.checked = true;
    this.cd.detectChanges();
  }

  switchClick(idx) {
    let self = this;
    self.showPandaLoading();
    let res_d3 = self.commandFactory.readlocalProtocol(ProtocolType.First_d3, self.connectedDevice);
    // self.commandFactory.readRemote(ProtocolType.First_d3, (success_d3) => {
    //   AppConfig.consoleLog(success_d3);
    //   let res_d3 = success_d3;
    res_d3.type = idx;
    self.selectedTab(res_d3.type);
    if (idx == 0) {
      if (res_d3.day > 0) {
        self.intervalTime = res_d3.day.toString();
      }
      self.hidePandaLoading();
    } else {
      self.initStationWaterIng(res_d3.week);
    }
    //self.commandFactory.editCommand2(res_d3);
    // self.commandFactory.send("wateringDayTimer",res_d3)
    //   .then((success_send)=>{
    //     AppConfig.consoleLog(success_send);
    //   });
    //}, null, self.connectedDevice);
  }

  selectedTab(index) {
    this.switchIndex = index;
    document.getElementById("divSwitch1").setAttribute("class", "");
    document.getElementById("divSwitch0").setAttribute("class", "");
    document.getElementById("divSwitch" + index).setAttribute("class", "mySwitchControlSelectdItem");

    if (index == 1) {
      $(".scroll-content").css({"overflow": "auto"});
    } else {
      $(".scroll-content").css({"overflow": "hidden"});
    }
  }

  getValue() {
    //返回的为数组
    return $('#pageColpicker').coolpicker('getValue');
  }

  saveData() {
    let self = this;
    //self.showPandaLoading();
    let res_rad = self.commandFactory.getCommand(ProtocolType.First_d3);
    res_rad.type = self.switchIndex;
    //self.commandFactory.readRemote(ProtocolType.First_d3,(success_read)=>{
    //AppConfig.consoleLog(success_read)
    //let res_rad=success_read;
    if (res_rad.type == 0) {
      let timeS = self.getValue();
      timeS[0] = timeS[0] == "" ? self.pickerAry[0][self.pickerAry[0].length - 1] : timeS[0];

      AppConfig.consoleLog(timeS);
      res_rad.day = parseInt(timeS[0]);
    } else {
      let ztmDays: any = 0;
      self.weekDays.forEach(function (item) {
        if (item.checked) {
          ztmDays = ztmDays + item.val;
        }
      });
      res_rad.week = ztmDays;
    }
    self.commandFactory.editCommand2(res_rad);
    self.commandFactory.send("wateringDayTimer", res_rad)
      .then((success_send) => {
        AppConfig.consoleLog(success_send)
      });
    self.hidePandaLoading();
    self.goBack();
    //});

  }

  singleColumnscha() {
    AppConfig.consoleLog(this.intervalTime)
  }

  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    });
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }
}



