  //设置站点状态
  setZoneStates = (zoneStates: any = 0, zone: any = null) => {
    let self = this;
    switch (zoneStates) {
      case self.ZoneStates.standby:
        if (self.IrrigationStatus.zmStartAll)
          self.IrrigationStatus.zmStartAll = false;
        if (zone == 1) {
          if (self.IrrigationStatus.startS1)
            self.IrrigationStatus.startS1 = false;
          if (self.IrrigationStatus.zmStartS1)
            self.IrrigationStatus.zmStartS1 = false;
          self.IrrigationStatus.zone1States = zoneStates;
        } else {
          if (self.IrrigationStatus.startS2)
            self.IrrigationStatus.startS2 = false;
          if (self.IrrigationStatus.zmStartS2)
            self.IrrigationStatus.zmStartS2 = false;
          self.IrrigationStatus.zone2States = zoneStates;
        }
        break;
      case self.ZoneStates.monitoring:
        if (self.IrrigationStatus.zmStartAll)
          self.IrrigationStatus.zmStartAll = false;
        if (zone == 1) {
          if (self.IrrigationStatus.startS1) {
            self.IrrigationStatus.startS1 = false;

          }
          if (self.IrrigationStatus.cmStartS1) {
            self.IrrigationStatus.cmStartS1 = false;
          }
          self.IrrigationStatus.zone1States = zoneStates;
        } else {
          if (self.IrrigationStatus.startS2) {
            self.IrrigationStatus.startS2 = false;
          }
          if (self.IrrigationStatus.cmStartS2) {
            self.IrrigationStatus.cmStartS2 = false;
          }
          self.IrrigationStatus.zone2States = zoneStates;
        }
        break;
      case self.ZoneStates.zoneAuto:
        // if (self.IrrigationStatus.zmStartAll)
        if (AppConfig.zutotime1 > 0 || AppConfig.zutotime2 > 0)
          self.IrrigationStatus.zmStartAll = true;
        if (zone == 1) {
          if (!self.IrrigationStatus.startS1) {
            if (AppConfig.runInfo["isOnline"] == 1) {
              self.IrrigationStatus.startS1 = true;
              self.IrrigationStatus.cmStartS1 = false;
            } else {
              self.IrrigationStatus.startS1 = false;
              self.IrrigationStatus.cmStartS1 = false;
            }
          }
          self.IrrigationStatus.zone1States = zoneStates;
        } else {
          if (!self.IrrigationStatus.startS2) {
            if (AppConfig.runInfo["isOnline"] == 1) {
              self.IrrigationStatus.startS2 = true;
              self.IrrigationStatus.cmStartS2 = false;
            } else {
              self.IrrigationStatus.startS2 = false;
              self.IrrigationStatus.cmStartS2 = false;
            }
          }
          self.IrrigationStatus.zone2States = zoneStates;
        }
        break;
      case self.ZoneStates.zoneZm:
        // if (self.IrrigationStatus.zmStartAll)
        //self.IrrigationStatus.zmStartAll = false;
        if (AppConfig.zutotime1 > 0 || AppConfig.zutotime2 > 0)
          self.IrrigationStatus.zmStartAll = true;
        if (zone == 1) {
          // if (self.IrrigationStatus.zone2States == self.ZoneStates.zoneZm && !self.IrrigationStatus.zmStartAll) {
          //   if (AppConfig.runInfo["isOnline"] == 1) {
          //     self.IrrigationStatus.zmStartAll = true;
          //   } else {
          //     self.IrrigationStatus.zmStartAll = false;
          //   }
          // }
          if (!self.IrrigationStatus.startS1) {
            if (AppConfig.runInfo["isOnline"] == 1) {
              self.IrrigationStatus.startS1 = true;
              self.IrrigationStatus.cmStartS1 = false;
            } else {
              self.IrrigationStatus.startS1 = false;
              self.IrrigationStatus.cmStartS1 = false;
            }
          }
          self.IrrigationStatus.zone1States = zoneStates;
        } else {
          // if (self.IrrigationStatus.zone1States == self.ZoneStates.zoneZm && !self.IrrigationStatus.zmStartAll) {
          //   if (AppConfig.runInfo["isOnline"] == 1) {
          //     self.IrrigationStatus.zmStartAll = true;
          //   } else {
          //     self.IrrigationStatus.zmStartAll = false;
          //   }
          // }
          if (!self.IrrigationStatus.startS2) {
            if (AppConfig.runInfo["isOnline"] == 1) {
              self.IrrigationStatus.startS2 = true;
              self.IrrigationStatus.cmStartS2 = false;
            } else {
              self.IrrigationStatus.startS2 = false;
              self.IrrigationStatus.cmStartS2 = false;
            }
          }
          self.IrrigationStatus.zone2States = zoneStates;
        }
        break;
      case self.ZoneStates.zonesoak:
        if (self.IrrigationStatus.zmStartAll)
          self.IrrigationStatus.zmStartAll = false;
        if (zone == 1) {
          if (!self.IrrigationStatus.cmStartS1) {
            if (AppConfig.runInfo["isOnline"] == 1) {
              self.IrrigationStatus.startS1 = false;
              self.IrrigationStatus.cmStartS1 = true;
            } else {
              self.IrrigationStatus.startS1 = false;
              self.IrrigationStatus.cmStartS1 = false;
            }
          }
          self.IrrigationStatus.zone1States = zoneStates;
        } else {
          if (!self.IrrigationStatus.cmStartS2) {
            if (AppConfig.runInfo["isOnline"] == 1) {
              self.IrrigationStatus.startS2 = false;
              self.IrrigationStatus.cmStartS2 = true;
            } else {
              self.IrrigationStatus.startS2 = false;
              self.IrrigationStatus.cmStartS2 = false;
            }
          }
          self.IrrigationStatus.zone2States = zoneStates;
        }
        break;
    }

    if (this.cd !== null && this.cd !== undefined &&
      !(this.cd as ViewRef_).destroyed) {
      this.cd.detectChanges();
    }
  }


