  /**
   * 获取浇水历史记录
   * @param zone 出口名
   * @param strStartDate 起始日期
   * @param strEndDate 终止日期
   * @param callback
   */
  onRequstHistory(zone, strStartDate, strEndDate, callback) {
    //这里请求数据，完事后调用
    //找到指定时间的上一条与下一条浇灌记录

    let me = this;
    //AppConfig.consoleLog(me.zone1NameTxt)
    this.commandFactory.queryLog()
      .then((success) => {
        ////AppConfig.consoleLog("onRequstHistory" + success);
        let r = JSON.parse(JSON.stringify(success));
        let zone1His = [], zone2His = [];
        if (1 > 1) {
          r.rows.forEach((row) => {
            if (row.zoneName == "zone1") {
              zone1His.push(row);
            } else if (row.zoneName == "zone2") {
              zone2His.push(row);
            }
          });
        }
        if (zone1His.length > 0) {
          this.preNextData.zone1.preDta = me.nativeService.twotransform(zone1His[zone1His.length - 1].updateTime, zone1His[zone1His.length - 1].log);
          this.preNextData.zone1.preLog = zone1His[zone1His.length - 1].log;
        }
        if (zone2His.length > 0) {
          this.preNextData.zone2.preDta = me.nativeService.twotransform(zone2His[zone2His.length - 1].updateTime, zone2His[zone2His.length - 1].log);
          this.preNextData.zone2.preLog = zone2His[zone2His.length - 1].log;
        }

        // if (zone1His.length > 0) {
        //   this.preNextData.zone1.preDta = zone1His[zone1His.length - 1].updateTime;
        //   this.preNextData.zone1.preLog = zone1His[zone1His.length - 1].log;
        // }
        // if (zone2His.length > 0) {
        //   this.preNextData.zone2.preDta = zone2His[zone2His.length - 1].updateTime;
        //   this.preNextData.zone2.preLog = zone2His[zone2His.length - 1].log;
        // }
        //传入了站点名，则要进行过滤
        if (zone == "zone1")
          r.rows = zone1His;
        else if (zone == "zone2")
          r.row = zone2His;
        callback(r, zone, strStartDate, strEndDate, me);
      });

  }


