  /**
   * 判断是否在时间区间
   * @param beginTime
   * @param endTime
   * @param curtime
   */
  checkAuditTime(beginTime: any, endTime: any, curtime) {
    var nowDate = new Date();
    var beginDate = new Date(nowDate);
    var endDate = new Date(nowDate);
    beginDate.setHours(beginTime.getHours(), beginTime.getMinutes(), 0, 0);
    endDate.setHours(endTime.getHours(), endTime.getMinutes(), 0, 0);
    if (curtime - beginDate.getTime() >= 0 && curtime <= endDate.getTime()) {
      return true;
    } else {
      return false;
    }
  }

  /**
   * 秒转化时分秒
   * @param value
   */
  formatsecond(result) {
    var h = Math.floor(result / 3600) < 10 ? '0' + Math.floor(result / 3600) : Math.floor(result / 3600);
    var m = Math.floor((result / 60 % 60)) < 10 ? '0' + Math.floor((result / 60 % 60)) : Math.floor((result / 60 % 60));
    var s = Math.floor((result % 60)) < 10 ? '0' + Math.floor((result % 60)) : Math.floor((result % 60));
    return result = h + ":" + m + ":" + s;
  }

  /**
   * 时分秒 转 数字
   * @param time
   */
  dateToTimestamp(time) {
    let hh = Math.floor(time.substring(0, 2));
    let mi = Math.floor(time.substring(3, 5));
    let ss = Math.floor(time.substring(6));
    let ts = (hh * 60 * 60) + (mi * 60) + ss;
    return ts;
  }

