  //开始手动灌溉
  startZmIrrigation(idx, time: string) {
    //AppConfig.consoleLog(idx)
    //AppConfig.consoleLog(time)
    let self = this;
    let cmd: any = null;
    //let cmd83=self.commandFactory.getCommand(ProtocolType.Second_83);
    self.commandFactory.readRemote(ProtocolType.Second_82, (success_82) => {
      //AppConfig.consoleLog(success_82);
      let cmd82 = success_82;
      let cmd83 = self.commandFactory.getCommand(ProtocolType.Second_83);
      cmd83.specialSetting = 0;
      if (cmd82.zone1State == 1)
        cmd83.zone1EnableManual = false;
      if (cmd82.zone2State == 1)
        cmd83.zone2EnableManual = false;
      if (idx == 1) {
        cmd = self.commandFactory.getCommand(ProtocolType.Second_86);
        if (AppConfig.zutotime2 > 1) {
          cmd83.zone2EnableManual = true;
        } else {
          cmd83.zone2EnableManual = false;
        }
        cmd83.zone1EnableManual = true;
      } else {
        cmd = self.commandFactory.getCommand(ProtocolType.Second_8b);
        if (AppConfig.zutotime1 > 1) {
          cmd83.zone1EnableManual = true;
        } else {
          cmd83.zone1EnableManual = false;
        }
        cmd83.zone2EnableManual = true;
      }
      cmd.wIndex = 4;
      cmd.zmHour = parseInt(time.split(":")[0]);
      cmd.zmMinute = parseInt(time.split(":")[1]);
      cmd.zmSecond = parseInt(time.split(":")[2]);

      let run_zone_cmd = cmd;
      run_zone_cmd["createTime"] = new Date().getTime();
      let startTime = new Date().getTime();
      let endTime = new Date(startTime + cmd.zmHour * 60 * 60 * 1000 + cmd.zmMinute * 60 * 1000 + cmd.zmSecond * 1000).getTime();

      if (idx == 1) {
        AppConfig.zone1showmes = false;
        localStorage.setItem("run_zone1_cmd", JSON.stringify(run_zone_cmd));
        localStorage.setItem("run_zone1_zm_time", JSON.stringify({
          zone: "zone1",
          startTime: startTime,
          endTime: endTime
        }));

      } else if (idx == 2) {
        AppConfig.zone2showmes = false;
        localStorage.setItem("run_zone2_cmd", JSON.stringify(run_zone_cmd));
        localStorage.setItem("run_zone2_zm_time", JSON.stringify({
          zone: "zone2",
          startTime: startTime,
          endTime: endTime
        }));
      }
      self.commandFactory.send_2("twoSchedule", cmd)
        .then((success) => {
          self.commandFactory.editCommand2(cmd);
          self.commandFactory.send_2("twoSchedule", cmd83)
            .then((success) => {
              self.commandFactory.editCommand2(cmd83);
            });
        });
    }, null, self.connectedDevice);

  }

