import {NavController, NavParams} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {Component, OnInit} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {ChangeDetectorRef} from '@angular/core';
import {AppConfig} from "../../../app/appconfig";
import {TranslateService} from "ng2-translate";
import {ProtocolType, CommandFactory} from "../../../util/CommandFactory";


@Component({
  selector: 'selector-settingStationName',
  templateUrl: 'settingStationName.html'
})

export class SettingStationNamePage {
  public showMore: boolean = false;
  public entpList: any = [];
  PageSize = 10;
  PageIndex = 1;
  eiPageCount = 0;
  zoneName: string = null;
  zone = 1;
  dataLs: any;
  email = {
    to: 'BTT@hunterindustries.com',
    subject: 'BTT App Feedback',
    body: "Feedback Device Platform=Android Device Model=OPPO OPPO R9s OS Version=6.1 Device Screen Height=1920 Device Screen Width=1080 App Version=2.0.1 Language=中文",
    isHtml: false
  };
  thisVersion: any = null;
  public currentUserInfo: any = {};
  version: any = AppConfig.apkVersion;
  connectedDevice: any = null;

  constructor(private nativeService: NativeService,
              private httpHelper: HttpHelper,
              public navCtrl: NavController,
              public cd: ChangeDetectorRef,
              private translate: TranslateService,
              private  navParams: NavParams,
              private  commandFactory: CommandFactory) {

  }

  ionViewWillEnter() {
    //this.serach();
    let self = this;
    self.zone = self.navParams.get("zone");
    self.zoneName = self.navParams.get("zoneName");

    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }
    self.thisVersion = self.connectedDevice.thisversion;
  }

  ionViewDidEnter() {
    //初始化数据
    let self = this;
    if (self.thisVersion > 3) {
      if (self.zone == 1) {
        let res = self.commandFactory.readlocalProtocol(ProtocolType.Second_90, self.connectedDevice);
        // self.commandFactory.read(ProtocolType.Second_90, self.connectedDevice)
        //   .then((success) => {
        //     AppConfig.consoleLog("ProtocolType.Second_90" + success);
        //     let res: any = success;
        //     AppConfig.consoleLog("ProtocolType.Second_90.res.zoneName" + res.zoneName);
            if (res.zoneName.trim() == "") {
              self.zoneName = self.translate.get("twoExport.twoSchedule.zone1")["value"];
            } else {
              self.zoneName = res.zoneName;
            }
          //});
      } else {
        let res = self.commandFactory.readlocalProtocol(ProtocolType.Second_91, self.connectedDevice);
        // self.commandFactory.read(ProtocolType.Second_91, self.connectedDevice)
        //   .then((success) => {
        //     AppConfig.consoleLog(success);
        //     AppConfig.consoleLog("ProtocolType.Second_91" + success);
        //     let res: any = success;
        //     AppConfig.consoleLog("ProtocolType.Second_91.res.zoneName" + res.zoneName);
            if (res.zoneName.trim() == "") {
              self.zoneName = self.translate.get("twoExport.twoSchedule.zone2")["value"];
            } else {
              self.zoneName = res.zoneName;
            }
          //});
      }
    } else {
      if (!localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")) {
        let zone1Name = self.translate.get("twoExport.twoSchedule.zone1")["value"];
        let zone2Name = self.translate.get("twoExport.twoSchedule.zone2")["value"];
        localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName", JSON.stringify({
          zone1: zone1Name,
          zone2: zone2Name
        }));
      }
      if (self.zone == 1) self.zoneName = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")).zone1;
      else self.zoneName = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")).zone2;
    }
  }

  save() {
    let self = this;
    //发送给设备的信息 Second_90
    if (AppConfig.isDockingMachine) {
      if (self.thisVersion > 3) {
        let Second_90_91;
        if (self.zoneName.trim() == "") {
          self.zoneName = self.translate.get("twoExport.twoSchedule.zone1")["value"];
        }
        if (self.zone == 1) {
          AppConfig.consoleLog("self.zone" + self.zone);
          Second_90_91 = {"protocolType": "Second_90", "zoneName": self.zoneName};
          localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') +"Second_90_zone1Name", self.zoneName);
        } else if (self.zone == 2) {
          AppConfig.consoleLog("self.zone" + self.zone);
          Second_90_91 = {"protocolType": "Second_91", "zoneName": self.zoneName};
          localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') +"Second_90_zone2Name", self.zoneName);
        }
        self.commandFactory.send_2("SettingStationNamePage", Second_90_91)
          .then((success) => {
            AppConfig.consoleLog(success);
            self.goBack();
          });
      } else {
        let local_zoneName = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName"));
        if (self.zone == 1) {
          if (self.zoneName.trim() == "") {
            self.zoneName = self.translate.get("twoExport.twoSchedule.zone1")["value"];
            local_zoneName.zone1 = self.zoneName;
          } else {
            local_zoneName.zone1 = self.zoneName;
          }
        } else {
          if (self.zoneName.trim() == "") {
            self.zoneName = self.translate.get("twoExport.twoSchedule.zone2")["value"];
            local_zoneName.zone2 = self.zoneName;
          } else {
            local_zoneName.zone2 = self.zoneName;
          }
        }
        localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName", JSON.stringify(local_zoneName));
        self.goBack();
      }
    } else {
      let local_zoneName = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName"));
      if (self.zone == 1) {
        if (self.zoneName.trim() == "") {
          self.zoneName = self.translate.get("twoExport.twoSchedule.zone1")["value"];
          local_zoneName.zone1 = self.zoneName;
        } else {
          local_zoneName.zone1 = self.zoneName;
        }
      } else {
        if (self.zoneName.trim() == "") {
          self.zoneName = self.translate.get("twoExport.twoSchedule.zone2")["value"];
          local_zoneName.zone2 = self.zoneName;
        } else {
          local_zoneName.zone2 = self.zoneName;
        }
      }
      localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName", JSON.stringify(local_zoneName));
      self.goBack();
    }
  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }

}



