import {App, NavController, NavParams} from 'ionic-angular';
import { Component, OnInit } from '@angular/core';
import { ChangeDetectorRef } from '@angular/core';
import { HttpHelper } from "../../../util/HttpHelper";
import { NativeService } from "../../../util/NativeService";
import {BttVersion, CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {NavPage} from "../../common/nav/nav";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";
declare var app:any;
@Component({
  selector: 'selector-loginBtts',
  templateUrl: 'loginBtts.html'
})

export class LoginBttsPage {
  public showMore: boolean = false;
  public entpList: any = [];
  address:string=null;
  postcode:string=null;
  curDevice=null;

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController,
              public cd: ChangeDetectorRef,public appCtrl: App,private  navParams:NavParams,private  commandFactory:CommandFactory,
              private translate:TranslateService) {
  }

  ionViewWillEnter() {
    //this.serach();
    let self=this;
    self.address=self.navParams.get("address");
    // if(AppConfig.isDebug){
    //   self.curDevice=self.commandFactory.findCurConnectDevice();
    // }
    // self.nativeService.queryDeviceData("nickName,password","address='"+self.address+"'",function (r) {
    //   AppConfig.consoleLog(r);
    //   if(r.result>0){
    //     self.curDevice=r.rows[0];
    //   }
    // })
  }

  login(){
    let self=this;
    let Second_81=self.commandFactory.getCommand(ProtocolType.Second_81);

    if(self.postcode.trim()==Second_81.password.replace(/(\u0000)+/,"").toString().trim()){
      let local_start_count=JSON.parse(localStorage.getItem("local_start_count"));
      local_start_count.SecondLogin=true;
      localStorage.setItem("local_start_count",JSON.stringify(local_start_count));
      self.goSchedule();
    }
    else{
      let incorrectPassword=self.translate.get("incorrectPassword")["value"];
      self.commandFactory.showAlert(incorrectPassword)
    }


  }
  viewEnterPirseInfo(entId: number) {
  }
  goSchedule(){
    let self=this;
    //self.appCtrl.getRootNavs()[0].setRoot(NavPage);
    app.autoTabGo(
      self.navCtrl,
      AppConfig.runInfo['selectOnlineDevice'],
      AppConfig.runInfo['selectOfflineDevice'],
      AppConfig.runInfo['isTwoMode'],
      AppConfig.runInfo['isOnline'],
      1
    );
  }
  goBack() {
    let self=this;
    self.commandFactory.disConnect().then(
      (success)=>{
        AppConfig.consoleLog(success);
        if(localStorage.getItem("local_device_list")){
          let deviceList=JSON.parse(localStorage.getItem("local_device_list"));
          deviceList.forEach((v)=>{
            v["connected"]=false;
          });
          localStorage.setItem("local_device_list",JSON.stringify(deviceList));
        }
        document.location.reload();
        this.navCtrl.pop({animate: false});
      });

  }
}



