import {NavController, ActionSheetController, Platform} from 'ionic-angular';
import {Component} from "@angular/core";
import {SettingStationBatteryPage} from "../../more/settingStationBattery/settingStationBattery";
import {LoginBttsPage_1} from "../../btts_1/loginBtts_1/loginBtts_1";
import {LocationSettingsPage} from "../locationSettings/locationSettings";
import {NativeService} from "../../../util/NativeService";
import {CommandFactory} from "../../../util/CommandFactory";
import {AppConfig} from "../../../app/appconfig";

declare var google: any;
declare var $: any;

@Component({
  selector: 'selector-mapBtts',
  templateUrl: 'mapBtts.html'
})

export class MapBttsPage {
  markerList = [];
  first = 0;
  map;
  //设备坐标集
  btt_coords = [
    //   {
    //   lat: 0,
    //   lng: 0,
    //   bttId: 1,
    //   labelIndex: 1,
    //   title: "",
    //   address: "",
    //   isOnline: true
    // }
  ];

  public marker;

  public new_marker: any = null;
  //存放点击marker列表
  public new_markerlist: any = [];


  constructor(private nativeService: NativeService, private platform: Platform,
              private  commandFactory: CommandFactory, public navCtrl: NavController, public actionSheetCtrl: ActionSheetController) {

  }

  goBack() {
    this.navCtrl.pop();
  }

  goSettingBtts(lng, lat) {
    this.navCtrl.push(LocationSettingsPage, {lng, lat});
  }

  goSettingBttsedit(type, mac) {
    this.navCtrl.push(LocationSettingsPage, {type, mac});
  }

  ionViewWillEnter() {
    this.first = 0;
    this.initMap();
    //this.CenterControl2(this.centerControlDiv2, this.map)
  }

  ionViewDidEnter() {
  }

//初始化谷歌地图
  initMap() {
    var _this = this;

    // //创建地图
    // _this.map = new google.maps.Map(
    //   document.getElementById("googleMap") as HTMLElement,
    //   {
    //     zoom: 18,//缩放级别
    //     streetViewControl: false //是否显示街景按钮,
    //   }
    // );
    //
    // //获取当前坐标
    // if (navigator.geolocation) {
    //   navigator.geolocation.getCurrentPosition(function (position) {
    //     const pos = {
    //       lat: parseFloat(position.coords.latitude.toString()),
    //       lng: parseFloat(position.coords.longitude.toString())
    //     };
    //
    //     _this.marker = new google.maps.Marker({
    //       position: pos,
    //       map: _this.map,
    //       icon: {
    //         url: "assets/icon/marker-self.png", // url
    //         scaledSize: new google.maps.Size(40, 40), // scaled size
    //         origin: new google.maps.Point(0, 0), // origin
    //         anchor: new google.maps.Point(0, 0) // anchor
    //       }
    //     });
    //     AppConfig.consoleLog(pos);
    //     _this.map.setCenter(pos);
    //   });
    // }
    // _this.map.setZoom(18);


    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(function (position) {
          var coords = position.coords;
          //console.log(position);
          var latlng = new google.maps.LatLng(coords.latitude, coords.longitude);
          var myOptions = {
            zoom: 14,                             //设定方法倍数
            center: latlng,                       //将地图中心设定为指定的坐标点
            //mapTypeId: google.maps.MapTypeId.ROADMAP,     //制定地图类型
            streetViewControl: false //是否显示街景按钮
          };
          _this.map = new google.maps.Map(document.getElementById("googleMap") as HTMLElement, myOptions);

          _this.marker = new google.maps.Marker({
            position: latlng,
            map: _this.map,
            icon: {
              url: "assets/icon/marker-self.png", // url
              scaledSize: new google.maps.Size(40, 40), // scaled size
              origin: new google.maps.Point(0, 0), // origin
              anchor: new google.maps.Point(0, 0) // anchor
            }
          });

          // var infoWindow = new google.maps.InfoWindow({
          //   content: "当前位置：<br/>经度：" + latlng.lat() + "<br/>纬度：" + latlng.lng()
          // });
          //
          // infoWindow.open(_this.map, _this.marker);

          //删除标注
          const centerControlDiv = document.createElement("div");
          _this.CenterControl(centerControlDiv, _this.map);
          _this.map.controls[google.maps.ControlPosition.LEFT_BOTTOM].push(centerControlDiv);

          //删除设备
          // const centerControlDiv1 = document.createElement("div");
          // _this.CenterControl1(centerControlDiv1, _this.map);
          // _this.map.controls[google.maps.ControlPosition.LEFT_BOTTOM].push(centerControlDiv1);

          //添加我的坐标按钮
          const centerControlDiv2 = document.createElement("div");
          _this.CenterControl2(centerControlDiv2, _this.map);
          _this.map.controls[google.maps.ControlPosition.LEFT_BOTTOM].push(centerControlDiv2);

          //设置地图样式，简化地图上的要素显示
          let map_style = [
            {
              featureType: "poi",//屏蔽所有POI兴趣点，防止点击弹出信息窗
              stylers: [{visibility: "off"}],
            },
            {
              featureType: "transit",
              elementType: "labels.icon",
              stylers: [{visibility: "off"}],
            },
          ];
          _this.map.setOptions({styles: map_style});

          let curDeviceMac: any = null;
          let tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
          for (let i = 0; i < tempDevice.length; i++) {
            if (tempDevice[i]["connected"] == true) {
              curDeviceMac = tempDevice[i]["address"];
              break;
            }
          }

          _this.nativeService.queryDeviceMapData("*", "", function (r) {
            _this.markerList = [];
            //_this.btt_coords = [];
            AppConfig.consoleLog(r);
            if (r.result > 0) {
              for (let i = 0; i < r.rows.length; i++) {
                let markers: any = {
                  title: '',
                  address: '',
                  site: '',
                  markerid: 0,
                  icon: '',
                  textcontent: '',
                  position: '',
                  lat: 0,
                  lng: 0,
                  isOnline: false,
                  mac: ''

                };
                markers.title = r.rows[i].name;
                markers.address = r.rows[i].address;
                markers.site = r.rows[i].site;
                markers.markerid = r.rows[i].id;
                //icon: '//a.amap.com/jsapi_demos/static/demo-center/icons/poi-marker-1.png',
                markers.mac = r.rows[i].mac;
                if (curDeviceMac == r.rows[i].mac) {
                  // markers.icon = new google.maps.Marker({
                  //   url: "assets/icon/icon_green.png"
                  // });
                  markers.isOnline = true;
                } else {
                  // markers.icon = new google.maps.Marker({
                  //   url: "assets/icon/icon_grey.png"
                  // });
                  markers.isOnline = false;
                }
                markers.textcontent = '1';
                markers.position = "[" + r.rows[i].lng + "," + r.rows[i].lat + "]";
                markers.lat = parseFloat(r.rows[i].lat);
                markers.lng = parseFloat(r.rows[i].lng);

                _this.markerList.push(markers);
              }


              //设备定位点
              let bounds = new google.maps.LatLngBounds();
              for (let coord of _this.markerList) {
                bounds.extend(new google.maps.LatLng(coord));

                //创建标注
                let liveMarker = new google.maps.Marker({
                  map: _this.map,
                  icon: (coord.isOnline ? "assets/icon/icon_green.png" : "assets/icon/icon_grey.png"),
                  position: new google.maps.LatLng(coord),
                  draggable: true
                });
                _this.MapsOverlays(liveMarker, coord, _this.map);
              }
              _this.map.fitBounds(bounds);//自动适配地图级别和中心，使点标记同时显示在视野内。

              google.maps.event.addListener(_this.map, 'click', function (event) {
                //if ($('#set-marker').is(':checked')) {


                $('#divDel').show();
                var lat = event.latLng.lat();
                var lng = event.latLng.lng();
                var marker_position = event.latLng;
                //console.log(marker_position);
                _this.new_marker = new google.maps.Marker({
                  map: _this.map,
                  draggable: true
                });
                if (_this.first == 0) {
                  _this.new_marker.setPosition(marker_position);
                  _this.first = 1;
                }
                _this.new_marker.addListener("click", function (marker_event) {
                  _this.goSettingBtts(lng, lat);
                });
                _this.new_markerlist.push(_this.new_marker);
                //}else{//非放置设备模式下，点击消失设备弹出信息窗
                $("#googleMap .marker-info").hide();
                //}
              })
            }
          });

        },


        function (error) {
          switch (error.code) {
            case 1:
              alert("位置服务被拒拒。");
              break;
            case 2:
              alert("暂时获取不到位置信息。");
              break;
            case 3:
              alert("获取信息超时。");
              break;
            default:
              alert("未知错误。");
              break;
          }
        });
    } else {
      alert("你的浏览器不支持HTML5来获取地理位置信息。");
    }
  }


  /**
   * @description 地图叠加
   * @param theMark
   * @param theCoord
   * @param map
   * @constructor
   */
  MapsOverlays(theMark, coord, map) {
    let me = this;

    let theCoord: any = {lat: coord.lat, lng: coord.lng};

    class USGSOverlay extends google.maps.OverlayView {
      private div: HTMLElement;

      onAdd() {
        this.div = document.createElement('div');
        this.div.style.borderStyle = 'none';
        this.div.style.borderWidth = '0px';
        this.div.style.position = 'absolute';
        this.div.style.left = "20px";
        this.div.style.top = "10px";


        this.div.innerHTML = /*'<i class="marker' + (coord.isOnline ? " marker-online" : "") + '" data-id=' + coord.markerid + '></i>' +*/
          '<div id="editMarker' + coord.markerid + '" ><div class="marker-info' + (coord.isOnline ? " marker-online-info" : "") + '">' +
          '<div class="marker-info-content">' +
          '<span class="marker-ic-left">' +
          '<img class="marker-ic-img"  src="' + (coord.devicePic ? coord.devicePic : "assets/images/img-1.png") + '"></span>' +
          '<span class="marker-ic-right">' +
          '<div style="display: flex;align-items: center;justify-content: space-between;margin-right: 15px;">' +
          '<p class="marker-ic-text-1">' + coord.title + '</p>' +
          //'<a id="divDel" (click)="btndeleteDev(' + coord.markerid + ')">X</a> </div>' +
          '</div>' +
          '<p class="marker-ic-text-2">' + coord.address + '</p> ' +
          '<p class="marker-ic-text-3">' + coord.site + '</p></div></div></div>';
        // '<p class="marker-ic-text-1">中国浙江省杭州市马云家后院草坪西北角</p>' +
        // '<p class="marker-ic-text-2">中国广东省深圳市福田区现代大厦31楼</p> ' +
        // '<p class="marker-ic-text-3">4站点定时器</p></div></div></div>';


        const panes = this.getPanes();
        panes.overlayLayer.appendChild(this.div);
        panes.overlayMouseTarget.appendChild(this.div);
        var $marker_info = $('.marker-info', this.div);
        google.maps.event.addListener(theMark, "click", function () {
          $("#googleMap .marker-info").hide();
          $marker_info.show();
          // theMark.assocatePanelisShow=true;
        });
        // google.maps.event.addDomListener(this.div, 'click', function () {
        //   $("#googleMap .marker-info").hide();
        //   $marker_info.show();
        // });
        // google.maps.event.addListener(theMark, 'dragstart', function() {
        //   if(theMark.assocatePanelisShow) {
        //     $marker_info.hide();
        //   }
        // });
        let updateTime: string = me.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
        google.maps.event.addListener(theMark, 'dragend', function () {
          theCoord = theMark.getPosition();
          try {
            this.draw();
          } catch (e) {

          }
          me.nativeService.updateDeviceMapDataBymac(updateTime,  theCoord.lng(), theCoord.lat(), coord.mac, (r) => {
            AppConfig.consoleLog(r);

          })


          // if(theMark.assocatePanelisShow) {
          //   $marker_info.show();
          // }
        });

        //弹出删除按钮  删除移到编辑页面
        //console.log(coord.markerid);
        // let addEvent = document.getElementById("divDel" + coord.markerid);
        // addEvent.addEventListener("click", function () {
        //   me.commandFactory.showConfirm("是否删除设备", () => {
        //     me.platform.ready()
        //       .then(
        //         () => {
        //           me.btndelete(2, coord.markerid);
        //
        //         }
        //       );
        //   });
        // })


        //点击编辑
        let editManrker = document.getElementById("editMarker" + coord.markerid);
        editManrker.addEventListener("click", function () {
          me.goSettingBttsedit("edit", coord.mac);
          //console.log(1)
        })
        //停止单击或点击该元素以免冒泡至地图。使用此选项可防止地图触发“点击”事件而展示地图景点信息。
        google.maps.OverlayView.preventMapHitsFrom(this.div)
      }


      draw() {
        let bounds = new google.maps.LatLngBounds(/*new google.maps.LatLng(coord)*/theCoord);
        this.bounds = bounds;
        const overlayProjection = this.getProjection();
        const sw = overlayProjection.fromLatLngToDivPixel(
          this.bounds.getSouthWest()
        );
        const ne = overlayProjection.fromLatLngToDivPixel(
          this.bounds.getNorthEast()
        );
        if (this.div) {
          this.div.style.left = (sw.x - 15) + 'px';
          this.div.style.top = (ne.y - 32) + 'px';
          this.div.style.width = ne.x - sw.x + "px";
          this.div.style.height = sw.y - ne.y + "px";
        }
      }

      onRemove() {
        if (this.div) {
          (this.div.parentNode as HTMLElement).removeChild(this.div);
          delete this.div;
        }
      }

      hide() {
        if (this.div) {
          this.div.style.visibility = "hidden";
        }
      }

      show() {
        if (this.div) {
          this.div.style.visibility = "visible";
        }
      }
    }

    const overlay: USGSOverlay = new USGSOverlay();
    overlay.setMap(map);
  }

  btndelete(type, id) {
    if (type == 1) {
      this.first = 0;

      for (let i = 0; i < this.new_markerlist.length; i++) {
        this.new_markerlist[i].setMap(null);
      }
      this.new_markerlist = [];

      // this.new_marker.setMap(null);
      // this.new_marker = [];
      $('#divDel').hide();
    } else if (type == 2) {
      this.nativeService.deleteDeviceMapTable(id, (r) => {
        AppConfig.consoleLog(r);
        this.initMap();
      })
    }
  }

  CenterControl(controlDiv, map) {
    // Set CSS for the control border.
    const controlUI = document.createElement("div");
    controlUI.style.backgroundColor = "#fff";
    controlUI.style.border = "2px solid #fff";
    controlUI.style.borderRadius = "3px";
    controlUI.style.boxShadow = "0 2px 6px rgba(0,0,0,.3)";
    controlUI.style.cursor = "pointer";
    controlUI.style.marginBottom = "50px";
    controlUI.style.textAlign = "center";
    controlUI.style.display = "none";
    controlUI.id = "divDel";
    controlUI.title = "Click to recenter the map";
    controlDiv.appendChild(controlUI);
    // Set CSS for the control interior.
    const controlText = document.createElement("div");
    controlText.style.color = "rgb(25,25,25)";
    controlText.style.fontFamily = "Roboto,Arial,sans-serif";
    controlText.style.fontSize = "16px";
    controlText.style.lineHeight = "38px";
    controlText.style.paddingLeft = "5px";
    controlText.style.paddingRight = "5px";
    controlText.innerHTML = "DEL";
    controlUI.appendChild(controlText);
    controlUI.addEventListener("click", () => {
      this.first = 0;
      AppConfig.consoleLog("删除标注");
      this.btndelete(1, 0);
    });
  }

  CenterControl2(controlDiv, map) {

    var firstChild = document.createElement('button');
    firstChild.style.backgroundColor = '#fff';
    firstChild.style.border = 'none';
    firstChild.style.outline = 'none';
    firstChild.style.width = '28px';
    firstChild.style.height = '28px';
    firstChild.style.borderRadius = '2px';
    firstChild.style.boxShadow = '0 1px 4px rgba(0,0,0,0.3)';
    firstChild.style.cursor = 'pointer';
    firstChild.style.marginRight = '10px';
    firstChild.style.padding = '0px';
    firstChild.title = 'Your Location';
    controlDiv.appendChild(firstChild);

    var secondChild = document.createElement('div');
    secondChild.style.margin = '5px';
    secondChild.style.width = '18px';
    secondChild.style.height = '18px';
    secondChild.style.backgroundImage = 'url(https://maps.gstatic.com/tactile/mylocation/mylocation-sprite-1x.png)';
    secondChild.style.backgroundSize = '180px 18px';
    secondChild.style.backgroundPosition = '0px 0px';
    secondChild.style.backgroundRepeat = 'no-repeat';
    secondChild.id = 'you_location_img';
    firstChild.appendChild(secondChild);

    google.maps.event.addListener(map, 'dragend', function () {
      $('#you_location_img').css('background-position', '0px 0px');
    });

    firstChild.addEventListener('click', function () {
      var imgX = '0';
      var animationInterval = setInterval(function () {
        if (imgX == '-18') imgX = '0';
        else imgX = '-18';
        $('#you_location_img').css('background-position', imgX + 'px 0px');
      }, 500);
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(function (position) {
          var latlng = new google.maps.LatLng(position.coords.latitude, position.coords.longitude);
          // marker.setPosition(latlng);
          map.setZoom(18);
          // AppConfig.consoleLog(map.getZIndex());
          map.setCenter(latlng);
          clearInterval(animationInterval);
          $('#you_location_img').css('background-position', '-144px 0px');
        });
      } else {
        clearInterval(animationInterval);
        $('#you_location_img').css('background-position', '0px 0px');
      }
    });

  }
}





