import { Pipe, PipeTransform } from '@angular/core';
import {TranslateService} from "ng2-translate";
import {NativeService} from '../util/NativeService';
import {AppConfig} from "../app/appconfig";
import {CommandFactory} from "../util/CommandFactory";

/**
 * Generated class for the KeyAryft pipe.
 *
 * See https://angular.io/api/core/Pipe for more info on Angular Pipes.
 */
@Pipe({
  name: '$GrassRuntimeft',
})
export class GrassRuntimeft implements PipeTransform {
  constructor(private translate:TranslateService,private  native:NativeService,private  commandFact:CommandFactory){

  }
  /**
   * Takes a value and makes it .
   */
  transform(value: any, ...args) {
    //console.log(value);
    //console.log(args);
    if (!value) {
      return "";
    }
    let showText = "";
    let valDate = new Date(value);
    let curDate=new Date();
    //判断是否为当日
    if(curDate.getFullYear()==valDate.getFullYear()&& curDate.getMonth()==valDate.getMonth()&&curDate.getDate()==valDate.getDate()){
      showText+=this.translate.get("common.today")["value"]+", ";
    }else{
      //获取当前星期
      let weekAry = this.commandFact.getWeekDays2("weekDaysShort");
      showText = weekAry[valDate.getDay()].name + ", ";
      //获取日期
      let monthAry = this.commandFact.getMonth();
      showText = showText + monthAry[valDate.getMonth()].name + " " + valDate.getDate();
      if(this.translate.getDefaultLang()=='zh-CN')
        showText +=this.translate.get("common.day")["value"];
      showText +=', ';
    }

    if (AppConfig.timeFormat == 24)//24小时制时间
    {
      //显示时间补足两位
      if (valDate.getHours() < 10)
        showText += "0" + valDate.getHours();
      else showText += valDate.getHours().toString();
      if (valDate.getMinutes() < 10)
        showText += ":0" + valDate.getMinutes();
      else showText += ":" + valDate.getMinutes();
      showText += ", ";

      //获取灌溉时间
      if (args[0]) {
        let runAry = args[0].toString().split(":");
        let min = parseInt(runAry[0]) * 60 + parseInt(runAry[1]);
        let sec = parseInt(runAry[2]);
        if (min > 0) {
          showText += min + " " + this.translate.get("common.min")["value"] + " ";
        }
        if (sec > 0) {
          showText += sec + " " + this.translate.get("common.sec")["value"]+" ";
        }
      }
    }
    else //12小时制时间
    {

      let hour = valDate.getHours();
      // 显示时间-获取24进制的时间通过 12 进制的时间进行显示
      let am = this.translate.get("common.am")["value"];
      let pm = this.translate.get("common.pm")["value"];
      let timeMin=valDate.getMinutes();
      let timeMinS=timeMin<10?"0"+timeMin:timeMin.toString();
      if(hour==0){
        showText += "12:" + timeMinS + " " + pm+", ";
      }
      else if (hour>=0&&hour < 12) {
        showText += hour + ":" + timeMinS + " " + am+", ";
      } else if (hour >= 12 && hour < 24) {
        hour -= 12;
        showText += hour + ":" + timeMinS + " " + pm+", ";
      }
      //获取灌溉时间
      if (args[0]) {
        let runAry = args[0].toString().split(":");
        let min = parseInt(runAry[0]) * 60 + parseInt(runAry[1]);
        let sec = parseInt(runAry[2]);
        if (min > 0) {
          showText += min + " " + this.translate.get("common.min")["value"] + " ";
        }
        if (sec > 0) {
          showText += sec + " " + this.translate.get("common.sec")["value"];
        }
      }
    }
    return showText;
  }

}




