import {NavController, NavParams} from 'ionic-angular';
import {Component} from '@angular/core';
import {CommandFactory} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";


declare var $: any;

@Component({
  selector: 'selector-settingBttsLastChangeBatteryTime',
  templateUrl: 'settingBttsLastChangeBatteryTime.html'
})

export class SettingBttsLastChangeBatteryTimePage {
  pandaLoading: any = null;
  connectedDevice: any = null;

  constructor(public navCtrl: NavController, private  navParams: NavParams, private  commandFactory: CommandFactory, private translate: TranslateService) {

  }

  ionViewWillEnter() {
  }

  ionViewDidEnter() {

  }

  getValue() {
    //返回的为数组
    return $('#pageColpicker').coolpicker('getValue');
  }

  ionViewDidLoad() {
    let self = this;
    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }
    let changedate = localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "last_change_battery_date")
    let yearList: any = [];
    let newyear = new Date();
    let currentDate = new Date();
    if (changedate == null) {
      currentDate = new Date();
    } else {
      let j = JSON.parse(changedate)
      currentDate = new Date(j.year + '-' + j.month + '-' + j.day);
    }
    for (let i = 0; i <= 2; i++) {
      yearList.push(newyear.getFullYear() - i);
    }
    yearList.push("");


    let pickerAry = [];
    let colAry = self.getMonthDays(currentDate);
    pickerAry.push(colAry);

    let monthAry = self.commandFactory.getMonth();
    let month = [];
    monthAry.forEach((v) => {
      month.push(v.name);
    });

    month.unshift(self.translate.get("common.notSet")["value"])
    //有选择性的传入每列数组数据，先插入的先显示
    $('#pageColpicker').coolpicker({
      onRollCompleted: function (columnIndex, value) {
        AppConfig.consoleLog('column:' + columnIndex + ',value:' + value);
        if (columnIndex == 0) {
          let timeS = self.getValue();
          let chayear = new Date();
          if (timeS[0] == "") {
            $('#pageColpicker').coolpicker('setValue', ["1", month[1], chayear.getFullYear()]);
          }
        } else if (columnIndex == 1) {
          let timeS = self.getValue();
          let chayear = new Date();
          if (value != "" && timeS[2] == "") {
            timeS[2] = chayear.getFullYear();
          }
          let curDateS = timeS[2] + "-" + self.getSelectMonth(timeS[1]) + "-1";
          colAry = self.getMonthDays(curDateS);
          pickerAry.push(colAry)
          colAry.push("");
          $('#pageColpicker').coolpicker(
            'loadData',
            [
              colAry,
              month,
              yearList
            ]
          );
          if (value == "没有设置" || value == "NOT SET") {
            timeS[0] = "";
            timeS[2] = "";
            //设置选择值
            $('#pageColpicker').coolpicker('setValue', [timeS[0], timeS[1], timeS[2]]);
          } else {
            //设置选择值
            $('#pageColpicker').coolpicker('setValue', ["1", timeS[1], timeS[2]]);
          }
        } else if (columnIndex == 2) {
          let timeS = self.getValue();
          let chayear = new Date();
          if (timeS[2] == "") {
            $('#pageColpicker').coolpicker('setValue', ["1", month[1], chayear.getFullYear()]);
          } else {
            $('#pageColpicker').coolpicker('setValue', ["1", month[1], timeS[2]]);
          }
        }
      },
      columnSpace: 15
    }).coolpicker(
      'loadData',
      [
        colAry,
        month,
        yearList
      ]
    );
    //设置选择值
    $('#pageColpicker').coolpicker('setValue', [currentDate.getDate(), month[currentDate.getMonth() + 1], currentDate.getFullYear().toString()]);

  }

  saveData() {
    let self = this;
    let timeS = self.getValue();
    let notSet = self.translate.get("common.notSet")["value"]
    if (timeS[1] == notSet) {
      localStorage.removeItem(self.connectedDevice["address"].replace(/:/g, '') + "last_change_battery_date");
    } else {
      let dayS = timeS[0];
      let monthS = "1";
      if (parseInt(timeS[0]) < 10) dayS = "0" + timeS[0];
      monthS = self.getSelectMonth(timeS[1]);

      localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') + "last_change_battery_date", JSON.stringify({
        year: timeS[2],
        month: monthS,
        day: dayS
      }));
    }

    self.goBack();
  }

  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    });
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }

  getSelectMonth(v) {
    let monthAry = this.commandFactory.getMonth();
    let monthS = "1";
    for (let i = 0; i < monthAry.length; i++) {
      if (v == monthAry[i].name) {
        monthS = monthAry[i].val.toString();
        break;
      }
    }
    return monthS;
  }

  //获取当前月天数
  getMonthDays(matchDate) {
    let currentMonthLast = this.getCurrentMonthLast(matchDate);
    let monthLastDate = new Date(currentMonthLast).getDate();
    let monthDays = [];
    for (let i = 1; i <= monthLastDate; i++) {
      monthDays.push(i.toString());
    }

    return monthDays;
  }

  //获取当月最后一天
  getCurrentMonthLast(matchDate) {
    let date = null;
    if (typeof (matchDate) == "string")
      date = new Date(matchDate);
    else date = matchDate;

    let currentMonth = date.getMonth();
    let nextMonth = ++currentMonth;
    let nextMonthFirstDay = new Date(date.getFullYear(), nextMonth, 1);
    let oneDay = 1000 * 60 * 60 * 24;
    let lastTime = new Date(nextMonthFirstDay.getTime() - oneDay);
    let month = lastTime.getMonth() + 1;
    let day = lastTime.getDate();

    return date.getFullYear() + '-' + month + '-' + day;
  }

  goBack() {
    this.navCtrl.pop();
  }

}



