import {NavController, IonicModule, Platform} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {Component, OnInit, ChangeDetectorRef} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {TranslateService} from "ng2-translate";
import {CommandFactory} from "../../../util/CommandFactory";
import {AppConfig} from "../../../app/appconfig";
// import {browserDetection} from "@angular/platform-browser/testing/src/browser_util";
// import {getSystemData} from "@ionic/app-scripts";

declare var $: any;

@Component({
  selector: 'selector-settingWateringPlan',
  templateUrl: 'settingWateringPlan.html'
})

export class settingWateringPlanPage {
  public showMore: boolean = false;
  public entpList: any = [];
  PageSize = 10;
  PageIndex = 1;
  eiPageCount = 0;
  imgbar = 0;
  dataLs: any;
  public list = [
    // {templateName: "Watering  plan 1", isChecked: true, templateId: 1},
    // {templateName: "Watering  plan 2", isChecked: false, templateId: 2},
    // {templateName: "Watering  plan 3", isChecked: false, templateId: 3},
    // {templateName: "Watering  plan 4", isChecked: false, templateId: 4},
    // {templateName: "Watering  plan 5", isChecked: false, templateId: 5},
    // {templateName: "Watering  plan 6", isChecked: false, templateId: 6},
    // {templateName: "Watering  plan 7", isChecked: false, templateId: 7},
    // {templateName: "Watering  plan 8", isChecked: false, templateId: 8},
    // {templateName: "Watering  plan 9", isChecked: false, templateId: 9},
    // {templateName: "Watering  plan 10", isChecked: false, templateId: 10},
  ];


  public currentUserInfo: any = {};

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController, public cd: ChangeDetectorRef, private translate: TranslateService, private  commandFactory: CommandFactory) {

  }

  ionViewWillEnter() {


    let self = this;
    self.nativeService.queryDeviceTemplateData("", "", (r) => {
      AppConfig.consoleLog(r);
      let res = r;
      for (let i = 0; i < res.rows.length; i++) {
        let templateobj: any = {
          templateName: "",
          isChecked: 1,
          templateId: ""
        }
        templateobj.templateName = res.rows[i].templateName;
        templateobj.isChecked = res.rows[i].isChecked == 0 ? false : true;
        templateobj.templateId = res.rows[i].templateId;
        this.list.push(templateobj);
      }
    })


    // if (localStorage.getItem("homePageTypeId")) {
    //   let localtypeId = JSON.parse(localStorage.getItem("homePageTypeId"));
    //   self.list.forEach((item) => {
    //     if (item.templateId == localtypeId) item.isChecked = true;
    //     else item.isChecked = false;
    //   });
    // }
  }

  ionViewDidEnter() {
    //初始化数据
    let self = this;
    if (localStorage.getItem("local_waring_msg")) {
      self.dataLs = localStorage.getItem("local_waring_msg");
    }
  }

  checkIitem(row) {
    let self = this;
    if (row.isChecked) return;
    row.isChecked = true;

    self.list.forEach((item) => {
      if (row.templateId != item.templateId) {
        if (item.isChecked)
          item.isChecked = false;
      }
    });
    //self.cd.detectChanges();
    self.nativeService.detectChanges(self.cd);
  }

  save() {
    let self = this;
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
    for (let i = 0; i < self.list.length; i++) {
      if (self.list[i].isChecked) {
        //保存到homePageTypeId
        self.nativeService.updateDeviceTemplateData(updateTime, self.list[i].templateId, self.list[i].templateName, 1, (r) => {
          AppConfig.consoleLog(r);
        })
        let typeID = JSON.stringify(self.list[i].templateId);
        localStorage.setItem("homePageTypeId", typeID);

        //region 定时 循环 时间设置 8个时间设置
        //站点1 Second_87 定时前4个时间
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_87' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_87", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });

        //站点1 Second_A0 定时后4个时间
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_A0' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_A0", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });


        //站点1 Second_88 循环
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_88' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_88", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });
        //站点2 Second_8c 定时前4个时间
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_8c' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_8c", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });
        //站点2 Second_A1 定时后4个时间
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_A1' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_A1", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });
        //站点2 Second_8d 循环
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_8d' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_8d", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });
        //endregion


        self.nativeService.queryDeviceBasicData("*", "pageName='SeasonalAdjustmentPage' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("SeasonalAdjustmentPage", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                  //localStorage.setItem("Second_9C", r.rows[0].jsonDate);
                });
            }
          }
        });


        //浇灌日 定时
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_86' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_86", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                  //localStorage.setItem("Second_9C", r.rows[0].jsonDate);
                });
            }
          }
        });

        //浇灌日 循环
        self.nativeService.queryDeviceBasicData("*", "pageName='Second_8b' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("Second_8b", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                  //localStorage.setItem("Second_9C", r.rows[0].jsonDate);
                });
            }
          }
        });

        //region 浇灌比例
        //比例 OverallAdjustment 全年
        self.nativeService.queryDeviceBasicData("*", "pageName='OverallAdjustment' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("OverallAdjustment", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });


        //比例 SeasonalAdjustmentPage 月份
        self.nativeService.queryDeviceBasicData("*", "pageName='SeasonalAdjustmentPage' and typeId = " + typeID + "", (r) => {
          if (r.result > 0) {
            if (r.rows.length > 0) {
              AppConfig.consoleLog(r);
              self.commandFactory.editCommand2(JSON.parse(r.rows[0].jsonDate));
              self.commandFactory.send_2("SeasonalAdjustmentPage", JSON.parse(r.rows[0].jsonDate))
                .then((success) => {
                  AppConfig.consoleLog(success)
                });
            }
          }
        });
        //endregion

      } else {
        //region MonthlyAdjustment 月度调整 OverallAdjustment 整体调整
        //修改所有状态为false
        self.nativeService.updateDeviceTemplateData(updateTime, self.list[i].templateId, self.list[i].templateName, 0, (r) => {
          AppConfig.consoleLog(r);
        })
      }
    }
    // document.location.reload();
    self.goBack();
  }

  goBack() {
    let self = this;
    this.navCtrl.pop();
  }

  goHome() {
    let self = this;
    self.commandFactory.disConnect().then(
      (success) => {
        AppConfig.consoleLog(success);
        if (localStorage.getItem("local_device_list")) {
          let deviceList = JSON.parse(localStorage.getItem("local_device_list"));
          deviceList.forEach((v) => {
            v["connected"] = false;
          });
          localStorage.setItem("local_device_list", JSON.stringify(deviceList));
        }

        this.navCtrl.parent.select(0);
        this.navCtrl.popToRoot();
      }, (error) => {
        AppConfig.consoleLog(error);
      });

  }

}



