import {NavController, NavParams} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {ChangeDetectorRef, Component} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {SettingStationNamePage} from "../settingStationName/settingStationName";
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";


declare var $: any;

@Component({
  selector: 'selector-settingBttsSuspendTime',
  templateUrl: 'settingBttsSuspendTime.html'
})

export class SettingBttsSuspendTimePage {
  pandaLoading: any = null;

  constructor(public navCtrl: NavController, private  navParams: NavParams, private  commandFactory: CommandFactory, private translate: TranslateService) {

  }

  ionViewWillEnter() {
  }

  ionViewDidEnter() {

  }

  getValue() {
    //返回的为数组
    return $('#pageColpicker').coolpicker('getValue');
  }

  ionViewDidLoad() {
    let self = this;
    let pickerAry = [];
    let colAry = [];
    let notSet = self.translate.get("msg.close")["value"]
    let tranday = self.translate.get("common.day")["value"]
    let tranday1 = self.translate.get("common.day1")["value"]
    let trandays = self.translate.get("common.day2")["value"]
    let tempDay = "";
    for (let i = 0; i <= 99; i++) {
      if (i == 0) colAry.push(notSet);
      else colAry.push(i.toString());
    }
    pickerAry.push(colAry);

    let Second_83 = self.commandFactory.getCommand(ProtocolType.Second_82);
    if (Second_83.suspendWatering == 0) {
      tempDay = "";
    } else if (Second_83.suspendWatering == 1) {
      tempDay = tranday1;
    } else {
      tempDay = trandays;
    }
    $('#pageColpicker').coolpicker({
      columnSpace: 0,
      onRollCompleted: function (columnIndex, value) {
        AppConfig.consoleLog('column:' + columnIndex + ',value:' + value);
        if (columnIndex == 0) {
          let timeS = self.getValue();
          if (value == "") {
            tempDay = "";
          } else if (value == notSet) {
            tempDay = "";
          } else if (value == 1) {
            tempDay = tranday1;
          } else {
            tempDay = trandays;
          }
          $('#pageColpicker').coolpicker(
            'loadData',
            [
              pickerAry[0],
              [tempDay]
            ]
          )
          $('#pageColpicker').coolpicker('setValue', [value, tempDay]);
        }
      }
    }).coolpicker(
      'loadData',
      [
        pickerAry[0],
        [tempDay]
      ]
    )
    $('#pageColpicker').coolpicker('setValue', [colAry[Second_83.suspendWatering], tempDay]);

  }

  saveData() {
    let self = this;
    self.showPandaLoading();
    let timeS = self.getValue();
    AppConfig.consoleLog(timeS);
    let notSet = self.translate.get("msg.close")["value"]
    let Second_83 = self.commandFactory.getCommand(ProtocolType.Second_83);
    let evl = 0;
    if (timeS[0] == notSet) {
      evl = 0;
    } else evl = parseInt(timeS[0]);
    Second_83.suspendWatering = evl;
    Second_83.specialSetting = 0;

    self.commandFactory.editCommand2(Second_83);

    let Second_82 = self.commandFactory.getCommand(ProtocolType.Second_82);
    Second_82.suspendWatering = evl;
    self.commandFactory.editCommand2(Second_82);

    self.commandFactory.send_2("SettingBttsSuspendTimePage", Second_83).then(
      (success) => {
        AppConfig.consoleLog(success);
        self.hidePandaLoading();
        self.goBack();
      }, (error) => {
        AppConfig.consoleLog(error);
        self.hidePandaLoading();
      }
    )
  }

  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    });
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }

  goBack() {
    this.navCtrl.pop();
  }

}



