import {NavController, IonicModule} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {Component, OnInit, ChangeDetectorRef} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";
import {CommandFactory} from "../../../util/CommandFactory";

declare var app: any;

@Component({
  selector: 'selector-languageSetting_1',
  templateUrl: 'languageSetting_1.html'
})

export class LanguageSettingPage_1 {
  public showMore: boolean = false;
  public entpList: any = [];
  PageSize = 10;
  PageIndex = 1;
  eiPageCount = 0;
  dataLs: any;
  public list = [];

  public currentUserInfo: any = {};

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController, public cd: ChangeDetectorRef, private translate: TranslateService, private  commandFactory: CommandFactory) {

  }

  ionViewWillEnter() {
    //this.serach();
    let self = this;
    this.list = AppConfig.languages;
    if (localStorage.getItem("local_lang")) {
      let localLang = JSON.parse(localStorage.getItem("local_lang"));
      self.list.forEach((item) => {
        if (item.code == localLang.code) item.isChecked = true;
        else item.isChecked = false;
      });
    } else {
      let defCode = self.translate.getDefaultLang();
      for (let i = 0; i < self.list.length; i++) {
        if (self.list[i].code == defCode) {
          self.list[i].isChecked = true;
          localStorage.setItem("local_lang", JSON.stringify(self.list[i]));
          self.translate.setDefaultLang(self.list[i].code);
          break;
        }
      }
    }
  }

  ionViewDidEnter() {
    //this.navParams.get("")
    //初始化数据
    let self = this;
    if (localStorage.getItem("local_waring_msg")) {
      self.dataLs = localStorage.getItem("local_waring_msg");
    }
  }

  checkIitem(row) {
    let self = this;
    if (row.isChecked) return;
    row.isChecked = true;

    self.list.forEach((item) => {
      if (row.code != item.code) {
        if (item.isChecked)
          item.isChecked = false;
      }
    });

    //self.cd.detectChanges();
    self.nativeService.detectChanges(self.cd);
  }

  save() {
    let self = this;
    for (let i = 0; i < self.list.length; i++) {
      //if(self.list[i].isChecked&&(self.list[i].code=="zh-CN"||self.list[i].code=="en")){
      if (self.list[i].isChecked) {
        localStorage.setItem("local_lang", JSON.stringify(self.list[i]));
        self.translate.setDefaultLang(self.list[i].code);
        break;
      }
    }
    //document.location.reload();
    self.goHome();
  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }

  goHome() {
    let self = this;
    app.autoTabGo(
      self.navCtrl,
      AppConfig.runInfo['selectOnlineDevice'],
      AppConfig.runInfo['selectOfflineDevice'],
      AppConfig.runInfo['isTwoMode'],
      AppConfig.runInfo['isOnline'],
      0,
      true, null, null, null,
      AppConfig.runInfo['thisversion'],
      AppConfig.runInfo['thisversiontype']
    );
    // this.navCtrl.parent.select(0);
    // this.navCtrl.popToRoot();
  }

}



