import {flatMap} from "rxjs/operators";

export class AppConfig {
  //获取设备高度
  public static getWindowHeight() {
    return window.screen.height;
  }

  //获取设备宽度
  public static getWindowWidth() {
    return window.screen.width;
  }

  //region 升级相关

  //当Apk版本获取不到时，默认的版本号
  public static apkVersion: string = "5.0.0";
  //apk指定升级编码
  public static upgradeApkCode: string = "apk-01";
  //当固件版本获取不到时，默认的版本号
  public static firmwareVersion: string = "0.0.0.0";
  //mcu指定升级编码
  public static upgradeFirmwareCode: string = "fw-01";

  //endregion

  //region 远程配置相关

  //环境
  public static siteUrl = "http://ais.hyruanjian.cn";       //正式
  public static testSiteUrl = "http://ais.hyruanjian.cn";  //测试

  //app下载页面
  public static apkDownloadUrl = AppConfig.GetInterFaceUrl() + 'app/download.html';

  //获取站点app下载地址
  public static GetSiteApkUrl() {
    if (this.isDebug == true) {
      return this.testSiteUrl;
    } else {
      return this.siteUrl;
    }
  }

  //是否自动链接
  public static Connection_tips = false;
  //已经显示提示是否连接弹出框
  public static showConfirm = false;

  //全部暂停 --只提示一次，取消完成后的提示
  public static IsallShow = false;
  //全部暂停 --只提示一次，取消完成后的提示
  public static IsallShowzone1 = false;
  //全部暂停 --只提示一次，取消完成后的提示
  public static IsallShowzone2 = false;

  public static zutotime1: any = 0;
  public static zutotime2: any = 0;
  public static zone1newId: any = 0;
  public static zone2newId: any = 0;
  public static zutotimetemp1: any = 0;
  public static zutotimetemp2: any = 0;
  public static zone1newIdtemp: any = 0;
  public static zone2newIdtemp: any = 0;


  //存储设备当前模式  单口应用
  public static onedingshiMode: any = null;
  public static onexunhuanMode: any = null;

  //记录是否输出站点浇水提示
  public static zone1showmes: any = false;
  public static zone2showmes: any = false;

  public static loadFinish: any = true;


  //默认读取间隔一次
  public static zone1interval: any = false;
  public static zone2interval: any = false;
  public static zone1Loop: any = false;
  public static zone2Loop: any = false;
  //首先计算下次灌溉天数,只进入一种
  //定时
  public static NextInterval: any = false;
  //循环
  public static NextLoop: any = false;

  public static runstopAll: any = false;
  //设备连接超时时间
  public static connectTimeout: number = 20 * 1000;

  //当片本获取不到时，默认的版本号
  public static version: string = "1.0";

  //获取请求接口地址
  public static GetInterFaceUrl() {
    if (this.isDebug == true) {
      return this.testSiteUrl + "/";
    } else {
      return this.siteUrl + "/";
    }
  }

  //运行信息
  public static runInfo = {
    timer: {
      'monitor.device.rssi': null,          //监控设备device rssi变化
      'start.device.scan': null,            //开始蓝牙设备扫描
      'search.device': null,                //获取搜索设备
      'connect.progress.update': null,      //连接进度更新
      'realtime.get.prev.next': null,       //监控设备上一条下一条数据
      'timelist.9d': null,        //监控设备上一条下一条数据
      'zone1showmes': null,        //启动浇水提示
      'zone2showmes': null        //启动浇水提示
    },

    disConnectedToHomePage: false,          //断开连接退出到设备搜索页
    reqManualTriggerLoadLog: false,         //需要手动触发加载日志
    isTwoMode: 1,                           //设备模式 1为双口 0为单口  默认为双口模式
    isOnline: 0,                            //设备在线 0为离线 1为在线
    selectOnlineDevice: null,               //选择的在线设备
    selectOfflineDevice: null,              //选择的离线设备
    thisversion: null,                      //>3 新版 <3 旧版
    thisversiontype: null,                  //默认1C新版单口，2C新版双口
    showverification: null                 //提示验证功能
  };

  public static delconnectInit: any = 0;

  //endregion

  //所有语言集
  public static languages = [
    {name: "Afrikaans", val: "Afrikaans", isChecked: false, code: "af"},//南非荷兰语
    {name: " العربية", val: "Arabic", isChecked: false, code: "ar"},//阿拉伯语
    {name: "Английски", val: "Bulgarian", isChecked: false, code: "bg"},//保加利亚语
    {name: "中国", val: "Chinese", isChecked: true, code: "zh-CN"},//中文
    {name: "Čeština", val: "Czech", isChecked: false, code: "cs"},//捷克语
    {name: "Deutsch", val: "German", isChecked: false, code: "de"},//德语
    {name: "English", val: "U.S", isChecked: false, code: "en"},//英语
    {name: "Español", val: "Spanish", isChecked: false, code: "es"},//西班牙语
    {name: "Français", val: "French", isChecked: false, code: "fr"},//法语
    {name: "Ελληνικά", val: "Greek", isChecked: false, code: "el"},//希腊语
    {name: "עברית", val: "Hebrew", isChecked: false, code: "iw"},//希伯来语
    {name: "Magyar", val: "Hungarian", isChecked: false, code: "hu"},//匈牙利语
    {name: "Nederlands", val: "Dutch", isChecked: false, code: "nl"},//荷兰语 nl
    {name: "Italiano", val: "Italian", isChecked: false, code: "it"},//意大利语
    {name: "Polski", val: "Polish", isChecked: false, code: "pl"},//波兰语
    {name: "Português", val: "Portuguese", isChecked: false, code: "pt"},//葡萄牙语
    {name: "Romana", val: "Romanian", isChecked: false, code: "ro"},//罗马尼亚语
    {name: "Pусский", val: "Russian", isChecked: false, code: "ru"},//俄语
    {name: "Türkçe", val: "Turkish", isChecked: false, code: "tr"},//土耳其语
    {name: "Svenska", val: "Swedish", isChecked: false, code: "sv"},//瑞典
  ];

  //标识是否为测试环境
  public static isDebug: boolean = false;
  //判断第一次登录
  public static firstLogin: boolean = false;
  //标识是否为对接设备
  public static isDockingMachine: boolean = true;
  //默认语言
  public static lang: string = "en";
  //默认时间制式24小时制
  public static timeFormat = 24;

  //控制日志输出，false:不输出 true:输出
  //日志输出在ts，引入AppConfig类，并调用AppConfig.ConsoleLog或AppConfig.ConsoleDir, html页面中调用使用 app.ConsoleLog和app.ConsoleDir
  public static enableLogOutput: boolean = false;

  /**
   * js console 输出日志
   * @param info
   * @constructor
   */
  public static consoleLog(...info: any[]) {
    if (this.enableLogOutput)
      console.log(info);
  }

  /**
   * js console 打印对象
   * @param info
   * @constructor
   */
  public static consoleDir(info) {
    if (this.enableLogOutput)
      console.dir(info);
  }

  //endregion
}



