import {NavController, NavParams} from 'ionic-angular';
import {ChangeDetectorRef, Component} from '@angular/core';
import {DatePicker} from 'ionic-native';
import {ManualOperationTimeDetailTimePage} from "../manualOperationTimeDetailTime/manualOperationTimeDetailTime";
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {AppConfig} from "../../../app/appconfig";
import {TranslateService} from "ng2-translate";

@Component({
  selector: 'selector-SitePage',
  templateUrl: 'manualOperationTime.html'
})

export class ManualOperationTimePage {
  //当前单双口情况
  thisVersionType: any = '1C';//默认1C单口，2C为双口
  //当前版本
  thisVersion: any = null;
  site1Name;
  site2Name;

  connectedDevice: any = null;

  constructor(
    public navCtrl: NavController,
    public cd: ChangeDetectorRef,
    public  NavParams: NavParams,
    private commandFactory: CommandFactory,
    private translate: TranslateService
  ) {
  }

  switchModelIndex = 0;

  selectedDsq() {
    this.switchModelIndex = 0;
    document.getElementById("Adsq").setAttribute("class", "mySwitchControlSelectdItem");
    document.getElementById("Axh").setAttribute("class", "");
  }

  selectedXh() {
    this.switchModelIndex = 1;
    document.getElementById("Axh").setAttribute("class", "mySwitchControlSelectdItem");
    document.getElementById("Adsq").setAttribute("class", "");
  }

  zone1Runing: boolean = false;
  zone2Runing: boolean = false;


  ionViewWillEnter() {
    let self = this;
    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }

    self.thisVersion = self.connectedDevice.thisversion;
    self.thisVersionType = self.connectedDevice.thisversiontype;

    self.commandFactory.readRemote(ProtocolType.Second_82, (success_82) => {
      let res_82 = success_82;
      if (res_82.zone1State == 1) self.zone1Runing = false;
      else if (res_82.zone1State == 17) self.zone1Runing = true;
      else self.zone1Runing = res_82.zone1EnableManual;

      if (res_82.zone2State == 1) self.zone2Runing = false;
      else if (res_82.zone2State == 17) self.zone2Runing = true;
      else self.zone2Runing = res_82.zone2EnableManual;
    }, null, self.connectedDevice);


    if (self.thisVersion > 3) {
      //region 主页 对接机器获取阀口名称
      if (AppConfig.isDockingMachine) {
        let Second_90 = self.commandFactory.readlocalProtocol(ProtocolType.Second_90, self.connectedDevice);
        // self.commandFactory.read1(ProtocolType.Second_90, self.connectedDevice)
        //   .then((success) => {
        //     AppConfig.consoleLog("res.zoneName" + success);
        //     let res: any = success;
        if (Second_90.zoneName == "") {
          self.site1Name = self.translate.get("twoExport.twoSchedule.zone1")["value"];
        } else {
          self.site1Name = Second_90.zoneName;
        }
        // });
        let Second_91 = self.commandFactory.readlocalProtocol(ProtocolType.Second_91, self.connectedDevice);
        // self.commandFactory.read1(ProtocolType.Second_91, self.connectedDevice)
        //   .then((success) => {
        //     AppConfig.consoleLog(success);
        //     let res: any = success;
        if (Second_91.zoneName == "") {
          self.site2Name = self.translate.get("twoExport.twoSchedule.zone2")["value"];
        } else {
          self.site2Name = Second_91.zoneName;
        }
        // });
      }
    } else {
      // self.site1Name = self.translate.get("twoExport.twoSchedule.zone1")["value"];
      // self.site2Name = self.translate.get("twoExport.twoSchedule.zone2")["value"];

      self.site1Name = self.translate.get("twoExport.twoSchedule.zone1")["value"];
      if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")) {
        self.site1Name = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")).zone1;
      }
      self.site2Name = self.translate.get("twoExport.twoSchedule.zone2")["value"];
      if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")) {
        self.site2Name = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")).zone2;
      }
    }
  }

  goManualOperationTimeDetail(siteIndex) {
    //this.navCtrl.push(manualOperationTimeDetailPage, {siteIndex: siteIndex});
    this.navCtrl.push(ManualOperationTimeDetailTimePage, {siteIndex: siteIndex});
  }

  goBack() {
    this.navCtrl.pop();
  }
}



