import {App, NavController, Platform} from 'ionic-angular';
import {ChangeDetectorRef, Component} from '@angular/core';
import {HttpHelper} from "../../../util/HttpHelper";
import {NativeService} from "../../../util/NativeService";
import {LoginBttsPage_1} from "../loginBtts_1/loginBtts_1";
import {VersionBttsPage_1} from "../versionBtts_1/versionBtts_1";
import {BttVersion, CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {NavPage} from "../../common/nav/nav";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";


declare var cordova: any;
declare var $: any;

@Component({
  selector: 'selector-homeBtts_1',
  templateUrl: 'homeBtts_1.html'
})

export class HomeBttsPage_1 {
  public showMore: boolean = false;
  public entpList: any = [];
  PageSize = 10;
  PageIndex = 1;
  eiPageCount = 0;
  public currentUserInfo: any = {};
  deviceAry: any = [];
  deviceAryhistory: any = [];
  pandaLoading: any = null;
  isConnected: boolean = false;
  iscanNotConnect: boolean = false;

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper,
              public navCtrl: NavController, public cd: ChangeDetectorRef, public appCtrl: App,
              private platform: Platform, private  commandFactory: CommandFactory, private translate: TranslateService) {

  }

  ionViewDidLoad() {

  }

  ionViewWillEnter() {
  }

  ionViewDidEnter() {

  }

  ionViewWillLeave() {
    let self = this;
    if (self._timer) {
      AppConfig.consoleLog("关闭监控器");
      window.clearInterval(self._timer);
    }
  }

  goBack() {
    this.navCtrl.pop();
  }

  goLoginBtts() {
    this.navCtrl.push(LoginBttsPage_1);
  }

  goVersionBtts(address) {
    this.navCtrl.push(VersionBttsPage_1, {address: address});
  }



  _timer: any = null;
  _noConnectDevices: any = [];
  //不可连接数组
  _canNotConnect: any = [];
  _idx: number = -1;


  //连接蓝牙设备
  clickConnectBluetooth(address, skipProgress) {
    if (localStorage.getItem("ConnectAddr") == null) {
    } else {
      if (localStorage.getItem("ConnectAddr") != address) return;
    }
    AppConfig.consoleLog("开始连接");
    AppConfig.consoleLog("address:" + address);
    localStorage.setItem("ConnectAddr", address);
    let self = this;
    //self.clickCloseConnect(address);
    //self.showPandaLoading();

    self.commandFactory.stopSearch();
    self.commandFactory.disConnect(address).then(
      (success) => {
      },
      (error) => {
        AppConfig.consoleLog(error);
      }
    );
    if (!skipProgress) {
      //找对应索引
      self._idx = 0;
      if (self._noConnectDevices) {
        for (let i = 0; i < self._noConnectDevices.length; i++) {
          if (self._noConnectDevices[i].address == address) {
            self._idx = i;
            break;
          }
        }
      }

      self._noConnectDevices[self._idx].connecting = true;
      self._noConnectDevices[self._idx].connectCompleted = false;
      self._noConnectDevices[self._idx].progressValue = 0;
      if (self._timer) {
        window.clearInterval(self._timer);
        self._timer = null;
      }
      self._timer = window.setInterval(
        () => {
          if (self._noConnectDevices[self._idx].connectCompleted) {
            window.clearInterval(self._timer);
            self._noConnectDevices[self._idx].progressValue = 100;
            AppConfig.consoleLog("已完成");
          } else {
            var v = self._noConnectDevices[self._idx].progressValue + Math.floor(1000 * 100 / AppConfig.connectTimeout);
            if (v > 100) {
              v = 0;
            }
            //更新进度值
            self._noConnectDevices[self._idx].progressValue = v;
            AppConfig.consoleLog("进度值：" + self._noConnectDevices[self._idx].progressValue);
            //self.cd.detectChanges();
            self.nativeService.detectChanges(self.cd);
          }
        },
        1000
      );
    }


    self.commandFactory.connectDevice(address).then((success) => {
      window.clearInterval(self._timer);
      self._timer = null;
      self.isConnected = true;

      AppConfig.consoleLog(success)

      self.deviceAry = self.commandFactory.updateDeviceConnectState(address, true);

      //不可连接设备
      self._canNotConnect = [];
      if (localStorage.getItem("local_device_list_connected")) {
        self.deviceAryhistory = JSON.parse(localStorage.getItem("local_device_list_connected"));
        if (self.deviceAryhistory.length > 0) {
          for (let i = 0; i < self.deviceAryhistory.length; i++) {
            if (JSON.stringify(self.deviceAry).indexOf(JSON.stringify(self.deviceAryhistory[i].address)) < 0) {
              self._canNotConnect.push(self.deviceAryhistory[i]);
            }
          }
        }
      }
      if (self._canNotConnect.length > 0) {
        self.iscanNotConnect = true;
      }

      //未连接设备
      self._noConnectDevices = [];
      self.deviceAry.forEach(
        function (item) {
          if (item.connected) {
            self.isConnected = true;
          }
          if (!item.connected) {
            if (item.name.toString().indexOf("Spray") < 0) {
              item.connecting = false;
              item.connectCompleted = item.connected;
              item.progressValue = 0;
              self._noConnectDevices.push(item);
            }
          }
        }
      );

      let bttTypeS: string = self.commandFactory.findDeviceByAttr("address", address).type;
      AppConfig.consoleLog(bttTypeS);
      if (bttTypeS == "Second") {
        localStorage.removeItem("ConnectAddr");
        self.connectTwoInit();
      } else if (bttTypeS == "First") {
        localStorage.removeItem("ConnectAddr");
        self.connectOneInit();
      }

    }, (error) => {
      AppConfig.consoleLog(error);
      if (error.result == -1) {
        //未建立连接时清除定时器，等待下次点击连接
        self.clickCloseConnect(self._noConnectDevices[self._idx].address);
        //重置
        self._noConnectDevices[self._idx].progressValue = 0;
        self._noConnectDevices[self._idx].connecting = false;
        self._noConnectDevices[self._idx].connectCompleted = true;
        //清除定时器
        if (self._timer) {
          window.clearInterval(self._timer);
          self._timer = null;
        }
      } else {
        //已建立连接时出错后自动重连
        self.clickConnectBluetooth(address, true);
      }

      // self._noConnectDevices[self._idx].connecting=false;
      // self._noConnectDevices[self._idx].connectCompleted=true;
      // window.clearInterval(self._timer);
      // self._timer=null;
      // let content=self.translate.get("msg.noDeviceContent")["value"];
      // let title=self.translate.get("msg.noDeviceTitle")["value"];
      // self.commandFactory.showAlert(content,title);
    });
  }

  connectOneInit() {
    let self = this;
    // self.goSchedule(BttVersion.First);
    // if(1==1)return;
    self.showPandaLoading();
    //First_c4
    self.commandFactory.readRemote(ProtocolType.First_c4,
      (success_c4) => {
        AppConfig.consoleLog(success_c4);

        let newDate = new Date(new Date().getTime() + 1 * 1000);
        let res_read = success_c4;
        res_read.hour = newDate.getHours();
        res_read.minute = newDate.getMinutes();
        res_read.second = newDate.getSeconds();
        res_read.week = self.commandFactory.getWeekDays2()[newDate.getDay()].val;
        self.commandFactory.editCommand2(res_read);
        self.commandFactory.send_2("home_btts", res_read).then(
          (success_send) => {
            AppConfig.consoleLog(success_send);
          });

        let First_c2 = self.commandFactory.getCommand(ProtocolType.First_c2);
        let First_c3 = self.commandFactory.getCommand(ProtocolType.First_c3);
        if (First_c2.currentMode > 0) {
          First_c3.selectMode = First_c2.currentMode - 1
          self.commandFactory.send_2("homeBtts_1", First_c3).then(
            (success_c3) => {
              AppConfig.consoleLog(success_c3);
            });
        }


        setTimeout(() => {
          self.hidePandaLoading();
          self.goSchedule(BttVersion.First);
        }, 500);
      }, (error_c4) => {
        AppConfig.consoleLog(error_c4);
      });
  }

  connectTwoInit() {
    let self = this;
    self.showPandaLoading();
    //Second_84 初始化时间
    let Second_84 = self.commandFactory.getCommand(ProtocolType.Second_84);
    let newDate = new Date(new Date().getTime() + 1 * 1000);
    Second_84.year = newDate.getFullYear();
    Second_84.month = newDate.getMonth() + 1;
    Second_84.day = newDate.getDate();

    Second_84.hour = newDate.getHours();
    Second_84.minute = newDate.getMinutes();
    Second_84.second = newDate.getSeconds();
    Second_84.week = self.commandFactory.getWeekDays2()[newDate.getDay()].val;

    self.commandFactory.send_2("init_time_information", Second_84)
      .then((success_84) => {
        AppConfig.consoleLog(success_84);
        self.commandFactory.editCommand2(Second_84);
      });
    self.commandFactory.readRemote(ProtocolType.Second_82, (success_82) => {
      let res_82 = success_82;
      self.commandFactory.readRemote(ProtocolType.Second_83, (success_83) => {
        let res_83 = success_83;
        let Second_82 = self.commandFactory.getCommand(ProtocolType.Second_82);
        res_83.zone1Mode = Second_82.zone1Mode;
        res_83.zone2Mode = Second_82.zone2Mode;

        if (!localStorage.getItem("system_setting_switch")) {
          res_83.enabled = true;
          res_83.zone1Enabled = true;
          res_83.zone2Enabled = true;
        } else {
          let system_setting_switch = JSON.parse(localStorage.getItem("system_setting_switch"));
          res_83.enabled = system_setting_switch.enabled;
          res_83.zone1Enabled = system_setting_switch.zone1Enabled;
          res_83.zone2Enabled = system_setting_switch.zone2Enabled;
        }
        if (res_82.zone1State == 17 || res_82.zone2State == 5)
          res_83.zone1EnableManual = true;
        else res_83.zone1EnableManual = false;
        if (res_82.zone2State == 17 || res_82.zone2State == 5)
          res_83.zone2EnableManual = true;
        else res_83.zone2EnableManual = false;

        if (res_82.zone1State != 17 && res_82.zone2State != 17)
          res_83.specialSetting = 0;
        self.hidePandaLoading();
        self.commandFactory.send_2("system_init", res_83);
        setTimeout(() => {
          self.hidePandaLoading();
          self.goSchedule(BttVersion.Second);
        }, 500);
      });
    }, (error) => {
      AppConfig.consoleLog(error)
      self._noConnectDevices[self._idx].connecting = false;
      self._noConnectDevices[self._idx].connectCompleted = true;
      window.clearInterval(self._timer);
      self._timer = null;

      let content = self.translate.get("msg.noDeviceContent")["value"];
      let title = self.translate.get("msg.noDeviceTitle")["value"];
      self.commandFactory.showAlert(content, title);
    });

  }

  //断开连接
  clickCloseConnect(address: any = null) {
    let self = this;
    localStorage.removeItem("ConnectAddr");
    self.isConnected = false;

    self.deviceAry = self.commandFactory.updateDeviceConnectState(address, false);
    //未连接设备
    self._noConnectDevices = [];
    self.deviceAry.forEach(
      function (item) {
        if (item.name.toString().indexOf("Spray") < 0) {
          if (JSON.stringify(self._canNotConnect).indexOf(JSON.stringify(item.address)) < 0) {
            item.connecting = false;
            item.connectCompleted = item.connected;
            item.progressValue = 0;
            self._noConnectDevices.push(item);
          }
        }
      }
    );

    self.commandFactory.disConnect(address).then((success) => {
      AppConfig.consoleLog(success)
    }, (error) => {
      AppConfig.consoleLog(error);
    });
  }

  goSchedule(bttType: BttVersion = BttVersion.First) {
    let self = this;
    if (bttType == BttVersion.First) {
      this.navCtrl.parent.select(1);
      this.navCtrl.popToRoot();
    } else {
      self.appCtrl.getRootNavs()[0].setRoot(NavPage);
    }

  }

  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    });
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }




}



