  //把离线状态修改的数据存到 local_device_list.protocolList 中。
  editoffLineProtocolList = (cmdModel: any = null) => {
    let protocolList: any = [];
    let protocolOnLineList: any = [];
    let tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
    for (let i = 0; i < tempDevice.length; i++) {
      if (AppConfig.runInfo['selectOfflineDevice'] && tempDevice[i].address == AppConfig.runInfo['selectOfflineDevice']['address']) {
        if (tempDevice[i].protocolList == undefined) {
          protocolList.push(cmdModel);
          tempDevice[i].protocolList = protocolList;
          localStorage.setItem("local_device_list", JSON.stringify(tempDevice));
        } else {
          protocolList = tempDevice[i].protocolList;
          protocolOnLineList = tempDevice[i].protocolOnLineList;
          for (let q = 0; q < protocolList.length; q++) {
            if (protocolList[q].protocolType == cmdModel.protocolType) {
              protocolList.splice(q, 1);
              q = q - 1;
            }
          }
          protocolList.push(cmdModel);
          tempDevice[i].protocolList = protocolList;
          localStorage.setItem("local_device_list", JSON.stringify(tempDevice));

          for (let q = 0; q < protocolOnLineList.length; q++) {
            if (protocolOnLineList[q].protocolType == cmdModel.protocolType) {
              protocolOnLineList.splice(q, 1);
              q = q - 1;
            }
          }
          protocolOnLineList.push(cmdModel);
          tempDevice[i].protocolOnLineList = protocolOnLineList;
          localStorage.setItem("local_device_list", JSON.stringify(tempDevice));
        }
        break;
      }
    }
  }

