  /**
   * 插入日志并返回自增值
   */
  remoteAddLog(zone: string = null, log: string = null, updateTime: string = null, callback: any = null) {
    let me = this;
    let connectedDevice: any = null;
    if (AppConfig.runInfo["isOnline"] == 0) {
      connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }


    let thisversion: any = localStorage.getItem("thisversion");
    if (thisversion > 3) {
      if (typeof (callback) == 'function') {
        // callback({"result": 1, "message": "ok"});
        callback({"result":1,"message":"ok","rows":[0]});
      }
    } else {
      // if (localStorage.getItem("switchZoneMode")) {
      //   localStorage.removeItem("switchZoneMode");
      //   callback({"result": 1, "message": "ok"});
      // } else {
        me.nativeService.execInsertDataAndQueryNewId(
          'btt2', zone, log, connectedDevice.address, updateTime,
          function (result) {
            AppConfig.consoleLog(result);
            localStorage.setItem("btt2_" + zone + "_manual_log", JSON.stringify({
              btt: "btt2",
              zone: zone,
              log: log,
              mac: connectedDevice.address,
              updateTime: updateTime,
              id: result.rows[0].newId
            }));
            if (typeof (callback) == 'function') {
              callback(result);
            }
          }
        )
      // }
    }
  }

