  /**
   * 查询日志
   */
  remoteQueryLog(createTime: any = null) {
    let me = this;
    let connectedDevice: any = null;
    if (AppConfig.runInfo["isOnline"] == 0) {
      connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }

    if (connectedDevice) {
      return new Promise((resolve, reject) => {
        createTime = "createTime >='" + createTime + "'";
        me.nativeService.queryData(
          "", createTime + " and productName='btt2' and mac='" + connectedDevice.address + "' order by createtime",
          function (result) {
            resolve(result);
          }
        );
      });
    }
  }

