import {NavController} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {Component, OnInit} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {ChangeDetectorRef} from '@angular/core';
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";


@Component({
  selector: 'selector-settingStationBattery',
  templateUrl: 'settingStationBattery.html'
})

export class SettingStationBatteryPage {
  choiceItem: any = null;
  listBattery = [];
  connectedDevice: any = null;
  public currentUserInfo: any = {};

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController, public cd: ChangeDetectorRef, private translate: TranslateService) {
  }

  ionViewWillEnter() {
    let self = this;
    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"].address;
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"].address;
    }
    this.initBatteryChangeTips();
  }

  ionViewDidEnter() {
    //this.navParams.get("")
  }

  initBatteryChangeTips() {
    let self = this;
    self.listBattery.push({
      name: self.translate.get("more.settingStationBattery.group1Item1Name")["value"],
      checked: false,
      val: -1
    });
    self.listBattery.push({
      name: self.translate.get("more.settingStationBattery.group1Item2Name")["value"],
      checked: false,
      val: 3
    });
    self.listBattery.push({
      name: self.translate.get("more.settingStationBattery.group1Item3Name")["value"],
      checked: false,
      val: 6
    });
    self.listBattery.push({
      name: self.translate.get("more.settingStationBattery.group1Item4Name")["value"],
      checked: false,
      val: 9
    });
    if (localStorage.getItem(self.connectedDevice.replace(/:/g, '') + "btt2_setting_station_battery")) {
      let checkItem = JSON.parse(localStorage.getItem(self.connectedDevice.replace(/:/g, '') + "btt2_setting_station_battery"));
      for (let i = 0; i < self.listBattery.length; i++) {
        if (checkItem.val == self.listBattery[i].val) {
          self.listBattery[i].checked = true;
          break;
        }
      }
    } else {
      self.listBattery[0].checked = true;
    }
  }

  checkIitem(row) {
    AppConfig.consoleLog(row);
    let self = this;

    self.listBattery.forEach((item) => {
      if (row.val != item.val && row.checked) {
        if (item.checked)
          item.checked = false;
      }
    });

    //self.cd.detectChanges();
    self.nativeService.detectChanges(self.cd);

  }

  save() {
    let self = this;
    let checkItem = null;
    localStorage.removeItem(self.connectedDevice.replace(/:/g, '') + "btt2_setting_station_battery");
    for (let i = 0; i < self.listBattery.length; i++) {
      if (self.listBattery[i].checked && self.listBattery[i].val > 0) {
        let curDate = new Date();
        let tmpDate = new Date();
        checkItem = self.listBattery[i];
        AppConfig.consoleLog(checkItem);
        let lastDate = new Date(tmpDate.setMonth((tmpDate.getMonth() + self.listBattery[i].val)));
        let diffDay = lastDate.getDate() < curDate.getDate() ? lastDate.getDate() : 0;
        checkItem["expiretime"] = new Date(lastDate.getTime() - diffDay * 24 * 60 * 60 * 1000);
        localStorage.setItem(self.connectedDevice.replace(/:/g, '') + "btt2_setting_station_battery", JSON.stringify(checkItem));
        break;
      }
    }
    self.goBack();
  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }

}



