import {NavController, NavParams, Platform} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {ChangeDetectorRef, Component} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {SettingStationNamePage} from "../settingStationName/settingStationName";
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {SettingStationTimePage} from "../settingStationTime/settingStationTime";
import {ActionSheetController} from "ionic-angular";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";
import {ViewRef_} from "@angular/core/src/view";

declare const $: any;
declare var installNotify: any;
declare var cordova: any;
declare var installDispatch: any;

// declare var settingStationstate: any ;
// declare var settingStationtotalBytes: any;
// declare var settingStationcompleteBytes: any;

@Component({
  selector: 'selector-settingStation',
  templateUrl: 'settingStation.html'
})

export class SettingStationPage {
  className: string = "SettingStationPage";
  pandaLoading: any = null;
  public tempData: any = {
    zone: 0,
    zoneName: null,//站点名称
    bttsTime: "00:00:00",
    zoneEnabled: false,
  }
  site1Name: string = null;
  site2Name: string = null;
  curData: any = null;
  photoUrl = null;

  totalBytes = 0;
  completeBytes = 0;
  state = false;
  errMsg = "";
  deletepic: any = false;
  connectedDevice: any = null;

  //当前版本
  thisVersion: any = null;

  constructor(private platform: Platform, private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController,
              public cd: ChangeDetectorRef, private  navParams: NavParams, private  commandFactory: CommandFactory,
              public actionSheetCtrl: ActionSheetController, private translate: TranslateService) {
    //installNotify(this, this.onSettingStationNotifyReceive);
    installDispatch(this, this.onZoneImageReceiveCompleted, true);
  }

  /**
   * 主动接收到通知消息
   * @param me
   * @param protocol  json协议数据
   */
  onSettingStationNotifyReceive(me, protocol) {
    AppConfig.consoleLog(protocol);
    try {
      if (protocol && protocol.protocolType == "Second_94") {
        me.totalBytes = protocol.totalBytes;
        me.completeBytes = protocol.completeBytes;
        if (!me.state && protocol.state == 1) {
          me.state = true;
        }
        if (me.state && me.totalBytes == me.completeBytes) {
          me.state = false;

        }
      } else if (protocol && protocol.protocolType == "Second_97") {
        me.totalBytes = protocol.totalBytes;
        me.completeBytes = protocol.completeBytes;
        if (protocol.state == 1) {
          me.state = true;
        }
        if (me.totalBytes == me.completeBytes) {
          me.state = false;
        }
      }
    } catch (e) {
      AppConfig.consoleLog(e);
      AppConfig.consoleLog(me.state);
      AppConfig.consoleLog(me.errMsg);
    }
    if (me.cd !== null && me.cd !== undefined && !(me.cd as ViewRef_).destroyed) {
      me.cd.detectChanges();
    }
  }

  /**
   * 主动接收到通知消息
   * @param me
   * @param protocol  json协议数据
   */
  onZoneImageReceiveCompleted(me, protocol) {
    AppConfig.consoleLog(protocol);
    try {
      if (protocol && protocol.protocolType == "Second_94") {
        me.totalBytes = protocol.totalBytes;
        me.completeBytes = protocol.completeBytes;
        me.deletepic = false;
        if (!me.state && protocol.state == 1) {
          me.state = true;
        }
        if (me.state && me.totalBytes == me.completeBytes) {
          me.state = false;
          me.deletepic = true;
        }
      } else if (protocol && protocol.protocolType == "Second_97") {
        me.totalBytes = protocol.totalBytes;
        me.completeBytes = protocol.completeBytes;
        me.deletepic = false;
        if (protocol.state == 1) {
          me.state = true;
        }
        if (me.totalBytes == me.completeBytes) {
          me.state = false;
          me.deletepic = true;
        }
      }
    } catch (e) {
      AppConfig.consoleLog(e);
      AppConfig.consoleLog(me.state);
      AppConfig.consoleLog(me.errMsg);
    }
    if (me.cd !== null && me.cd !== undefined && !(me.cd as ViewRef_).destroyed) {
      me.cd.detectChanges();
    }
  }


  ionViewWillEnter() {
    let self = this;
    self.tempData.zone = self.navParams.get("zone");
    AppConfig.consoleLog(self.tempData.zone);
    self.commandFactory.setSessionId("settingStation");

    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }
    self.thisVersion = self.connectedDevice.thisversion;

    this.init();
  }

  ionViewDidEnter() {
    //初始化数据
    //this.init();
  }

  init() {
    let self = this;
    self.showPandaLoading();
    self.commandFactory.readRemote(ProtocolType.Second_82, (success) => {
      AppConfig.consoleLog(success)
      self.hidePandaLoading();
      let res = success;
      self.commandFactory.editCommand2(res);
      if (self.tempData.zone == 1) {
        self.tempData.zoneEnabled = res.zone1Enabled;

        let res_86 = self.commandFactory.readlocalProtocol(ProtocolType.Second_86, self.connectedDevice);

        // self.commandFactory.readRemote1(ProtocolType.Second_86, (success_86) => {
        //   AppConfig.consoleLog(success_86);
        //   let res_86 = success_86;
          self.commandFactory.editCommand2(res_86);
          self.tempData.bttsTime = res_86.zemHour + ":" + res_86.zemMinute + ":" + res_86.zemSecond;
       // }, null, self.connectedDevice);

      } else if (self.tempData.zone == 2) {
        self.tempData.zoneEnabled = res.zone2Enabled;

        let res_8b = self.commandFactory.readlocalProtocol(ProtocolType.Second_8b, self.connectedDevice);
        // self.commandFactory.readRemote1(ProtocolType.Second_8b, (success_8b) => {
        //   AppConfig.consoleLog(success_8b);
        //   let res_8b = success_8b;
          self.commandFactory.editCommand2(res_8b);
          self.tempData.bttsTime = res_8b.zemHour + ":" + res_8b.zemMinute + ":" + res_8b.zemSecond;
        //}, null, self.connectedDevice);
      }
    }, null, self.connectedDevice);


    if (self.tempData.zone == 1) {
      if (self.thisVersion > 3) {
        if (AppConfig.runInfo["isOnline"] == 0) {
          if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone1Name")) {
            self.tempData.zoneName = localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone1Name");
          } else {
            self.tempData.zoneName = self.translate.get("twoExport.twoSchedule.zone1")["value"];
          }
        } else {
          let res = self.commandFactory.readlocalProtocol(ProtocolType.Second_90, self.connectedDevice);
          //对接机器获取阀口名称
          // self.commandFactory.read(ProtocolType.Second_90, self.connectedDevice)
          //   .then((success) => {
          //     let res: any = success;
              if (res.zoneName == "") {
                self.tempData.zoneName = self.translate.get("twoExport.twoSchedule.zone1")["value"];
              } else {
                self.tempData.zoneName = res.zoneName;
              }
            // });
        }
        //获取阀门1图片数据
        self.nativeService.queryDeviceImgData("*", "mac = '" + self.connectedDevice["address"] + "' and zone = 1", (zone1r) => {
          AppConfig.consoleLog("queryDeviceImgData 1:" + zone1r);
          if (zone1r.result > 0) {
            if (zone1r.rows.length > 0) {
              self.deletepic = true;
              self.photoUrl = "file:///" + zone1r.rows[0].imagePath + "?difurl=" + Math.random();
              AppConfig.consoleLog("queryDeviceImgData imagePath " + zone1r.rows[0].imagePath);
            } else {
              self.photoUrl = "assets/images/img-1.png"
              self.deletepic = false;
            }
          }
        })
      } else {
        self.tempData.zoneName = self.translate.get("twoExport.twoSchedule.zone1")["value"];
        if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")) {
          self.tempData.zoneName = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")).zone1;
        }
        if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone1_photo")) {
          self.photoUrl = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone1_photo"))["photo"]["url"];
          self.deletepic = true;
        } else {
          self.photoUrl = "assets/images/img-1.png";
          self.deletepic = false;
        }
      }
    } else if (self.tempData.zone == 2) {
      if (self.thisVersion > 3) {
        if (AppConfig.runInfo["isOnline"] == 0) {
          if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone2Name")) {
            self.tempData.zoneName = localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone2Name");
          } else {
            self.tempData.zoneName = self.translate.get("twoExport.twoSchedule.zone2")["value"];
          }
        } else {
          let res = self.commandFactory.readlocalProtocol(ProtocolType.Second_91, self.connectedDevice);
          //对接机器获取阀口名称
          // self.commandFactory.read(ProtocolType.Second_91, self.connectedDevice)
          //   .then((success) => {
          //     AppConfig.consoleLog(success);
          //     let res: any = success;
              if (res.zoneName == "") {
                self.tempData.zoneName = self.translate.get("twoExport.twoSchedule.zone2")["value"];
              } else {
                self.tempData.zoneName = res.zoneName;
              }
            // });
        }
        //获取阀门2图片数据
        self.nativeService.queryDeviceImgData("*", "mac = '" + self.connectedDevice["address"] + "' and zone = 2", (zone2r) => {
          AppConfig.consoleLog("queryDeviceImgData 2:" + zone2r);
          if (zone2r.result > 0) {
            if (zone2r.rows.length > 0) {
              self.deletepic = true;
              self.photoUrl = "file:///" + zone2r.rows[0].imagePath + "?difurl=" + Math.random();
              AppConfig.consoleLog("queryDeviceImgData imagePath " + zone2r.rows[0].imagePath);
            } else {
              self.deletepic = false;
              self.photoUrl = "assets/images/img-2.png";
            }
          }
        })
      } else {
        self.tempData.zoneName = self.translate.get("twoExport.twoSchedule.zone2")["value"];
        if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")) {
          self.tempData.zoneName = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "local_zoneName")).zone2;
        }
        if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone2_photo")) {
          self.photoUrl = JSON.parse(localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone2_photo"))["photo"]["url"];
          self.deletepic = true;
        } else {
          self.photoUrl = "assets/images/img-2.png";
          self.deletepic = false;
        }
      }
    }
  }

  goSettingStationName() {
    let self = this;
    this.navCtrl.push(SettingStationNamePage, {zone: self.tempData.zone, zoneName: self.tempData.zoneName});
  }

  choiceTime() {
    let idx = this.tempData.zone;
    this.navCtrl.push(SettingStationTimePage, {"zone": idx});
  }

  changeDate() {
    let self = this;
    let evl = self.tempData.bttsTime;
    AppConfig.consoleLog(evl);
    let cmdModel: any = null;
    if (self.tempData.zone == 1) {
      cmdModel = self.commandFactory.getCommand(ProtocolType.Second_86);
      cmdModel.zemHour = parseInt(evl.toString().split(":")[0]);
      cmdModel.zemMinute = parseInt(evl.toString().split(":")[1]);
    } else {
      cmdModel = self.commandFactory.getCommand(ProtocolType.Second_8b);
      cmdModel.zemHour = parseInt(evl.toString().split(":")[0]);
      cmdModel.zemMinute = parseInt(evl.toString().split(":")[1]);
    }
    cmdModel.wIndex = 8;

    self.commandFactory.send_2("settingStation", cmdModel)
      .then((success) => {
        AppConfig.consoleLog(success);
        if (self.tempData.zone == 1) {
          self.commandFactory.editCommand2(cmdModel);
        } else {
          self.commandFactory.editCommand2(cmdModel);
        }

        self.goBack()

      }, (error) => {
        AppConfig.consoleLog(error);
      });

  }

  clickZoneEnabled(evl) {
    AppConfig.consoleLog(evl);
    let self = this;
    if (evl) {
      evl = 1;
    } else {
      evl = 0;
    }
    let Second_83 = self.commandFactory.getCommand(ProtocolType.Second_83);
    let Second_82 = self.commandFactory.getCommand(ProtocolType.Second_82);

    if (self.tempData.zone == 1) {

      if (evl == 0) {
        AppConfig.zutotime1 = -1;
        AppConfig.zone1newId = 0;
      }

      Second_83.zone1Enabled = evl;
      Second_82.zone1Enabled = evl;

      Second_83.runAllHH = 0;
      Second_83.runAllMM = 0;
      Second_83.runAllSS = 0;

      Second_83.zone1EnableManual = false;

    } else {
      if (evl == 0) {
        AppConfig.zutotime2 = -1;
        AppConfig.zone2newId = 0;
      }
      Second_83.zone2Enabled = evl;
      Second_82.zone2Enabled = evl;

      Second_83.runAllHH = 0;
      Second_83.runAllMM = 0;
      Second_83.runAllSS = 0;

      Second_83.zone2EnableManual = false;
    }
    localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') + "system_setting_switch", JSON.stringify({
      enabled: true,
      zone1Enabled: Second_83.zone1Enabled,
      zone2Enabled: Second_83.zone2Enabled
    }));
    self.commandFactory.send_2("settingStation", Second_83).then(
      (success) => {
        AppConfig.consoleLog(success);
        self.commandFactory.editCommand2(Second_83);
        self.commandFactory.editCommand2(Second_82);

        //self.goBack()
      }, (error) => {
        AppConfig.consoleLog(error);
      }
    )
  }

  clickPhoto() {
    let self = this;
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
    //region 新增插件 拍照功能
    this.nativeService.takePicture(null).then((val) => {
      if (val) {
        let tempval = val;
        val = "file:///" + val;
        self.photoUrl = val;
        let photo = {url: val};
        let phoneandaddr = {addr: self.connectedDevice["address"], photo: photo}

        if (AppConfig.isDockingMachine) {
          if (self.thisVersion > 3) {
            //对接机器设置阀门图片
            self.platform.ready()
              .then(
                () => {
                  cordova.plugins.AisBlePlugin.sendZoneImage(self.tempData.zone, tempval, 0, 0,
                    function (info) {
                      AppConfig.consoleLog("sendZoneImage:" + info.imgPath);
                      self.nativeService.insertDeviceImgData(self.connectedDevice["address"], self.tempData.zone, info.imgPath, updateTime, (r) => {
                        AppConfig.consoleLog(r);
                      })

                    },
                    function (errMsg) {
                      AppConfig.consoleLog(errMsg);
                      //self.nativeService.showToast(errMsg);
                    }
                  );
                }
              );
          } else {
            if (self.tempData.zone == 1) {
              localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone1_photo", JSON.stringify(phoneandaddr));
              self.deletepic = true;
            } else {
              localStorage.setItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone2_photo", JSON.stringify(phoneandaddr));
              self.deletepic = true;
            }
          }
        }
      }
    }, (error) => {
      AppConfig.consoleLog(error);
    });
  }

  deletePhoto() {
    let self = this;
    if (self.thisVersion > 3) {
      cordova.plugins.AisBlePlugin.sendZoneImage(self.tempData.zone, '', 0, 0,
        function (info) {
          self.photoUrl = "assets/images/img-1.png";
          self.deletepic = false;
          self.nativeService.deleteDeviceImgData(self.connectedDevice["address"], self.tempData.zone, (r) => {
            AppConfig.consoleLog(r);
          })

        },
        function (errMsg) {
          AppConfig.consoleLog(errMsg);
        }
      );
    } else {
      if (self.tempData.zone == 1) {
        localStorage.removeItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone1_photo");

        self.deletepic = false;
      } else {
        localStorage.removeItem(self.connectedDevice["address"].replace(/:/g, '') + "btt2_zone2_photo");
        self.deletepic = false;
      }
      self.photoUrl = "assets/images/img-1.png";
    }


  }


  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    });
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }

}



