import { Pipe, PipeTransform } from '@angular/core';
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../app/appconfig";
/**
 * Generated class for the KeyAryft pipe.
 *
 * See https://angular.io/api/core/Pipe for more info on Angular Pipes.
 */
@Pipe({
  name: '$GrassTimeft2',
})
export class GrassTimeft2 implements PipeTransform {
  constructor(private translate:TranslateService){}
  /**
   * Takes a value and makes it .
   */
  transform(value: any, ...args) {
    //console.log(value);
    let notSet = true;
    let valAry = value.toString().split(":");
    let oldValAry = value.toString().trim().split(":");
    if (!value || valAry.length <= 0) {
      return this.translate.get("msg.close")["value"];
    } else {
      for (let i = 0; i < valAry.length; i++) {
        if (parseInt(valAry[i].toString()) != -1) {
          notSet = false;
          break;
        }
      }
    }
    if (notSet) {
      return this.translate.get("msg.close")["value"];
    }
    let self = this;

    if (args && typeof (args) == "object" && args.length > 0) {
      let newValAry = [];
      let separator = "";
      let valAry = value.toString().trim().split(":");
      let ftAry = args[0].toString().trim().split(":");
      let eachLength = valAry.length > ftAry.length ? ftAry.length : valAry.length;
      for (let i = 0; i < eachLength; i++) {
        if (ftAry[i] == "hh" || ftAry[i] == "h" || ftAry[i] == "mm" || ftAry[i] == "ss") {
          if (AppConfig.timeFormat == 12 && ftAry[i] == "hh" || ftAry[i] == "h") {
            if (parseInt(valAry[i]) > 12) {
              valAry[i] = self.getPatch(parseInt(valAry[i]) - 12);
            } else if (parseInt(valAry[i]) == 0) {//上午12点
              valAry[i] = '12';
            }
          }
          if (AppConfig.timeFormat == 12) {
            if (parseInt(oldValAry[0]) >= 0 && parseInt(oldValAry[0]) < 12) {
              console.log("AppConfig.timeFormat == 12 AM")
              console.log(valAry[i] + " " + self.translate.get("common.am")["value"]);
              console.log("AppConfig.timeFormat == 12 AM")
              if (ftAry[i] == "hh" || ftAry[i] == "h") {
                newValAry.push(self.getPatch(valAry[i]));
              } else {
                newValAry.push(self.getPatch(valAry[i]) + " " + self.translate.get("common.am")["value"]);
              }
            } else if (parseInt(oldValAry[0]) >= 12 && parseInt(oldValAry[0]) < 24) {
              if (ftAry[i] == "hh" || ftAry[i] == "h") {
                newValAry.push(self.getPatch(valAry[i]));
              } else {
                console.log("AppConfig.timeFormat == 12 PM")
                console.log(valAry[i] + " " + self.translate.get("common.pm")["value"]);
                console.log("AppConfig.timeFormat == 12 PM")
                newValAry.push(self.getPatch(valAry[i]) + " " + self.translate.get("common.pm")["value"]);
              }
            }
          } else {
            console.log("AppConfig.timeFormat == 24")
            console.log(self.getPatch(valAry[i]))
            console.log("AppConfig.timeFormat == 24")
            newValAry.push(self.getPatch(valAry[i]));
          }
          //newValAry.push(self.getPatch(valAry[i]));
          separator = ":";

        } else if (ftAry[i] == "h" || ftAry[i] == "m" || ftAry[i] == "s") {
          newValAry.push(parseInt(valAry[i]).toString());
          separator = ":";
        } else if (ftAry[i] == "hour"
          || ftAry[i] == "min"
          || ftAry[i] == "sec") {
          if (ftAry[i] == "hour"){
            if (valAry[i] > 1) {
              newValAry.push(valAry[i] + " " + self.translate.get("common.hours")["value"] + " ");
            }else {
              newValAry.push(valAry[i] + " " + self.translate.get("common.hour")["value"] + " ");
            }
          }else {
            newValAry.push(valAry[i] + " " + self.translate.get("common." + ftAry[i])["value"] + " ");
          }
        } else if (ftAry[i] == "day2") {
          if (valAry[i] > 1) {
            newValAry.push(valAry[i] + " " + self.translate.get("common.day2")["value"]);
          } else {
            newValAry.push(valAry[i] + " " + self.translate.get("common.day")["value"]);
          }
          separator = ":";
        }
      }

      console.log("transform")
      console.log(JSON.stringify(newValAry));
      console.log("transform")
      return newValAry.join(separator);
    } else {
      return value;
    }
  }

  getPatch(num){
    if(num){
      if(typeof(num)=="number"){
        if(num<10)return "0"+num.toString();
        else return num.toString();
      }
      else if(typeof(num)=="string"){
        if(parseInt(num)<0)return num.toString();
        if(parseInt(num)<10)return "0"+parseInt(num);
        else return  num;
      }
      else  return num;
    }else{
      return "00";
    }
  }

}





