import {App, NavController, NavParams, ViewController} from 'ionic-angular';
import {HttpHelper} from './../../../util/HttpHelper';
import {ChangeDetectorRef, Component} from '@angular/core';
import {NativeService} from './../../../util/NativeService';
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {NavPage} from "../../common/nav/nav";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";

@Component({
  selector: 'selector-SitePage',
  templateUrl: 'manualOperationTimeDetail.html'
})

export class manualOperationTimeDetailPage {
  public navPage: any = NavPage;
  zmIrrigationStatus: any = {
    zmHour: 0,
    zmMinute: 0,
    zmSecond: 0,
    zoneEnableManual: false,
    btnName: null//开始
  }

  constructor(
    private nativeService: NativeService,
    private httpHelper: HttpHelper,
    public navCtrl: NavController,
    public cd: ChangeDetectorRef,
    public  navParams: NavParams,
    private  commandFactory: CommandFactory,
    public  appCtrl: App,
    public viewCtrl: ViewController,
    private translate: TranslateService
  ) {
    this.siteIndex = this.navParams.get("siteIndex");
  }

  hourList = [];
  minitesList = [];
  secondsList = [];
  switchModelIndex = 0;
  siteIndex = 1;

  connectedDevice: any = null;

  ionViewWillEnter() {
    let self = this;
    //0为离线 1为在线
    if (AppConfig.runInfo["isOnline"] == 1) {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"]
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"]
    }

    self.zmIrrigationStatus.btnName = self.translate.get("btn.run")["value"];
    self.siteIndex = self.navParams.get("siteIndex");
    for (let i = 0; i < 24; i++) {
      this.hourList.push(i);
    }

    for (let i = 0; i < 60; i++) {
      this.minitesList.push(i);
    }

    for (let i = 0; i < 60; i++) {
      this.secondsList.push(i);
    }

    self.commandFactory.readRemote(ProtocolType.Second_82,
      (success) => {
        AppConfig.consoleLog(success)
        let res = success;
        self.commandFactory.editCommand2(res);
        let zoneState = 1;
        if (self.siteIndex == 1) {
          zoneState = res.zone1State;

          if (res.zone1State == 1) self.zmIrrigationStatus.zoneEnableManual = false;
          else if (res.zone1State == 17) self.zmIrrigationStatus.zoneEnableManual = true;
          else self.zmIrrigationStatus.zoneEnableManual = res.zone1EnableManual;

        } else if (self.siteIndex == 2) {
          zoneState = res.zone2State;

          if (res.zone2State == 1) self.zmIrrigationStatus.zoneEnableManual = false;
          else if (res.zone2State == 17) self.zmIrrigationStatus.zoneEnableManual = true;
          else self.zmIrrigationStatus.zoneEnableManual = res.zone2EnableManual;

        }
        if (self.zmIrrigationStatus.zoneEnableManual || zoneState == 17)
          self.zmIrrigationStatus.btnName = self.translate.get("btn.stop")["value"];
        else self.zmIrrigationStatus.btnName = self.translate.get("btn.run")["value"];

        self.commandFactory.readRemote(ProtocolType.Second_83, (success83) => {
          AppConfig.consoleLog(success83)
        }, null, self.connectedDevice);


      }, (error) => {
        AppConfig.consoleLog(error)
      }, self.connectedDevice);
  }

  ionViewDidEnter() {
    AppConfig.consoleLog("ionViewDidEnter");
    let self = this;
    if (self.siteIndex == 1) {
      let Second_86 = self.commandFactory.readlocalProtocol(ProtocolType.Second_86, self.connectedDevice);
      // self.commandFactory.read1(ProtocolType.Second_86,self.connectedDevice)
      //   .then((success)=>{
      //     let res=success;
      self.commandFactory.editCommand2(Second_86);
      self.init(Second_86);
      //AppConfig.consoleLog(success)
      // },(error)=>{
      //   AppConfig.consoleLog(error)
      // });
    } else if (self.siteIndex == 2) {
      let Second_8b = self.commandFactory.readlocalProtocol(ProtocolType.Second_8b, self.connectedDevice);
      // self.commandFactory.read1(ProtocolType.Second_8b,self.connectedDevice)
      //   .then((success)=>{
      //     let res=success;
      self.commandFactory.editCommand2(Second_8b);
      self.init(Second_8b);
      // AppConfig.consoleLog(success)
      // },(error)=>{
      //   AppConfig.consoleLog(error)
      // });
    } else {
      self.init();
    }

  }

  init(cmdModel: any = null) {
    let self = this;
    if (self.siteIndex > 0) {
      self.zmIrrigationStatus.zmHour = cmdModel.zmHour;
      self.zmIrrigationStatus.zmMinute = cmdModel.zmMinute;
      self.zmIrrigationStatus.zmSecond = cmdModel.zmSecond;
    } else {
      self.zmIrrigationStatus.zmHour = 0;
      self.zmIrrigationStatus.zmMinute = 0;
      self.zmIrrigationStatus.zmSecond = 0;
      self.zmIrrigationStatus.btnName = self.translate.get("btn.run")["value"];
      self.zmIrrigationStatus.zoneEnableManual = false;
    }


  }

  saveData() {
    if (this.siteIndex == 0) {
      if (this.zmIrrigationStatus.zoneEnableManual) this.stopAllIrrigation();
      else this.startAllIrrigation();
    } else {
      if (this.zmIrrigationStatus.zoneEnableManual) this.shopIrrigation();
      else this.startIrrigation();
    }
  }

  shopIrrigation() {
    let self = this;

    let res = self.commandFactory.readlocalProtocol(ProtocolType.Second_83, self.connectedDevice);
    // self.commandFactory.readRemote1(ProtocolType.Second_83,(success83)=>{
    //   AppConfig.consoleLog(success83)
    //   let res=success83;
    res.specialSetting = 0;
    if (self.siteIndex == 1) {
      res.zone1EnableManual = false;
      if (localStorage.getItem("run_zone1_zm_time")) {
        let run_zone1_zm_time = JSON.parse(localStorage.getItem("run_zone1_zm_time"));
        localStorage.setItem("run_zone1_zm_time", JSON.stringify({
          zone: "zone1",
          startTime: run_zone1_zm_time.startTime,
          endTime: new Date().getTime()
        }));
      }
      self.commandFactory.updateLog("zone1");
    } else if (self.siteIndex == 2) {
      res.zone2EnableManual = false;
      if (localStorage.getItem("run_zone2_zm_time")) {
        let run_zone2_zm_time = JSON.parse(localStorage.getItem("run_zone2_zm_time"));
        localStorage.setItem("run_zone2_zm_time", JSON.stringify({
          zone: "zone2",
          startTime: run_zone2_zm_time.startTime,
          endTime: new Date().getTime()
        }));
      }
      self.commandFactory.updateLog("zone2");
    }
    self.commandFactory.send_2("manualOperationTimeDetail", res)
      .then((successres) => {
        AppConfig.consoleLog(successres);
        self.commandFactory.editCommand2(res);
        self.zmIrrigationStatus.zoneEnableManual = false;
        self.zmIrrigationStatus.btnName = self.translate.get("btn.run")["value"];
        self.goTwoSchedule();
      })
    //},null,self.connectedDevice);

  }

  startIrrigation() {
    let self = this;
    let Second_83 = self.commandFactory.getCommand(ProtocolType.Second_83);
    Second_83.specialSetting = 0;
    let cmdModel: any = null;
    if (self.siteIndex == 1) {
      Second_83.zone1EnableManual = true;
      Second_83.zone2EnableManual = false;
      cmdModel = self.commandFactory.getCommand(ProtocolType.Second_86)

    } else if (self.siteIndex == 2) {
      Second_83.zone2EnableManual = true;
      Second_83.zone1EnableManual = false;
      cmdModel = self.commandFactory.getCommand(ProtocolType.Second_8b)
    }
    cmdModel.wIndex = 4;//手动
    cmdModel.zmHour = parseInt(self.zmIrrigationStatus.zmHour);
    cmdModel.zmMinute = parseInt(self.zmIrrigationStatus.zmMinute);
    cmdModel.zmSecond = parseInt(self.zmIrrigationStatus.zmSecond);

    let run_zone_cmd = cmdModel;
    run_zone_cmd["createTime"] = new Date().getTime();
    let startTime = new Date().getTime();
    let endTime = new Date(startTime + cmdModel.zmHour * 60 * 60 * 1000 + cmdModel.zmMinute * 60 * 1000 + cmdModel.zmSecond * 1000).getTime();

    if (self.siteIndex == 1) {
      localStorage.setItem("run_zone1_cmd", JSON.stringify(run_zone_cmd));
      localStorage.setItem("run_zone1_zm_time", JSON.stringify({
        zone: "zone1",
        startTime: startTime,
        endTime: endTime
      }));
      self.commandFactory.addLog("zone1", cmdModel.zmHour.toString() + ":" + cmdModel.zmMinute.toString() + ":" + cmdModel.zmSecond);
    } else if (self.siteIndex == 2) {
      localStorage.setItem("run_zone2_cmd", JSON.stringify(run_zone_cmd));
      localStorage.setItem("run_zone2_zm_time", JSON.stringify({
        zone: "zone2",
        startTime: startTime,
        endTime: endTime
      }));
      self.commandFactory.addLog("zone2", cmdModel.zmHour.toString() + ":" + cmdModel.zmMinute.toString() + ":" + cmdModel.zmSecond);
    }

    AppConfig.consoleLog(cmdModel);

    self.commandFactory.send_2("manualOperationTimeDetail", cmdModel)
      .then((success) => {
        AppConfig.consoleLog(success)
        self.zmIrrigationStatus.zoneEnableManual = true;
        self.zmIrrigationStatus.btnName = self.translate.get("btn.stop")["value"];
        self.commandFactory.send_2("manualOperationTimeDetail", Second_83)
          .then((success) => {
            AppConfig.consoleLog(success)
            self.commandFactory.editCommand2(Second_83);
            if (self.siteIndex == 1) {
              self.commandFactory.editCommand2(cmdModel);
            } else if (self.siteIndex == 2) {
              self.commandFactory.editCommand2(cmdModel);
            }
            self.goTwoSchedule();
          }, (error) => {
            AppConfig.consoleLog(error)
          });
      }, (error) => {
        AppConfig.consoleLog(error);
      });

  }

  startAllIrrigation() {
    let self = this;
    let Second_83 = self.commandFactory.getCommand(ProtocolType.Second_83);
    Second_83.runAllHH = parseInt(self.zmIrrigationStatus.zmHour);
    Second_83.runAllMM = parseInt(self.zmIrrigationStatus.zmMinute);
    Second_83.runAllSS = parseInt(self.zmIrrigationStatus.zmSecond);
    Second_83.zone1EnableManual = true;
    Second_83.zone2EnableManual = true;
    Second_83.specialSetting = 2;

    let Second_82 = self.commandFactory.getCommand(ProtocolType.Second_82);
    Second_82.zone1EnableManual = true
    Second_82.zone2EnableManual = true;
    self.commandFactory.editCommand2(Second_82);
    //Second_83.suspendWatering=0;
    let run_all_cmd = Second_83;
    run_all_cmd["createTime"] = new Date().getTime();
    let startTime = new Date().getTime();
    let endTime = new Date(startTime + Second_83.runAllHH * 60 * 60 * 1000 + Second_83.runAllMM * 60 * 1000 + Second_83.runAllSS * 1000).getTime();

    localStorage.setItem("run_all_cmd", JSON.stringify(run_all_cmd));
    localStorage.setItem("run_zone1_zm_time", JSON.stringify({zone: "zone1", startTime: startTime, endTime: endTime}));
    localStorage.setItem("run_zone2_zm_time", JSON.stringify({zone: "zone2", startTime: startTime, endTime: endTime}));
    self.commandFactory.addLog("zone1", Second_83.runAllHH.toString() + ":" + Second_83.runAllMM.toString() + ":" + Second_83.runAllSS);
    self.commandFactory.addLog("zone2", Second_83.runAllHH.toString() + ":" + Second_83.runAllMM.toString() + ":" + Second_83.runAllSS);

    self.commandFactory.send_2("manualOperationTimeDetail", Second_83)
      .then((success) => {
        AppConfig.consoleLog(success);
        self.zmIrrigationStatus.zoneEnableManual = true;
        self.zmIrrigationStatus.btnName = self.translate.get("btn.stop")["value"];
        self.commandFactory.editCommand2(Second_83);

        self.goTwoSchedule();

      }, (error) => {
        AppConfig.consoleLog(error);
      });

  }

  stopAllIrrigation() {
    let self = this;
    let Second_83 = self.commandFactory.getCommand(ProtocolType.Second_83);
    Second_83.zone1EnableManual = false;
    Second_83.zone2EnableManual = false;
    Second_83.specialSetting = 0;
    //Second_83.suspendWatering=0;
    let Second_82 = self.commandFactory.getCommand(ProtocolType.Second_82);
    Second_82.zone1EnableManual = false
    Second_82.zone2EnableManual = false;
    if (localStorage.getItem("run_zone1_zm_time")) {
      let run_zone1_zm_time = JSON.parse(localStorage.getItem("run_zone1_zm_time"));
      localStorage.setItem("run_zone1_zm_time", JSON.stringify({
        zone: "zone1",
        startTime: run_zone1_zm_time.startTime,
        endTime: new Date().getTime()
      }));
    }
    if (localStorage.getItem("run_zone2_zm_time")) {
      let run_zone2_zm_time = JSON.parse(localStorage.getItem("run_zone2_zm_time"));
      localStorage.setItem("run_zone2_zm_time", JSON.stringify({
        zone: "zone2",
        startTime: run_zone2_zm_time.startTime,
        endTime: new Date().getTime()
      }));
    }
    self.commandFactory.editCommand2(Second_82);
    self.commandFactory.updateLog("zone1");
    self.commandFactory.updateLog("zone2");

    self.commandFactory.send_2("manualOperationTimeDetail", Second_83)
      .then((success) => {
        AppConfig.consoleLog(success);
        self.zmIrrigationStatus.zoneEnableManual = false;
        self.zmIrrigationStatus.btnName = self.translate.get("btn.run")["value"];
        self.commandFactory.editCommand2(Second_83);

        self.goTwoSchedule();
      }, (error) => {
        AppConfig.consoleLog(error);
      });
    let Second_89 = self.commandFactory.readlocalProtocol(ProtocolType.Second_89, self.connectedDevice);
    // self.commandFactory.read1(ProtocolType.Second_89, self.connectedDevice)
    //   .then((success1) => {
    //     AppConfig.consoleLog(success1);
        self.commandFactory.send_2("manualOperationTimeDetail", Second_89)
          .then((success2) => {
            AppConfig.consoleLog(success2)
          }, (error) => {
            AppConfig.consoleLog(error);
          });
      // }, (error) => {
      //   AppConfig.consoleLog(error);
      // });
    let Second_8e = self.commandFactory.readlocalProtocol(ProtocolType.Second_8e, self.connectedDevice);
    // self.commandFactory.read1(ProtocolType.Second_8e, self.connectedDevice)
    //   .then((success1) => {
    //     AppConfig.consoleLog(success1);
        self.commandFactory.send_2("manualOperationTimeDetail", Second_8e)
          .then((success2) => {
            AppConfig.consoleLog(success2)
          }, (error) => {
            AppConfig.consoleLog(error);
          });
      // }, (error) => {
      //   AppConfig.consoleLog(error);
      // });


  }

  goBack() {
    this.navCtrl.pop();
  }

  goTwoSchedule() {
    this.navCtrl.parent.select(1);
    this.navCtrl.popToRoot();
  }
}



