import {Pipe, PipeTransform} from '@angular/core';
import {TranslateService} from "ng2-translate";


/**
 * Generated class for the KeyAryft pipe.
 *
 * See https://angular.io/api/core/Pipe for more info on Angular Pipes.
 */
@Pipe({
  name: '$GrassShortRuntimeft',
})
export class GrassShortRuntimeft implements PipeTransform {
  constructor(private translate: TranslateService) {

  }

  /**
   * Takes a value and makes it .
   */
  transform(value: any, ...args) {
    let notSet = true;
    let valAry = value.toString().split(":");
    if (value == "XXX") {
      return "0 " + this.translate.get("common.sec")["value"] + " ";
    }
    if (!value || valAry.length <= 0) {
      return this.translate.get("common.notSet")["value"];
    } else {
      for (let i = 0; i < valAry.length; i++) {
        if (parseInt(valAry[i].toString()) != 0 && parseInt(valAry[i].toString()) != -1) {
          notSet = false;
          break;
        }
      }
    }
    if (notSet) {
      return this.translate.get("common.notSet")["value"];
    }
    let self = this;
    let minuteWord = " " + self.translate.get("common.min")["value"] + " ";
    let secondWord = " " + self.translate.get("common.sec")["value"] + " ";


    //按时分秒存在值来显示具体的内容
    let showTxt = "";//(parseInt(valAry[0])*60+parseInt(valAry[1]))+minuteWord+valAry[2]+secondWord;
    if ((parseInt(valAry[0]) + parseInt(valAry[1])) > 0) {
      showTxt += (parseInt(valAry[0]) * 60 + parseInt(valAry[1])) + minuteWord;
    }
    if (parseInt(valAry[2]) > 0) {
      showTxt += parseInt(valAry[2]) + secondWord;
    }

    return showTxt;
  }

}





