  init(thisVersion) {
    let self = this;
    if (thisVersion > 3) {
      if (TimeType[self.timeType] == TimeType.timeStartTime2 || TimeType[self.timeType] == TimeType.timeStartTime3 || TimeType[self.timeType] == TimeType.timeStartTime4
        || TimeType[self.timeType] == TimeType.timeStartTime5 || TimeType[self.timeType] == TimeType.timeStartTime6 || TimeType[self.timeType] == TimeType.timeStartTime7 || TimeType[self.timeType] == TimeType.timeStartTime8
        || TimeType[self.timeType] == TimeType.cycStartTime2 || TimeType[self.timeType] == TimeType.cycEndTime2 || TimeType[self.timeType] == TimeType.cycSoakTime) {
        self.isShowClose = true;
      }
    } else {
      if (TimeType[self.timeType] == TimeType.timeStartTime2 || TimeType[self.timeType] == TimeType.timeStartTime3 || TimeType[self.timeType] == TimeType.timeStartTime4
        || TimeType[self.timeType] == TimeType.cycStartTime2 || TimeType[self.timeType] == TimeType.cycEndTime2 || TimeType[self.timeType] == TimeType.cycSoakTime) {
        self.isShowClose = true;
      }
    }
    self.headerTitle = self.translate.get("choiceTime." + self.timeType)["value"];
    self.initPicker(self.timeType);

    if (this.cd !== null && this.cd !== undefined &&
      !(this.cd as ViewRef_).destroyed) {
      this.cd.detectChanges();
    }

  }

