  getNewRunTime(times, percent) {
    let newSeconds = percent * (parseInt(times[0]) * 60 * 60 + parseInt(times[2]) * 60 + parseInt(times[4]));

    let hour = parseInt((newSeconds / 3600).toString())
    let min = parseInt(((newSeconds - (hour * 3600)) / 60).toString());
    let sec = parseInt((newSeconds - (hour * 3600) - (min * 60)).toString());
    return (hour < 10 ? "0" + hour.toString() : hour.toString()) + ":" + (min < 10 ? "0" + min.toString() : min.toString()) + ":" + (sec < 10 ? "0" + sec.toString() : sec.toString());
  }

  getNewRunTimeTop(times, percent) {
    let self = this;
    let newSeconds = percent * (parseInt(times[0]) * 60 * 60 + parseInt(times[1]) * 60 + parseInt(times[2]));

    let hour = parseInt((newSeconds / 3600).toString())
    let min = parseInt(((newSeconds - (hour * 3600)) / 60).toString());
    let sec = parseInt((newSeconds - (hour * 3600) - (min * 60)).toString());
    return (hour < 10 ? "0" + hour.toString() : hour.toString()) + ":" + (min < 10 ? "0" + min.toString() : min.toString()) + ":" + (sec < 10 ? "0" + sec.toString() : sec.toString());


  }

