  //获取默认时间
  getDefaultTime(timeType: TimeType = null) {
    let self = this;
    let defaultTime = [];
    if (self.siteIndex == 1)//站点1
    {
      if (self.mode == 1)//定时
      {
        if (timeType == 5 || timeType == 6 || timeType == 7 || timeType == 8) {
          let Second_A0;
          Second_A0 = self.commandFactory.getCommand(ProtocolType.Second_A0);
          defaultTime = self.getDefaultFixedTime(timeType, Second_A0);
        } else {
          let Second_87;
          Second_87 = self.commandFactory.getCommand(ProtocolType.Second_87);
          defaultTime = self.getDefaultFixedTime(timeType, Second_87);
        }
      } else {//循环
        let Second_88 = self.commandFactory.getCommand(ProtocolType.Second_88);
        defaultTime = self.getDefaultCircleTime(timeType, Second_88);
      }
    } else {//站点2
      if (self.mode == 1)//定时
      {
        if (timeType == 5 || timeType == 6 || timeType == 7 || timeType == 8) {
          let Second_A1;
          Second_A1 = self.commandFactory.getCommand(ProtocolType.Second_A1);
          defaultTime = self.getDefaultFixedTime(timeType, Second_A1);
        } else {
          let Second_8c = self.commandFactory.getCommand(ProtocolType.Second_8c);
          defaultTime = self.getDefaultFixedTime(timeType, Second_8c);
        }
      } else {//循环
        let Second_8d = self.commandFactory.getCommand(ProtocolType.Second_8d);
        defaultTime = self.getDefaultCircleTime(timeType, Second_8d);
      }
    }
    AppConfig.consoleLog(defaultTime);

    return defaultTime;
  }

