  savegoBack() {
    let self = this;
    if (TimeType[self.timeType] == TimeType.cycRunTime) {
      if (TimeType[self.timeType] == TimeType.cycRunTime) {
        $("#DivIrrigationAdjustment").hide();
        self.timeType = TimeType[TimeType.cycSoakTime];
      }
      self.init(self.thisVersion);
    } else {
      this.navCtrl.pop({animate: false});
    }
  }

