  ionViewWillUnload() {
    let self = this;

    destoryTabPage(self, 0);
    console.log('pageId=' + self.pageId + ',销毁....................................');
  }

  ionViewDidLoad() {
    if (AppConfig.delconnectInit == 0) {
      localStorage.removeItem("connectInit");
      AppConfig.delconnectInit = 1;
    }
    if (localStorage.getItem("local_device_list_connected")) {
      $("#divObj").show();
    } else {
      $("#divObj").hide();
    }
  }

  ionViewWillEnter() {
    let self = this;
    // //显示加载进度
    // $('#loadingPanel').css("display", "flex").show();
  }

  ionViewDidEnter() {
    let self = this;

    //监控页面是否发生变化
    monitorTab(this, 0, this.doEnter, this.doLeave);

    //所有进度条隐藏
    $('ion-item .progress', '#availablePanel').hide();

    localStorage.removeItem("ConnectAddr");

    //读取配置方案
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");

    //插入模板10条记录 Watering  plan 1 - Watering  plan 10
    self.nativeService.insertDeviceTemplateData(1, "", 0, updateTime, (r) => {
      ////AppConfig.consoleLog(r);
      if (r.result > 0) {
        self.nativeService.queryDeviceTemplateData("templateId", "isChecked = 1 ", function (result) {
          let templateId = null; //JSON.stringify(result);
          if (result.result > 0) {
            if (result.rows.length > 0) templateId = result.rows[0].templateId;
            else {
              AppConfig.consoleLog(result);
            }
          } else {
            //AppConfig.consoleLog(result);
          }

          if (templateId) {
            //存储配置方案ID  homePageTypeId
            localStorage.setItem("homePageTypeId", templateId.toString());
          } else {
            self.nativeService.insertDeviceBasicData("homePageTypeId", "", 1, 1, updateTime, (r2) => {
              //AppConfig.consoleLog(r2);
              //存储配置方案ID  homePageTypeId
              localStorage.setItem("homePageTypeId", "1");
            });
          }
        });
      }
    });

    //连接过的设备地址集合
    let macJson = localStorage.getItem("MACaddress");
    if(macJson) {
      try {
        self.MACaddressList=JSON.parse(macJson);
      }
      catch(e) {
        self.MACaddressList={};
      }
    }
  }

  ionViewWillLeave() {
    let self = this;

  }

