import {NavController, ActionSheetController, Platform} from 'ionic-angular';
import {Component} from "@angular/core";
import {SettingStationBatteryPage} from "../../more/settingStationBattery/settingStationBattery";
import {LocationSettingsPage} from "../locationSettings/locationSettings";
import {AppConfig} from "../../../app/appconfig";
import {BttVersion, CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {NativeService} from "../../../util/NativeService";


declare var $: any;
declare var AMap;

@Component({
  selector: 'selector-gdmapBtts',
  templateUrl: 'gdmapBtts.html'
})

export class GdmapBttsPage {
  markerList = [];
  delType = 0;
  markerId = 0;

  map;
  oneIcon = 0;
  //public markers:any = {
  //  title: '',
  //  address: '',
  //  site: '',
  //  markerid: 0,
  //  icon: '',
  //  textcontent: '',
  //  position: ''
  //};

  constructor(private nativeService: NativeService, public navCtrl: NavController, public actionSheetCtrl: ActionSheetController,
              private  commandFactory: CommandFactory, private platform: Platform) {

  }

  goBack() {
    this.navCtrl.pop();
  }

  goSettingBtts() {
    this.navCtrl.push(LocationSettingsPage);
  }


  ionViewWillEnter() {
    this.initMap();
  }

  ionViewDidEnter() {
  }

  //初始化高德地图
  initMap() {
    var me = this;
    $('#deldev').hide();
    $('#delicon').hide();
    me.map = new AMap.Map('DivGdMap');
    me.map.plugin('AMap.Geolocation', function () {
      var geolocation = new AMap.Geolocation({
        enableHighAccuracy: true,//是否使用高精度定位，默认:true
        timeout: 10000,          //超过10秒后停止定位，默认：无穷大
        maximumAge: 0,           //定位结果缓存0毫秒，默认：0
        convert: true,           //自动偏移坐标，偏移后的坐标为高德坐标，默认：true
        showButton: true,        //显示定位按钮，默认：true
        buttonPosition: 'LB',    //定位按钮停靠位置，默认：'LB'，左下角
        buttonOffset: new AMap.Pixel(10, 20),//定位按钮与设置的停靠位置的偏移量，默认：Pixel(10, 20)
        showMarker: true,        //定位成功后在定位到的位置显示点标记，默认：true
        showCircle: true,        //定位成功后用圆圈表示定位精度范围，默认：true
        panToLocation: true,     //定位成功后将定位到的位置作为地图中心点，默认：true
        zoomToAccuracy: true     //定位成功后调整地图视野范围使定位位置及精度范围视野内可见，默认：false

      });

      me.map.addControl(geolocation);
      geolocation.getCurrentPosition();
      //AMap.event.addListener(geolocation, 'complete', onComplete);//返回定位信息
      //AMap.event.addListener(geolocation, 'error', onError);      //返回定位出错信息
    });


    AMap.plugin([
      'AMap.ToolBar',
    ], function () {
      // 在图面添加工具条控件，工具条控件集成了缩放、平移、定位等功能按钮在内的组合控件
      me.map.addControl(new AMap.ToolBar({
        // 简易缩放模式，默认为 false
        liteStyle: false
      }));
    });

    me.addMapClickEvent(me.map);


    let curDeviceMac: any = null;
    let tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
    for (let i = 0; i < tempDevice.length; i++) {
      if (tempDevice[i]["connected"] == true) {
        curDeviceMac = tempDevice[i]["address"];
        break;
      }
    }
    me.nativeService.queryDeviceMapData("*", "", function (r) {
      AppConfig.consoleLog(r);
      if (r.result > 0) {
        for (let i = 0; i < r.rows.length; i++) {
          me.fillMarker(r.rows[i], curDeviceMac);
        }
      }
    });
  }

  //填充/添加 marker
  fillMarker(data, curDeviceMac) {
    let me = this;
    let row = data;
    let marker = new AMap.Marker({
      markerid: row.id,
      title: row.name,
      address: row.address,
      site: row.site,
      icon: '',
      textcontent: '1',
      position: (row.lng + ',' + row.lat).split(","),
      offset: new AMap.Pixel(-10, -34),
      //设置是否可以拖拽
      draggable: true,
      cursor: 'move',
      // 设置拖拽效果
      raiseOnDrag: true,
      devicePic: row.devicePic
    });
    let icon = new AMap.Icon({
      image: "assets/icon/icon_grey.png",
      size: new AMap.Size(40, 40),  //图标所处区域大小
      imageSize: new AMap.Size(40, 40) //图标大小
    });
    if (curDeviceMac == row.mac) {
      icon = new AMap.Icon({
        image: "assets/icon/icon_green.png",
        size: new AMap.Size(40, 40),  //图标所处区域大小
        imageSize: new AMap.Size(40, 40) //图标大小
      });
    }
    marker.setIcon(icon);
    me.map.add(marker);
    me.addMarkerInfo(marker, curDeviceMac, row.mac, row.id);
  }

  //添加marker消息框
  addMarkerInfo(marker, curDeviceMac, mac, markerid) {
    let me = this;
    AppConfig.consoleLog(markerid);
    var infoWindow1 = new AMap.InfoWindow(
      {
        closeWhenClickMap: true,
        offset: new AMap.Pixel(0, -30)
      });
    AMap.event.addListener(marker, 'click', function (e) {
      if (e.target.w.markerid == 0) {
        me.navCtrl.push(LocationSettingsPage, {lng: e.target.getPosition().lng, lat: e.target.getPosition().lat});
      } else {
        AppConfig.consoleLog(e.target.w.markerid);
        AppConfig.consoleLog(e.target.w.textcontent);
        var str;
        if (curDeviceMac == mac) {
          str = "<div id='editMarker" + e.target.w.markerid + "'><div class='marker-online-info'>" +
            "<span class='marker-ic-left'><img class='marker-ic-img' src=" + (e.target.w.devicePic ? e.target.w.devicePic : "assets/images/img-1.png") + "></span>" +
            "<div class='marker-ic-right'>" +
            "<p class='marker-ic-text-1'>" + e.target.w.title + "</p>" +
            "<p class='marker-ic-text-2'>" + e.target.w.address + "</p>" +
            "<p class='marker-ic-text-3'>" + e.target.w.site + "</p></div></div></div>";
        } else {
          str = "<div id='editMarker" + e.target.w.markerid + "'><div class='marker-info-content'>" +
            "<span class='marker-ic-left'><img class='marker-ic-img' src=" + (e.target.w.devicePic ? e.target.w.devicePic : "assets/images/img-1.png") + "></span>" +
            "<div class='marker-ic-right'>" +
            "<p class='marker-ic-text-1'>" + e.target.w.title + "</p>" +
            "<p class='marker-ic-text-2'>" + e.target.w.address + "</p>" +
            "<p class='marker-ic-text-3'>" + e.target.w.site + "</p></div></div></div>";
        }
        infoWindow1.setContent(str);
        //infoWindow1.on('close', me.showInfoClose())
        infoWindow1.open(me.map, e.target.getPosition());
        $('#deldev').show();
        me.delType = 2;
        me.markerId = markerid;

        let editMarker = document.getElementById("editMarker" + e.target.w.markerid);
        editMarker.addEventListener("click", function () {
          me.goSettingBttsedit("edit", mac);
        })
      }
    });

  }

  goSettingBttsedit(type, mac) {
    this.navCtrl.push(LocationSettingsPage, {type, mac});
  }

  //添加地图点击事件
  addMapClickEvent(map) {
    let me = this;
    map.on('click', function (e) {
      let display = $('#deldev').css('display');
      if (display == 'none') {
        AppConfig.consoleLog(e.lnglat.getLng() + ',' + e.lnglat.getLat());
        var icon = new AMap.Icon({
          image: "http://a.amap.com/jsapi_demos/static/demo-center/icons/poi-marker-default.png",
          size: new AMap.Size(31, 40),  //图标所处区域大小
          imageSize: new AMap.Size(31, 40) //图标大小
        });
        var infoWindow = new AMap.InfoWindow({offset: new AMap.Pixel(0, -30)});
        var marker = new AMap.Marker({
          icon: icon,
          position: [e.lnglat.getLng(), e.lnglat.getLat()],
          offset: new AMap.Pixel(-13, -30),
          //设置是否可以拖拽
          draggable: true,
          cursor: 'move',
          // 设置拖拽效果
          raiseOnDrag: true,
          zoom: 13
        });

        marker.id = 0;
        marker.on('click', function markerClick(e) {
          if (e.target.id == 0) {
            me.navCtrl.push(LocationSettingsPage, {lng: e.target.getPosition().lng, lat: e.target.getPosition().lat});
            AppConfig.consoleLog('click');
          } else {
            AppConfig.consoleLog(e.target.id);
            infoWindow.setContent(e.target.content);
            infoWindow.open(map, e.target.getPosition());
          }
        });
        marker.setMap(map);
        $('#delicon').show();
        let addEvent = document.getElementById("delicon");
        me.delType = 1;
        //me.markerId = marker;
        addEvent.addEventListener("click", function () {
          me.btndelete(1, marker);
        })
      } else {
        $("#deldev").hide();
      }
    });

  }

  //删除
  btndelete(type = null, id = null) {
    let me = this;
    if (!type) type = me.delType;
    if (!id) id = me.markerId;

    if (type == 1) {
      me.map.remove(id);
      $('#delicon').hide();
      me.delType = 0;
    } else if (type == 2) {
      me.commandFactory.showConfirm("是否删除设备", () => {
        me.platform.ready()
          .then(
            () => {
              this.nativeService.deleteDeviceMapTable(id, (r) => {
                AppConfig.consoleLog(r);
                me.delType = 0;
                me.markerId = 0;
              })
              //me.btndelete(2, markerid);
              me.initMap();
              //$('#deldev').hide();
            }
          );
      }, () => {
        $('#deldev').hide();
        me.delType = 0;
        me.markerId = 0;
      });
    }

  }
}







