import { Pipe, PipeTransform } from '@angular/core';
import {AppConfig} from "../app/appconfig";

/**
 * Generated class for the AdsImgft pipe.
 *
 * See https://angular.io/api/core/Pipe for more info on Angular Pipes.
 */
@Pipe({
  name: '$AdsImgft',
})
export class AdsImgft implements PipeTransform {
  /**
   * Takes a value and makes it lowercase.
   */
  transform(value: string, ...args) {
    if(!value){
      if(args[0] && args[0]==1) return './assets/images/upload.png';
      else if(args[0] && args[0]==2) return './assets/imgs/head.png';

      else return './assets/imgs/ads-default.png';
    }
    else if (args[0] && args[0]==2){
      if(value.indexOf("[")>=0){
        return AppConfig.GetInterFaceUrl()+JSON.parse(value)[0];
      }
      return AppConfig.GetInterFaceUrl()+value;
    }

    return value;//.toLowerCase();
  }
}



