  ionViewWillLeave() {
    let self = this;
    if (self.zoneZmStateMonitor) {
      AppConfig.consoleLog("关闭监控器");
      window.clearInterval(self.zoneZmStateMonitor);
      self.zoneZmStateMonitor = null;
    }
    self.zmIrrigationStatus.zoneEnableManual = false;
  }

  runMonitor() {
    let self = this;
    if (self.zoneZmStateMonitor) {
      window.clearInterval(self.zoneZmStateMonitor);
      self.zoneZmStateMonitor = null;
    }
    let siteIdx = self.siteIndex;
    self.zoneZmStateMonitor = setInterval(() => {
      self.timerZoneStateZm(siteIdx);
    }, 1000);

  }

  timerZoneStateZm(siteIdx: any = null) {
    let self = this;
    let curTime = new Date().getTime();
    if (siteIdx == 1) {
      if (localStorage.getItem("run_zone1_zm_time")) {
        let run_zone1_zm_time = JSON.parse(localStorage.getItem("run_zone1_zm_time"));
        if (self.connectedDevice.address==run_zone1_zm_time.address && curTime > run_zone1_zm_time.startTime && curTime < run_zone1_zm_time.endTime) {
          if (!self.zmIrrigationStatus.zoneEnableManual)
            self.zmIrrigationStatus.zoneEnableManual = true;

          self.zmIrrigationStatus.zoneDiffTime = self.commandFactory.getDateDiff_2(curTime, run_zone1_zm_time.endTime);
          let diffAry = self.zmIrrigationStatus.zoneDiffTime.split(":");
          $('#pageColpicker').coolpicker('setValue', [diffAry[0], "小时", diffAry[1], "分钟", diffAry[2], "秒"]);
        } else {
          if (self.zmIrrigationStatus.zoneEnableManual)
            self.zmIrrigationStatus.zoneEnableManual = false;
        }
      }
    } else {
      if (localStorage.getItem("run_zone2_zm_time")) {
        let run_zone2_zm_time = JSON.parse(localStorage.getItem("run_zone2_zm_time"));
        if (self.connectedDevice.address==run_zone2_zm_time.address && curTime > run_zone2_zm_time.startTime && curTime < run_zone2_zm_time.endTime) {
          if (!self.zmIrrigationStatus.zoneEnableManual)
            self.zmIrrigationStatus.zoneEnableManual = true;

          self.zmIrrigationStatus.zoneDiffTime = self.commandFactory.getDateDiff_2(curTime, run_zone2_zm_time.endTime);
          let diffAry = self.zmIrrigationStatus.zoneDiffTime.split(":");
          $('#pageColpicker').coolpicker('setValue', [diffAry[0], "小时", diffAry[1], "分钟", diffAry[2], "秒"]);
        } else {
          if (self.zmIrrigationStatus.zoneEnableManual)
            self.zmIrrigationStatus.zoneEnableManual = false;
        }
      }
    }
  }

  getValue() {
    //返回的为数组
    return $('#pageColpicker').coolpicker('getValue');
  }

