import {NavController} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {Component, OnInit} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {ChangeDetectorRef} from '@angular/core';
import {LanguageSettingPage} from "../languageSetting/languageSetting";
import {AppAboutPage} from "../appAbout/appAbout";
import {InAppBrowser} from "@ionic-native/in-app-browser";
import {EmailComposer} from "@ionic-native/email-composer";
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {AppConfig} from "../../../app/appconfig";
import {TranslateService} from "ng2-translate";
import {settingWateringPlanPage} from '../settingWateringPlan/settingWateringPlan';

declare var $: any;

@Component({
  selector: 'selector-settingHome',
  templateUrl: 'settingHome.html'
})

export class SettingHomePage {
  public showMore: boolean = false;
  public entpList: any = [];
  PageSize = 10;
  PageIndex = 1;
  eiPageCount = 0;
  dataLs: any;
  public curData: any = {
    enabled: false
  };

  email = {
    to: 'BTT@hunterindustries.com',
    subject: 'BTT App Feedback',
    body: "Feedback Device Platform=Android Device Model=OPPO OPPO R9s OS Version=6.1 Device Screen Height=1920 Device Screen Width=1080 App Version=2.0.1 Language=中文",
    isHtml: false
  };

  public currentUserInfo: any = {};
  version: any = " " + AppConfig.apkVersion;
  curDevice;
  thisVersion: any = null;
  connectedDevice: any = null;
  constructor(private  emailComposer: EmailComposer, private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController,
              public cd: ChangeDetectorRef, private commandFactory: CommandFactory, private translate: TranslateService) {
  }

  ionViewWillEnter() {
    //this.serach();
    let self = this;
    self.curData.enabled = localStorage.getItem("Connection_tips");
    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }
  }

  ionViewDidEnter() {
    //this.navParams.get("")
    //初始化数据
    let self = this;
    //新版不可用，无法连接离线设备
    self.thisVersion = self.connectedDevice.thisversion;
    if (localStorage.getItem("local_waring_msg")) {
      self.dataLs = localStorage.getItem("local_waring_msg");
    }

    let lang = self.translate.getDefaultLang();
    self.email.body = self.email.body.replace("2.0.1", self.version).replace("中文", lang);


    $("#lbltemplateName").text("Watering  plan 1");
    self.nativeService.queryDeviceTemplateData("templateName", "isChecked=1", (r) => {
      AppConfig.consoleLog(r);
      if (r.result > 0) {
        if (r.rows.length > 0) {
          $("#lbltemplateName").text(r.rows[0].templateName);
        }
      }
    })

  }

  goLanguageSetting() {
    this.navCtrl.push(LanguageSettingPage);
  }

  //浇水计划设置
  goWateringPlanSetting() {
    this.navCtrl.push(settingWateringPlanPage);
  }

  goAppAbout() {
    this.navCtrl.push(AppAboutPage);
  }

  goSupport() {
    // window.open("https://www.hunterindustries.com/cn/node/81606","_blank");
    this.commandFactory.openUrl("https://www.hunterindustries.com/support/controllers/btt");
  }

  goHunter() {
    //window.open("https://www.hunterindustries.com/cn","_blank");
    this.commandFactory.openUrl("https://www.hunterindustries.com/");
  }

  goFeedback() {
    //this.emailComposer.open(this.email);

    this.commandFactory.sendEmail();
  }

  shareUrl(){
    this.commandFactory.shareUrl("https://play.google.com/store/apps/details?id=com.hunter.btt");
  }

  goGoolePlay() {
    //window.open("https://www.hunterindustries.com/cn","_blank");
    this.commandFactory.openUrl("https://play.google.com/store/apps/details?id=com.hunter.btt");
  }

  goBack() {
    this.navCtrl.pop({animate:false});
  }

  //是否自动连接设置
  clickSwitchSystem(evl) {
    if (evl.checked) {
      localStorage.setItem("Connection_tips", "true");
    } else {
      localStorage.setItem("Connection_tips", "false");
    }
  }

}



