import {MenuController, NavController, NavParams, Platform, Tabs, App} from 'ionic-angular';
import {MoreHomePage} from "../../more/moreHome/moreHome";
import {HomeBttsPage} from '../../btts/homeBtts/homeBtts';
import {TwoSchedulePage} from '../../twoExport/twoSchedule/twoSchedule';
import {ChangeDetectorRef, Component, ViewChild} from '@angular/core';
import {bttTestPage} from "../../btts/bttTest/bttTest";
import {CommandFactory} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";
import {DeviceNoConnect} from "../../btts/deviceNoConnect/deviceNoConnect";

declare var cordova: any;
declare var $: any;
declare var app: any;
declare var navPage: any;

@Component({
  selector: 'page-nav',
  templateUrl: 'nav.html'
})

export class NavPage {
  @ViewChild('myTabs') tabRef: Tabs;

  public rootPage0: any = HomeBttsPage;
  public rootPage1: any = DeviceNoConnect;
  public rootPage2: any = MoreHomePage;
  public rootPage3: any = bttTestPage;

  constructor(
    public navCtrl: NavController,
    public  menu: MenuController,
    public  NavParams: NavParams,
    public cd: ChangeDetectorRef,
    public appCtrl: App,
  ) {
    navPage = this;
  }

  ionViewDidEnter() {
    let self = this;
    $('a.tab-button').on(
      'click',
      function () {
        let index = $(this).parent().children().index(this);
        if (index > -1 && index < 3) {
          // if (index == 2) {
          //   AppConfig.loadFinish = false;
          // }else{
          //   AppConfig.loadFinish = true;
          // }

          //选择的是调度页
          if (index == 1 && (AppConfig.runInfo['selectOnlineDevice'] || AppConfig.runInfo['selectOfflineDevice'])) {

            //选择的是调度页
            let isOnline = AppConfig.runInfo['isOnline'];
            let isTwoMode = AppConfig.runInfo['isTwoMode'];
            let thisVersion = AppConfig.runInfo['thisversion'];
            let thisVersionType = AppConfig.runInfo['thisversiontype'];
            if (AppConfig.runInfo['selectOnlineDevice']) {
              isOnline = 1;
              isTwoMode = AppConfig.runInfo['selectOnlineDevice']['type'] == 'Second' ? 1 : 0;
              thisVersion = AppConfig.runInfo['selectOnlineDevice']['thisversion'];
              thisVersionType = AppConfig.runInfo['selectOnlineDevice']['thisversiontype'];
            } else if (AppConfig.runInfo['selectOfflineDevice']) {
              isOnline = 0;
              isTwoMode = AppConfig.runInfo['selectOfflineDevice']['type'] == 'Second' ? 1 : 0;
              thisVersion = AppConfig.runInfo['selectOfflineDevice']['thisversion'];
              thisVersionType = AppConfig.runInfo['selectOfflineDevice']['thisversiontype'];
            }

            app.autoTabGo(
              self.navCtrl,
              AppConfig.runInfo['selectOnlineDevice'],
              AppConfig.runInfo['selectOfflineDevice'],
              isTwoMode,
              isOnline,
              1, true, null, null, null,
              thisVersion,
              thisVersionType, null
            );
          }
          //手动选择指定tab页
          self.tabRef.select(index).then(() => {

          });
          return true;
        }
      }
    );
  }
}



