import {NavController, NavParams, Platform} from 'ionic-angular';
import {Component} from '@angular/core';
import {NativeService} from "../../../util/NativeService";
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {ChangeDetectorRef} from '@angular/core';
import {HttpHelper} from "../../../util/HttpHelper";
import {AppConfig} from "../../../app/appconfig";
import {AppAboutPage} from "../../more/appAbout/appAbout";
import {VersionBttsUpdateListPage} from '../versionBttsUpdateList/versionBttsUpdateList'

declare var $: any;
declare var cordova: any;
declare var app: any;

@Component({
  selector: 'selector-versionBtts',
  templateUrl: 'versionBtts.html'
})

export class VersionBttsPage {
  pandaLoading: any = null;
  curDevice: any = {
    nickName: null,
    name: '',
    address: '',
    type: '',
    rssi: 0,
    connected: false,
    password: null,
    firmware: null
  };
  address: any = null;
  isPasscode = false;
  fileUrl: any = null;
  max: number = 0;
  DateSecond_9Ecompleted: number = 0;

  promptContent = "";
  promptTitle = "";
  version = "";

  connectedDevice: any = null;
  thisVersion: any = null;

  constructor(private cdr: ChangeDetectorRef, private platform: Platform, private httpHelper: HttpHelper, private nativeService: NativeService,
              private  navParams: NavParams, public navCtrl: NavController, private  commandFactory: CommandFactory, private translate: TranslateService) {
    app.versionPage = this;
    //在index.html调用
    //{
    //  app.versionPage.max=100;
    //  app.versionPage.DateSecond_9Ecompleted=50;
    //  app.versionPage.cdr.detectChanges();
    //}
  }

  ionViewWillEnter() {
    let self = this;

    self.address = self.navParams.get("address");
    AppConfig.consoleLog(self.address);
    self.curDevice = self.commandFactory.findDeviceByAttr("address", self.address, 2);

    //0为离线 1为在线
    if (AppConfig.runInfo["isOnline"] == 1) {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
      self.connectedDevice["isOnline"] = true;
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
      self.connectedDevice["isOnline"] = false;
    }
    self.thisVersion = self.connectedDevice.thisversion;
    if (self.thisVersion > 3) {
      $("#showdetail").show();
    } else {
      $("#showdetail").hide();
    }
    //region 请求固件是否有升级接口
    //code=fw-01
    //version=版本号(下发固件版本协议后获取的版本号，例如取得为Version 5.0.0.2，则传递5.0.0.2)
    //http://ais.hyruanjian.cn/Common/GetUpgradeInfo
    self.httpHelper.post(AppConfig.GetInterFaceUrl() + "Common/GetUpgradeInfo", {
      code: "fw-01",
      version: self.curDevice.firmware.replace("Version ", "")
    }).then((data) => {
      var varResult = data.json();
      AppConfig.consoleLog(varResult)
      if (varResult.result > 0) {
        if (varResult.rows.length > 0) {
          $("#redtips").css("display", "");
          let fileName = varResult.rows[0].fileName;//"Yilin_Hunter_BTT2_3V_20210111_V.5.0.0.2.oad.bin"
          self.fileUrl = varResult.rows[0].fileUrl;//"/Upload/1/20210111/c292f64b-f12f-4268-ae43-6307c65d4bea.bin"
          self.promptContent = varResult.rows[0].promptContent;//"有最新版本，请升级！"
          self.promptTitle = varResult.rows[0].promptTitle;//"系统提示"
          self.version = varResult.rows[0].version; //5.0.0.2
        } else {

        }
      }
    })
    //endregion

    let Second_81 = self.commandFactory.getCommand(ProtocolType.Second_81);
    self.nativeService.queryDeviceData("nickName,password", "address='" + self.address + "'", function (r) {
      AppConfig.consoleLog(r);
      if (r.result > 0) {
        self.curDevice.nickName = r.rows[0].nickName;
        self.curDevice.password = Second_81.password.replace(/(\u0000)+/, "").toString().trim();//r.rows[0].password;
        if (!r.rows[0].nickName)
          self.curDevice.nickName = null;
        // if(r.rows[0].password=="null"||!r.rows[0].password)
        //   self.curDevice.password=null;
      }
      if (self.curDevice.password) self.isPasscode = true;

      if (localStorage.getItem("local_device_list")) {
        let local_device_list = JSON.parse(localStorage.getItem("local_device_list"));
        ////console.log(local_device_list);
        ////console.log(self.curDevice.address+","+self.curDevice.nickName);
        for (let i = 0; i < local_device_list.length; i++) {
          if (local_device_list[i].address == self.curDevice.address) {
            local_device_list[i].password = self.curDevice.password.toString().trim();
            if (self.curDevice.nickName) {
              local_device_list[i]["nickName"] = self.curDevice.nickName.toString().trim();
            } else {
              local_device_list[i]["nickName"] = "";
            }
            if (AppConfig.runInfo["isOnline"] == 0) {
              AppConfig.runInfo["selectOfflineDevice"] = local_device_list[i];
            } else {
              AppConfig.runInfo["selectOnlineDevice"] = local_device_list[i];
            }
            break;
          }
        }
        localStorage.setItem("local_device_list", JSON.stringify(local_device_list));
      }
    })
    AppConfig.consoleLog(self.curDevice);
  }


  save() {
    let self = this;
    let msg = this.translate.get("msg.passcodeChanged")["value"];
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");

    let Second_81 = self.commandFactory.getCommand(ProtocolType.Second_81);
    //Second_81.password = self.curDevice.password.toString().trim();
    Second_81.password = '\u0000\u0000\u0000';
    self.commandFactory.send_2("VersionBttsPage", Second_81);
    self.commandFactory.editCommand2(Second_81);
    self.curDevice.password = '';
    // self.nativeService.updateDeviceData(updateTime, self.curDevice.nickName, self.curDevice.password, self.curDevice.address, (r) => {
    //   AppConfig.consoleLog(r);
    // });
    self.nativeService.updateDeviceData(updateTime, self.curDevice.nickName, '', self.curDevice.address, (r) => {
      AppConfig.consoleLog(r);
    });
    if (localStorage.getItem("local_device_list")) {
      let local_device_list = JSON.parse(localStorage.getItem("local_device_list"));
      for (let i = 0; i < local_device_list.length - 1; i++) {
        if (local_device_list[i].address == self.curDevice.address) {
          local_device_list[i].password = self.curDevice.password.toString().trim();
          if (self.curDevice.nickName) {
            local_device_list[i]["nickName"] = self.curDevice.nickName.toString().trim();
          } else {
            local_device_list[i]["nickName"] = "";
          }

          if (AppConfig.runInfo["isOnline"] == 0) {
            AppConfig.runInfo["selectOfflineDevice"] = local_device_list[i];
          } else {
            AppConfig.runInfo["selectOnlineDevice"] = local_device_list[i];
          }
          break;
        }
      }
      localStorage.setItem("local_device_list", JSON.stringify(local_device_list));
    }
    //self.commandFactory.showAlert(msg)
    self.goBack();
  }

  clickDisPasscode() {
    let self = this;
    let msg = this.translate.get("confirmDisablePasscode")["value"];
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
    self.commandFactory.showConfirm(msg, () => {

      let Second_81 = self.commandFactory.getCommand(ProtocolType.Second_81);
      Second_81.password = '\u0000\u0000\u0000';
      self.commandFactory.send_2("VersionBttsPage", Second_81)
        .then((success) => {
          AppConfig.consoleLog(success)
        });
      self.commandFactory.editCommand2(Second_81);

      self.nativeService.updateDeviceData(updateTime, self.curDevice.nickName, '', self.curDevice.address, (r) => {
        AppConfig.consoleLog(r);
        if (r.result > 0) {
          self.curDevice.password = null;
          if (localStorage.getItem("local_device_list")) {
            let local_device_list = JSON.parse(localStorage.getItem("local_device_list"));
            for (let i = 0; i < local_device_list.length - 1; i++) {
              if (local_device_list[i].address == self.curDevice.address) {
                local_device_list[i].password = self.curDevice.password.toString().trim();
                break;
              }
            }
            localStorage.setItem("local_device_list", JSON.stringify(local_device_list));
          }

          msg = this.translate.get("passcodeChanged")["value"];
          self.commandFactory.showAlert(msg);
        } else {
          msg = this.translate.get("passcodeDisableError")["value"];
          self.commandFactory.showAlert(msg);
        }
        self.goBack();
      });
    });

  }

  viewEnterPirseInfo(entId: number) {
  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }

  godetails() {

    this.navCtrl.push(VersionBttsUpdateListPage);
  }

  goUpdate() {
    AppConfig.consoleLog(2);
    let me = this;
    let updateTime: string = me.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
    //onOADProgressUpdate()
    let promptTitle = me.translate.get("versionBtt.promptTitle")["value"]
    let promptContent = me.translate.get("versionBtt.promptContent")["value"]

    let curDeviceName: any = null;
    let tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
    for (let i = 0; i < tempDevice.length; i++) {
      if (tempDevice[i]["connected"] == true) {
        curDeviceName = tempDevice[i]["name"];
        break;
      }
    }
    me.commandFactory.showConfirm(promptContent + "\n" + "version ：" + me.version, () => {
      me.platform.ready()
        .then(
          () => {
            cordova.plugins.AisBlePlugin.remoteOADUpdate(
              AppConfig.GetInterFaceUrl() + me.fileUrl,
              function (info) {
                AppConfig.consoleLog(info);
                me.showPandaLoading();
                $("#redtips").css("display", "none");

                me.nativeService.insertDeviceBasicData("VersionBttsPage" + me.version, curDeviceName + "_" + me.version, 0, 1, updateTime, (r2) => {
                  AppConfig.consoleLog(r2);
                })
              },
              function (errMsg) {
                AppConfig.consoleLog(errMsg);
              }
            );
          }
        );
    }, null, promptTitle);
  }

  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    }, '', 99999);
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }

}



