  /**
   * 主动接收到通知消息
   * @param me
   * @param protocol  json协议数据
   */
  onZoneImageReceiveCompleted(me, protocol) {
    try {
      if ((protocol.protocolType == "Second_8a" && me.siteIndex == 1)
        || (protocol && (protocol.protocolType == "Second_8f" && me.siteIndex == 2))) {
        if (AppConfig.runInfo["isOnline"] == 1) {
          me.notfiZoneStateAuto(protocol);
        }
      } else if (protocol && protocol.protocolType == "Second_82") {
        if (AppConfig.runInfo["isOnline"] == 1) {
          me.notifyZoneState_82(protocol);
        }
      }
    } catch (e) {
      AppConfig.consoleLog(e);
    }

  }

  notfiZoneStateAuto(cmdModel: any = null) {
    let self = this;

    //zone1
    if (cmdModel && cmdModel.protocolType == "Second_8a") {
      //定时自动
      if (cmdModel.type == 1) {
        self.zoneModeStatus.fixedTimeStatus.runTime = cmdModel.tmRunHour.parse2S() + ":" + cmdModel.tmRunMinute.parse2S() + ":" + cmdModel.tmRunSecond.parse2S();
      }
      //循环自动
      else if (cmdModel.type == 2) {
        //self.zoneModeStatus.circleTimeStatus.runTime = cmdModel.cmRunHour.parse2S() + ":" + cmdModel.cmRunMinute.parse2S() + ":" + cmdModel.cmRunSecond.parse2S();
        if (cmdModel.cmRunHour.parse2S() + ":" + cmdModel.cmRunMinute.parse2S() + ":" + cmdModel.cmRunSecond.parse2S() == "00:00:00") {
          self.zoneModeStatus.circleTimeStatus.runTime = "XXX";
        } else {
          self.zoneModeStatus.circleTimeStatus.runTime = cmdModel.cmRunHour.parse2S() + ":" + cmdModel.cmRunMinute.parse2S() + ":" + cmdModel.cmRunSecond.parse2S();
        }

      }
      //循环自动-入渗
      else if (cmdModel.type == 4) {
        //self.zoneModeStatus.circleTimeStatus.soakTime = cmdModel.cmSoakHour.parse2S() + ":" + cmdModel.cmSoakMinute.parse2S() + ":" + cmdModel.cmSoakecond.parse2S();

        if (cmdModel.cmSoakHour.parse2S() + ":" + cmdModel.cmSoakMinute.parse2S() + ":" + cmdModel.cmSoakecond.parse2S() == "00:00:00") {
          self.zoneModeStatus.circleTimeStatus.soakTime = "XXX";
        } else {
          self.zoneModeStatus.circleTimeStatus.soakTime = cmdModel.cmSoakHour.parse2S() + ":" + cmdModel.cmSoakMinute.parse2S() + ":" + cmdModel.cmSoakecond.parse2S();
        }

      } else {
        self.zoneModeStatus.fixedTimeStatus.runTime = self.zoneModeStatus.fixedTimeStatus.oldRunTime;
        self.zoneModeStatus.circleTimeStatus.runTime = self.zoneModeStatus.circleTimeStatus.oldRunTime;
        self.zoneModeStatus.circleTimeStatus.soakTime = self.zoneModeStatus.circleTimeStatus.oldSoakTime;
      }

    }
    //zone2
    if (cmdModel && cmdModel.protocolType == "Second_8f") {
      //定时自动
      if (cmdModel.type == 1) {
        self.zoneModeStatus.fixedTimeStatus.runTime = cmdModel.tmRunHour.parse2S() + ":" + cmdModel.tmRunMinute.parse2S() + ":" + cmdModel.tmRunSecond.parse2S();
      }
      //循环自动
      else if (cmdModel.type == 2) {
        //self.zoneModeStatus.circleTimeStatus.runTime = cmdModel.cmRunHour.parse2S() + ":" + cmdModel.cmRunMinute.parse2S() + ":" + cmdModel.cmRunSecond.parse2S();
        if (cmdModel.cmRunHour.parse2S() + ":" + cmdModel.cmRunMinute.parse2S() + ":" + cmdModel.cmRunSecond.parse2S() == "00:00:00") {
          self.zoneModeStatus.circleTimeStatus.runTime = "XXX";
        } else {
          self.zoneModeStatus.circleTimeStatus.runTime = cmdModel.cmRunHour.parse2S() + ":" + cmdModel.cmRunMinute.parse2S() + ":" + cmdModel.cmRunSecond.parse2S();
        }
      }
      //循环自动-入渗
      else if (cmdModel.type == 4) {
        //self.zoneModeStatus.circleTimeStatus.soakTime = cmdModel.cmSoakHour.parse2S() + ":" + cmdModel.cmSoakMinute.parse2S() + ":" + cmdModel.cmSoakecond.parse2S();
        if (cmdModel.cmSoakHour.parse2S() + ":" + cmdModel.cmSoakMinute.parse2S() + ":" + cmdModel.cmSoakecond.parse2S() == "00:00:00") {
          self.zoneModeStatus.circleTimeStatus.soakTime = "XXX";
        } else {
          self.zoneModeStatus.circleTimeStatus.soakTime = cmdModel.cmSoakHour.parse2S() + ":" + cmdModel.cmSoakMinute.parse2S() + ":" + cmdModel.cmSoakecond.parse2S();
        }
      } else {
        self.zoneModeStatus.fixedTimeStatus.runTime = self.zoneModeStatus.fixedTimeStatus.oldRunTime;
        self.zoneModeStatus.circleTimeStatus.runTime = self.zoneModeStatus.circleTimeStatus.oldRunTime;
        self.zoneModeStatus.circleTimeStatus.soakTime = self.zoneModeStatus.circleTimeStatus.oldSoakTime;
      }

    }
    // self.cd.markForCheck();
    if (this.cd !== null && this.cd !== undefined &&
      !(this.cd as ViewRef_).destroyed) {
      this.cd.detectChanges();
    }
    // self.cd.detectChanges();
  }

  notifyZoneState_82(cmdModel: any = null) {
    let self = this;
    if (cmdModel.zone1State == 1 && cmdModel.zone1Mode == 1) {
      self.zoneModeStatus.fixedTimeStatus.runTime = self.zoneModeStatus.fixedTimeStatus.oldRunTime;
    } else if (cmdModel.zone1State == 1 && cmdModel.zone1Mode == 2) {
      self.zoneModeStatus.circleTimeStatus.runTime = self.zoneModeStatus.circleTimeStatus.oldRunTime;
      self.zoneModeStatus.circleTimeStatus.soakTime = self.zoneModeStatus.circleTimeStatus.oldSoakTime;
    }

    if (cmdModel.zone2State == 1 && cmdModel.zone2Mode == 1) {
      self.zoneModeStatus.fixedTimeStatus.runTime = self.zoneModeStatus.fixedTimeStatus.oldRunTime;
    } else if (cmdModel.zone2State == 1 && cmdModel.zone2Mode == 2) {
      self.zoneModeStatus.circleTimeStatus.runTime = self.zoneModeStatus.circleTimeStatus.oldRunTime;
      self.zoneModeStatus.circleTimeStatus.soakTime = self.zoneModeStatus.circleTimeStatus.oldSoakTime;
    }
    if (this.cd !== null && this.cd !== undefined &&
      !(this.cd as ViewRef_).destroyed) {
      this.cd.detectChanges();
    }
    // self.cd.detectChanges();
  }

  //取消挂起浇水
  cancelSuspendWatering(cmd82: any = null) {
    let self = this;
    let Second_82 = self.commandFactory.getCommand(ProtocolType.Second_82);
    let res_83 = self.commandFactory.readlocalProtocol(ProtocolType.Second_83, self.connectedDevice);
    // self.commandFactory.readRemote(ProtocolType.Second_83, (success_83) => {
    //   let res_83 = success_83;
    if (cmd82.zone1State == 1) res_83.zone1EnableManual = false;
    if (cmd82.zone2State == 1) res_83.zone2EnableManual = false;
    let zone1Mode = res_83.zone1Mode * res_83.zone2Mode;
    if (res_83.zone1Mode == 0 && self.siteIndex == 1) {
      res_83.zone1Mode = Second_82.zone1Mode;
      cmd82.zone1Mode = Second_82.zone1Mode;
    }
    if (res_83.zone2Mode == 0 && self.siteIndex == 2) {
      res_83.zone2Mode = Second_82.zone2Mode;
      cmd82.zone2Mode = Second_82.zone2Mode;
    }
    self.commandFactory.editCommand2(cmd82);

    if (zone1Mode == 0) {
      self.commandFactory.editCommand2(res_83);
      self.commandFactory.send_2("twoSchedule", res_83)
        .then((scuccess) => {
          AppConfig.consoleLog(scuccess);
        });
    }
    //}, null, self.connectedDevice)
  }

