  getNewRunTime(times, type) {
    let self = this;
    let Percentage;
    if (self.initSecond_9C) {
      if (self.initSecond_9C.config.length > 0) {
        for (var i = 0; i < 12; i++) {
          if (self.initSecond_9C.config[i] < 0) {
            self.initSecond_9C.config[i] = self.initSecond_9C.config[i] + 256;
          }
        }
        if (self.initSecond_9C.isGlobal == true) {
          Percentage = self.initSecond_9C.config[0] / 100;
        } else {
          let thisMonth = self.utilityService.getDateMonth(0);
          Percentage = (self.initSecond_9C.config[thisMonth - 1]) / 100;
        }
        let tempTimes = times.split(':');
        let newSeconds = Percentage * (parseInt(tempTimes[0]) * 60 * 60 + parseInt(tempTimes[1]) * 60 + parseInt(tempTimes[2]));
        let hour = parseInt((newSeconds / 3600).toString())
        let min = parseInt(((newSeconds - (hour * 3600)) / 60).toString());
        let sec = parseInt((newSeconds - (hour * 3600) - (min * 60)).toString());
        if (type == 1) {
          self.zoneModeStatus.fixedTimeStatus.runTime = (hour < 10 ? "0" + hour.toString() : hour.toString()) + ":" + (min < 10 ? "0" + min.toString() : min.toString()) + ":" + (sec < 10 ? "0" + sec.toString() : sec.toString());
          self.zoneModeStatus.fixedTimeStatus.oldRunTime = (hour < 10 ? "0" + hour.toString() : hour.toString()) + ":" + (min < 10 ? "0" + min.toString() : min.toString()) + ":" + (sec < 10 ? "0" + sec.toString() : sec.toString());
        } else {
          self.zoneModeStatus.circleTimeStatus.runTime = (hour < 10 ? "0" + hour.toString() : hour.toString()) + ":" + (min < 10 ? "0" + min.toString() : min.toString()) + ":" + (sec < 10 ? "0" + sec.toString() : sec.toString());
          self.zoneModeStatus.circleTimeStatus.oldRunTime = (hour < 10 ? "0" + hour.toString() : hour.toString()) + ":" + (min < 10 ? "0" + min.toString() : min.toString()) + ":" + (sec < 10 ? "0" + sec.toString() : sec.toString());
        }
      }
    }

    if (this.cd !== null && this.cd !== undefined &&
      !(this.cd as ViewRef_).destroyed) {
      this.cd.detectChanges();
    }


  }

