  //复制定时时间表到站点2
  copyTimerZone1ToZone2() {
    let self = this;
    let localtypeId = localStorage.getItem("homePageTypeId");
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");

    let SecondCmd = self.commandFactory.getCommand(ProtocolType.Second_87);
    SecondCmd.protocolType = "Second_8c";

    let SecondCmdA1 = self.commandFactory.getCommand(ProtocolType.Second_A0);
    SecondCmdA1.protocolType = "Second_A1";

    let cmdMode = self.commandFactory.getCommand(ProtocolType.Second_86);
    cmdMode.protocolType = "Second_8b";

    self.commandFactory.editCommand2(SecondCmd);
    self.commandFactory.editCommand2(SecondCmdA1);


    //复制模式
    let res83 = self.commandFactory.readlocalProtocol(ProtocolType.Second_83, self.connectedDevice);
    res83.zone2Mode = res83.zone1Mode;
    self.commandFactory.editCommand2(res83);
    self.commandFactory.send_2("zone_res83", res83)
      .then((success8c) => {
      })

    self.commandFactory.send_2("zone_mode_site8c", SecondCmd)
      .then((success8c) => {
        AppConfig.consoleLog(success8c);
        let jsonSecond_8C = JSON.stringify(SecondCmd);
        self.nativeService.insertDeviceBasicData("Second_8c", jsonSecond_8C, localtypeId, 1, updateTime, (r8c) => {
          AppConfig.consoleLog(r8c);
        })
        //发送浇水日
        self.commandFactory.send_2("zone_mode_site_Second_8b", cmdMode)
          .then((success) => {
            AppConfig.consoleLog(success);
            let message = (self.translate.get("msg.Zone_Copy_Succeeded")["value"] + "");
            self.commandFactory.showToast_2(message);
            self.commandFactory.send_2("zone_mode_siteA1", SecondCmdA1)
              .then((successA1) => {
                AppConfig.consoleLog(successA1);
                let jsonSecond_A1 = JSON.stringify(SecondCmdA1);
                self.nativeService.insertDeviceBasicData("Second_A1", jsonSecond_A1, localtypeId, 1, updateTime, (rA1) => {
                  AppConfig.consoleLog(rA1);
                })
              }, (error) => {
                AppConfig.consoleLog(error);
              });
          }, (error) => {
            AppConfig.consoleLog(error);
          });
      }, (error) => {
        AppConfig.consoleLog(error);
      });
  }

