  parse2Str(val) {
    if (!val) return val;
    if (typeof (val) === "string") {
      if (0 <= parseInt(val) && parseInt(val) < 10) return "0" + val.toString().trim();
      return val.toString().trim();
    } else if (typeof (val) === "number") {
      if (0 <= val && val < 10) return "0" + val.toString();
      return val.toString();
    }
    return null;

  }
