import {NavController} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {Component, OnInit} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {ChangeDetectorRef} from '@angular/core';
import {SettingHomePage_1} from "../settingHome_1/settingHome_1";
import {CommandFactory} from "../../../util/CommandFactory";
import {VersionBttsPage_1} from "../../btts_1/versionBtts_1/versionBtts_1";
import {AppConfig} from "../../../app/appconfig";
import {SettingBttsPage} from "../../more/settingBtts/settingBtts";

declare var app: any;


declare var monitorTab: any;
declare var destoryTabPage: any;

@Component({
  selector: 'selector-more_1',
  templateUrl: 'moreHome_1.html'
})

export class MoreHomePage_1 {
  public list: any = [];

  _deviceAry: any = [];
  _offlinedeviceAry: any = [];
  _showConnectedList: boolean = false;
  _showPreviouslyConnectedList: boolean = false;

  //搜索定时器
  _reqRequestSearchTimer: any = null;
  _isSearching: boolean = false;
  //蓝牙扫描定时器
  _scanRetryTimer: any = null;

  public currentUserInfo: any = {};

  pageId: string = '';

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper,
              public navCtrl: NavController, public cd: ChangeDetectorRef,
              private commandFactory: CommandFactory) {
    this.pageId = Math.random().toString().replace('.', '');
  }

  ionViewWillUnload() {
    let self = this;

    destoryTabPage(self, 2);
    console.log('pageId=' + self.pageId + ',销毁....................................');
  }

  /**
   * 进入处理
   * @param self
   */
  doEnter(self) {
    //隐藏进度条

    console.log('pageId=' + self.pageId + ',doEnter....................................');
  }

  /**
   * 离开处理
   * @param self
   */
  doLeave(self) {
    //清除资源


    console.log('pageId=' + self.pageId + ',doLeave..................................');
  }

  ionViewDidEnter() {
    let self = this;

    //监控页面是否发生变化
    monitorTab(this, 2, self.doEnter, self.doLeave);

  }

  ionViewWillEnter() {
    // let self=this;
    // self.commandFactory.getDeviceLs().then((success)=>{
    //   AppConfig.consoleLog(success);
    //   self.list=success;
    // },(error)=>{
    //   AppConfig.consoleLog(error)
    // });

    let self = this;
    //自动启动设备扫描
    //self.startScanBluetooth();
    self._showConnectedList = false;
    self._showPreviouslyConnectedList = false;
    self._deviceAry = [];
    let _onlinedevice: any = AppConfig.runInfo["selectOnlineDevice"];
    if (_onlinedevice) {
      self._showConnectedList = true;
      self._deviceAry.push(_onlinedevice);
    } else {
      self._showConnectedList = false;
    }


    let _local: any = JSON.parse(localStorage.getItem("local_device_list_connected"));
    for (let q = 0; q < _local.length; q++) {
      if (_onlinedevice) {
        if (_onlinedevice.address == _local[q].address) {
          _local.splice(q, 1)
          break;
        }
      }
    }
    if (_local.length > 0) {
      self._showPreviouslyConnectedList = true;
      self._offlinedeviceAry = _local;
    } else {
      self._showPreviouslyConnectedList = false;
    }
  }

  goSettingHome() {
    this.navCtrl.push(SettingHomePage_1);
    AppConfig.consoleLog("HELLO")
  }

  //跳转到设备设置页面
  goSettingBtts(address) {
    let self = this;
    let bttS: any = self.commandFactory.findDeviceByAttr("address", address, 2);
    if (bttS.type == "Second") {
      app.autoTabGo(
        self.navCtrl,
        bttS,
        AppConfig.runInfo['selectOfflineDevice'],
        1,
        1,
        2,
        false,
        2,
        SettingBttsPage,
        {address: address}, bttS["thisversion"], bttS["thisversiontype"],true
      );
      // self.navCtrl.push(SettingBttsPage, {address: address});
    } else {
      app.autoTabGo(
        self.navCtrl,
        bttS,
        AppConfig.runInfo['selectOfflineDevice'],
        0,
        1,
        2,
        false,
        2,
        VersionBttsPage_1,
        {address: address}, bttS["thisversion"], bttS["thisversiontype"],true
      );
      //self.navCtrl.push(VersionBttsPage_1, {address: address});
    }
  }

  //跳转到设备设置页面
  goSettingBttsoffline(address) {
    let self = this;
    let bttS: any = self.commandFactory.findDeviceByAttr("address", address, 2);
    if (bttS.type == "Second") {
      app.autoTabGo(
        self.navCtrl,
        AppConfig.runInfo['selectOnlineDevice'],
        bttS,
        1,
        0,
        2,
        false,
        2,
        SettingBttsPage,
        {address: address}, bttS["thisversion"], bttS["thisversiontype"],true
      );
      //self.navCtrl.push(SettingBttsPage, {address: address});
    } else {
      app.autoTabGo(
        self.navCtrl,
        AppConfig.runInfo['selectOnlineDevice'],
        bttS,
        0,
        0,
        2,
        false,
        2,
        VersionBttsPage_1,
        {address: address}, bttS["thisversion"], bttS["thisversiontype"],true
      );
      //self.navCtrl.push(VersionBttsPage_1, {address: address});
    }
  }

}



