import {NavController, IonicModule, AlertController, ActionSheetController, NavParams, Platform} from 'ionic-angular';
import {ChangeDetectorRef, Component} from "@angular/core";
import {NativeService} from "../../../util/NativeService";
import {CommandFactory} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";


declare var cordova: any;
declare var $: any;

@Component({
  selector: 'selector-locationSettings',
  templateUrl: 'locationSettings.html'
})

export class LocationSettingsPage {
  name: any = "";
  address: any = "";
  devicePic: any = "";
  mapPic: any = "";
  serialNumber: any = "";
  firmwareVersion: any = "";
  site: any = "";
  passcode: any = "";
  lng: any = null;
  lat: any = null;
  //photoUrl=null;
  photoUrl: any = "assets/images/img-1.png";
  connectedDevice: any = null;
  type: any = null;
  mac: any = null;
  markerid: any = null;

  constructor(private nativeService: NativeService, private translate: TranslateService,
              private commandFactory: CommandFactory, private platform: Platform,
              private  navParams: NavParams, public navCtrl: NavController, public cd: ChangeDetectorRef, public actionSheetCtrl: ActionSheetController) {

  }

  goBack() {
    this.navCtrl.pop();
  }

  clickPhoto() {
    let self = this;
    this.nativeService.takePicture(null).then((val) => {
      //alert(val);
      if (val) {
        val = "file:///" + val;
        self.photoUrl = val.toString();
        self.devicePic = val.toString();

      }
    }, (error) => {
      AppConfig.consoleLog(error);
    });
  }

  ionViewDidEnter() {
    var me = this;
    $("#divRemoveMap").hide();
    me.type = this.navParams.get("type");
    me.mac = this.navParams.get("mac");
    me.lng = this.navParams.get("lng");
    me.lat = this.navParams.get("lat");
    AppConfig.consoleLog("接收传递坐标：" + me.lng + "," + me.lat);

    if (AppConfig.runInfo["isOnline"] == 0) {
      me.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      me.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }
    let thisversion: any = localStorage.getItem("thisversiontype");

    if (me.type == "edit") {
      $("#divRemoveMap").show();
      me.nativeService.queryDeviceMapData("*", "mac = '" + me.connectedDevice["address"] + "'", function (r) {
        if (r.result > 0) {
          let cons = r.rows[0];
          me.name = cons.name;
          me.address = cons.address;
          me.devicePic = cons.devicePic;
          me.serialNumber = cons.serialNumber;
          me.firmwareVersion = cons.firmwareVersion;
          me.site = cons.site;
          me.markerid = cons.id;
          me.lat = parseFloat(cons.lat);
          me.lng = parseFloat(cons.lng);
        }
      })
    } else {
      $("#divRemoveMap").hide();
      me.name = me.connectedDevice["name"];
      me.firmwareVersion = me.connectedDevice["firmware"];
      if (thisversion == "2C") {
        me.site = "2";
      } else {
        me.site = "1";
      }
    }


  }

  save() {
    var me = this;
    let updateTime: string = me.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
    let curDeviceMac: any = null;
    let tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
    for (let i = 0; i < tempDevice.length; i++) {
      if (tempDevice[i]["connected"] == true) {
        curDeviceMac = tempDevice[i]["address"];
        break;
      }
    }

    //type==edit 就是更新操作
    if (me.type == "edit") {
      me.nativeService.updateDeviceMapData(updateTime, me.name, me.address, me.devicePic, me.mapPic, me.serialNumber, me.firmwareVersion, me.site, me.passcode, me.lng, me.lat, curDeviceMac, (r) => {
        AppConfig.consoleLog(r);
        this.navCtrl.pop();
      })
    } else {
      /**
       * 插入地图标注信息
       * @param name
       * @param address
       * @param devicePic
       * @param mapPic
       * @param serialNumber 序列号
       * @param firmwareVersion 版本
       * @param site
       * @param passcode
       * @param lng
       * @param lat
       * @param mac
       * @param updateTime
       * @param callback
       */
      me.nativeService.insertDeviceMapData(me.name, me.address, me.devicePic, me.mapPic, me.serialNumber, me.firmwareVersion, me.site, me.passcode, me.lng, me.lat, curDeviceMac, updateTime, (r) => {
        AppConfig.consoleLog(r);
        this.navCtrl.pop();
      });
    }
  }

  //删除地图
  RemoveMap(markerid) {
    let msgcontent = this.translate.get("locationSettings.RemoveMapask")["value"];
    this.commandFactory.showConfirm(msgcontent, () => {
      this.platform.ready()
        .then(
          () => {
            this.nativeService.deleteDeviceMapTable(markerid, (r) => {
              AppConfig.consoleLog(r);
              this.navCtrl.pop();
            })
          }
        );
    });
  }
}




