import {NavController, NavParams} from 'ionic-angular';
import {Component} from '@angular/core';
import {SettingStationNamePage} from "../settingStationName/settingStationName";
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {ChoiceZcmInterval_2TimePage} from "../choiceZcmInterval_2Time/choiceZcmInterval_2Time";
import {NativeService} from './../../../util/NativeService';
import {AppConfig} from "../../../app/appconfig";

declare var $: any;

@Component({
  selector: 'selector-choiceZcmInterval_1Time',
  templateUrl: 'choiceZcmInterval_1Time.html'
})

export class ChoiceZcmInterval_1TimePage {
  pandaLoading: any = null;
  wIndex: any = 0;//1-定时 2-循环
  siteIndex: any = 0;
  zmInterval1 = 0;
  zmInterval2 = 0;
  pickerAry: any = null;
  connectedDevice: any = null;

  constructor(private nativeService: NativeService, public navCtrl: NavController, private  navParams: NavParams, private  commandFactory: CommandFactory) {

  }

  ionViewDidLoad() {

  }

  ionViewWillEnter() {
    let self = this;
    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }
  }

  ionViewDidEnter() {
    let self = this;
    self.siteIndex = self.navParams.get("siteIndex");
    self.wIndex = self.navParams.get("wIndex");
    let cmdMode = null;
    if (self.siteIndex == 1) {
      cmdMode = self.commandFactory.getCommand(ProtocolType.Second_86);
    } else {
      cmdMode = self.commandFactory.getCommand(ProtocolType.Second_8b);
    }
    //定时
    if (self.wIndex == 1) {
      if (cmdMode.ztmInterval1 == -1)
        self.zmInterval1 = 0;
      else
        self.zmInterval1 = cmdMode.ztmInterval1;
      if (cmdMode.ztmInterval2 == -1)
        self.zmInterval2 = 0;
      else
        self.zmInterval2 = cmdMode.ztmInterval2;
    }
    //循环
    else {
      if (cmdMode.zcmInterval1 == -1)
        self.zmInterval1 = 0;
      else
        self.zmInterval1 = cmdMode.zcmInterval1;

      if (cmdMode.zcmInterval2 == -1)
        self.zmInterval2 = 0;
      else
        self.zmInterval2 = cmdMode.zcmInterval2;
    }
    if (typeof (self.zmInterval1) == "string")
      self.zmInterval1 = parseInt(self.zmInterval1);
    if (typeof (self.zmInterval2) == "string")
      self.zmInterval2 = parseInt(self.zmInterval2);

    self.initPicker();
  }

  getValue() {
    //返回的为数组
    return $('#pageColpicker').coolpicker('getValue');
  }


  initPicker() {
    let self = this;
    let pickerAry = [];
    let colAry = [];
    for (let i = 1; i <= 31; i++) {
      colAry.push(i.toString());
    }
    pickerAry.push(colAry);

    this.pickerAry = pickerAry;
    if (self.wIndex == 1) {
      if (self.siteIndex == 1) {
        let res_read = self.commandFactory.readlocalProtocol(ProtocolType.Second_86, self.connectedDevice);
        // self.commandFactory.readRemote1(ProtocolType.Second_86,
        //   (success_read) => {
        //     let res_read = success_read;
        //     AppConfig.consoleLog(success_read);
        $('#pageColpicker').coolpicker({
          columnSpace: 0
        }).coolpicker(
          'loadData',
          [
            pickerAry[0]
          ]
        );

        //设置选择值
        $('#pageColpicker').coolpicker('setValue', [res_read.ztmInterval1]);
        // }, null, self.connectedDevice)
      } else {
        let res_read = self.commandFactory.readlocalProtocol(ProtocolType.Second_8b, self.connectedDevice);
        // self.commandFactory.readRemote1(ProtocolType.Second_8b,
        //   (success_read) => {
        //     let res_read = success_read;
        //     AppConfig.consoleLog(success_read);
        $('#pageColpicker').coolpicker({
          columnSpace: 0
        }).coolpicker(
          'loadData',
          [
            pickerAry[0]
          ]
        );

        //设置选择值
        $('#pageColpicker').coolpicker('setValue', [res_read.ztmInterval1]);
        // }, null, self.connectedDevice)
      }
    } else if (self.wIndex == 2) {
      if (self.siteIndex == 1) {

        let res_read = self.commandFactory.readlocalProtocol(ProtocolType.Second_86, self.connectedDevice);
        // self.commandFactory.readRemote1(ProtocolType.Second_86,
        //   (success_read) => {
        //     let res_read = success_read;
        //     AppConfig.consoleLog(success_read);
        $('#pageColpicker').coolpicker({
          columnSpace: 0
        }).coolpicker(
          'loadData',
          [
            pickerAry[0]
          ]
        );

        //设置选择值
        $('#pageColpicker').coolpicker('setValue', [res_read.zcmInterval1]);
        //}, null, self.connectedDevice)
      } else {
        let res_read = self.commandFactory.readlocalProtocol(ProtocolType.Second_8b, self.connectedDevice);
        // self.commandFactory.readRemote1(ProtocolType.Second_8b,
        //   (success_read) => {
        //     let res_read = success_read;
        //     AppConfig.consoleLog(success_read);
        $('#pageColpicker').coolpicker({
          columnSpace: 0
        }).coolpicker(
          'loadData',
          [
            pickerAry[0]
          ]
        );

        //设置选择值
        $('#pageColpicker').coolpicker('setValue', [res_read.zcmInterval1]);
        //}, null, self.connectedDevice)
      }
    }
  }

  saveData() {
    let self = this;
    self.showPandaLoading();
    let timeS = self.getValue();
    AppConfig.consoleLog(timeS);
    timeS[0] = timeS[0] == "" ? self.pickerAry[0][self.pickerAry[0].length - 1] : timeS[0];
    self.zmInterval1 = parseInt(timeS[0]);

    localStorage.setItem("zm_interval_zone" + self.siteIndex + "_switch" + self.wIndex, JSON.stringify({
      zcmInterval1: self.zmInterval1,
      zcmInterval2: self.zmInterval2,
      createTime: new Date().getTime()
    }));
    //定时模式
    if (self.wIndex == 1) {
      self.timeZcmIntervalChoice();
    }//循环模式
    else if (self.wIndex == 2) {
      self.cycZcmIntervalChoice();
    }

  }

  //定时-选择间隔
  timeZcmIntervalChoice() {
    let self = this;
    let localtypeId = localStorage.getItem("homePageTypeId");
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");

    //站点1
    if (self.siteIndex == 1) {
      let Second_86 = self.commandFactory.getCommand(ProtocolType.Second_86);
      // Second_86.ztmType=2;
      Second_86.ztmType = 4;

      Second_86.ztmInterval1 = self.zmInterval1;
      if (self.zmInterval1 == 0)
        Second_86.ztmInterval1 = -1;

      Second_86.ztmInterval2 = self.zmInterval2;
      // if(self.zmInterval2>0)
      //   Second_86.ztmType=4;
      if (self.zmInterval2 == 0)
        Second_86.ztmInterval2 = -1;
      //else Second_86.ztmType=4;

      self.commandFactory.editCommand2(Second_86);
      self.commandFactory.send_2("ChoiceZcmInterval_1TimePage", Second_86)
        .then((success) => {
          AppConfig.consoleLog((success))

          let jsonSecond_86 = JSON.stringify(Second_86)
          self.nativeService.insertDeviceBasicData("Second_86", jsonSecond_86, localtypeId, 1, updateTime, (r) => {
            AppConfig.consoleLog(r);

          })

          self.hidePandaLoading();
          var tempsiteIndex = JSON.parse(localStorage.getItem("tempsiteIndex"));
          AppConfig.consoleLog("tempsiteIndex" + tempsiteIndex.siteIndex, tempsiteIndex.wIndex);
          this.navCtrl.push(ChoiceZcmInterval_2TimePage, {
            siteIndex: tempsiteIndex.siteIndex,
            wIndex: tempsiteIndex.wIndex
          });
        });


    }//站点2
    else {
      let Second_8b = self.commandFactory.getCommand(ProtocolType.Second_8b);
      // Second_8b.ztmType=2;
      Second_8b.ztmType = 4;

      Second_8b.ztmInterval1 = self.zmInterval1;
      if (self.zmInterval1 == 0)
        Second_8b.ztmInterval1 = -1;

      Second_8b.ztmInterval2 = self.zmInterval2;
      // if(self.zmInterval2>0)
      //   Second_8b.ztmType=4;
      if (self.zmInterval2 == 0)
        Second_8b.ztmInterval2 = -1;
      //else Second_8b.ztmType=4;

      self.commandFactory.editCommand2(Second_8b);
      self.commandFactory.send_2("ChoiceZcmInterval_1TimePage", Second_8b)
        .then((success) => {
          AppConfig.consoleLog((success))
          self.hidePandaLoading();
          //self.goBack()
          let jsonSecond_8b = JSON.stringify(Second_8b)
          self.nativeService.insertDeviceBasicData("Second_8b", jsonSecond_8b, localtypeId, 1, updateTime, (r) => {
            AppConfig.consoleLog(r);

          })

          var tempsiteIndex = JSON.parse(localStorage.getItem("tempsiteIndex"));
          AppConfig.consoleLog("tempsiteIndex" + tempsiteIndex.siteIndex, tempsiteIndex.wIndex);
          this.navCtrl.push(ChoiceZcmInterval_2TimePage, {
            siteIndex: tempsiteIndex.siteIndex,
            wIndex: tempsiteIndex.wIndex
          });
        });
    }

  }

  //循环-选择间隔
  cycZcmIntervalChoice() {
    let self = this;
    let localtypeId = localStorage.getItem("homePageTypeId");
    let updateTime: string = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");

    //站点1
    if (self.siteIndex == 1) {
      let Second_86 = self.commandFactory.getCommand(ProtocolType.Second_86);
      // Second_86.zcmType=2;
      Second_86.zcmType = 4;

      Second_86.zcmInterval1 = self.zmInterval1;
      if (self.zmInterval1 == 0)
        Second_86.zcmInterval1 = -1;
      Second_86.zcmInterval2 = self.zmInterval2;
      // if(self.zmInterval2>0)
      //   Second_86.zcmType=4;
      if (self.zmInterval2 == 0)
        Second_86.zcmInterval2 = -1;
      //else Second_86.zcmType=4;

      self.commandFactory.editCommand2(Second_86);
      self.commandFactory.send_2("ChoiceZcmInterval_1TimePage", Second_86)
        .then((success) => {
          AppConfig.consoleLog((success))
          let jsonSecond_86 = JSON.stringify(Second_86)
          self.nativeService.insertDeviceBasicData("Second_86", jsonSecond_86, localtypeId, 1, updateTime, (r) => {
            AppConfig.consoleLog(r);

          })
          self.hidePandaLoading();
          self.goBack()
        });


    }//站点2
    else {
      let Second_8b = self.commandFactory.getCommand(ProtocolType.Second_8b);
      // Second_8b.zcmType=2;
      Second_8b.zcmType = 4;

      Second_8b.zcmInterval1 = self.zmInterval1;
      if (self.zmInterval1 == 0)
        Second_8b.zcmInterval1 = -1;
      Second_8b.zcmInterval2 = self.zmInterval2;
      // if(self.zmInterval2>0)
      //   Second_8b.zcmType=4;
      if (self.zmInterval2 == 0)
        Second_8b.zcmInterval2 = -1;
      //else Second_8b.zcmType=4;

      self.commandFactory.editCommand2(Second_8b);
      self.commandFactory.send_2("ChoiceZcmInterval_1TimePage", Second_8b)
        .then((success) => {
          AppConfig.consoleLog((success))
          let jsonSecond_8b = JSON.stringify(Second_8b)
          self.nativeService.insertDeviceBasicData("Second_8b", jsonSecond_8b, localtypeId, 1, updateTime, (r) => {
            AppConfig.consoleLog(r);

          })
          self.hidePandaLoading();
          self.goBack()
        });
    }

  }

  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    });
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }

  goBack() {
    this.navCtrl.pop();
  }

}



