  /**
   * 主动接收到通知消息
   * @param me
   * @param protocol  json协议数据
   */
  onOneNotifyReceive(me, protocol) {
    try {
      AppConfig.consoleLog(protocol);
      //手动停止通知
      if (protocol && (protocol.protocolType == "First_d9" || protocol.protocolType == "First_eb")) {
        if (protocol.control == 0) {
          me.isManualMonitorStart = false;
          me.cd.detectChanges();
          let msgComlete = me.translate.get("msg.zmWateringComplete")["value"];
          me.commandFactory.showToast_2(msgComlete);
        }
      }
      //循环自动通知
      else if (protocol && (protocol.protocolType == "First_e6" || protocol.protocolType == "First_e7")) {
        me.notiCyclingAuto(protocol);
      }
    } catch (e) {
      AppConfig.consoleLog(e);
    }
  }

  /**
   * 主动接收到通知消息
   * @param me
   * @param protocol  json协议数据
   */
  onZoneImageReceiveCompleted(me, protocol) {
    try {
      AppConfig.consoleLog(protocol);
      //手动停止通知
      if (protocol && (protocol.protocolType == "First_d9" || protocol.protocolType == "First_eb")) {
        if (protocol.control == 0) {
          me.isManualMonitorStart = false;
          me.cd.detectChanges();
          let msgComlete = me.translate.get("msg.zmWateringComplete")["value"];
          me.commandFactory.showToast_2(msgComlete);
        }
      }
      //循环自动通知
      else if (protocol && (protocol.protocolType == "First_e6" || protocol.protocolType == "First_e7" || protocol.protocolType == "First_d2")) {
        me.notiCyclingAuto(protocol);
      }
    } catch (e) {
      AppConfig.consoleLog(e);
    }
  }


