  //信号量默认值
  _signalValue: number = -60;

  /**
   * 更新信号量
   */
  updateDeviceSignal() {
    let self = this;

    //画信号量
    //self.commandFactory.signalCanvas(self._signalValue);

    self.imgsignal = self.commandFactory.loadingsignalimg(self._signalValue);
    //清除定时器
    self.stopMonitorDeviceSignal()

    //创建定时器
    AppConfig.runInfo['timer']['monitor.device.rssi'] = window.setInterval(
      () => {
        self.commandFactory.getCurDeviceRssi()
          .then((success) => {
              self._signalValue = parseInt(success.toString());
              //递归更新信号量
              self.updateDeviceSignal();
            },
            (error) => {
              AppConfig.consoleLog(error);
              //递归更新信号量
              self.updateDeviceSignal();
            });
      },
      2000);
  }

  /**
   * 启动监控信号强度变化
   */
  startMonitorDeviceSignal() {
    let self = this;
    let timer = window.setInterval(
      function () {
        //清除定时器
        window.clearInterval(timer);
        //启动更新
        self.updateDeviceSignal();
      },
      500
    );
  }

  /**
   * 停止信号强度变化
   */
  stopMonitorDeviceSignal() {
    let self = this;
    if (AppConfig.runInfo['timer']['monitor.device.rssi']) {
      window.clearInterval(AppConfig.runInfo['timer']['monitor.device.rssi']);
      AppConfig.runInfo['timer']['monitor.device.rssi'] = null;
    }
  }


  notiCyclingAuto(cmdModel) {
    let self = this;
    // if (cmdModel.protocolType == "First_e6") {
    //   self.modeStatus.circleTimeStatus.runTime = cmdModel.hour + ":" + cmdModel.minute + ":" + cmdModel.second;
    // } else if (cmdModel.protocolType == "First_e7") {
    //   self.modeStatus.circleTimeStatus.soakTime = cmdModel.hour + ":" + cmdModel.minute + ":" + cmdModel.second;
    // }
    if (cmdModel.protocolType == "First_e6") {
      self.modeStatus.circleTimeStatus.runTime = self.nativeService.transFormat(cmdModel.hour + ":" + cmdModel.minute + ":" + cmdModel.second, 'hour:min:sec');
    } else if (cmdModel.protocolType == "First_e7") {
      self.modeStatus.circleTimeStatus.soakTime = self.nativeService.transFormat(cmdModel.hour + ":" + cmdModel.minute + ":" + cmdModel.second, 'hour:min:sec');
    } else if (cmdModel.protocolType == "First_d2") {
      self.modeStatus.fixedTimeStatus.runTime = self.nativeService.transFormat(Math.floor(cmdModel.duration / 60) + ":" + Math.floor(cmdModel.duration % 60), 'hour:min');
      self.modeStatus.fixedTimeStatus.oldRunTime = self.nativeService.transFormat(Math.floor(cmdModel.duration / 60) + ":" + Math.floor(cmdModel.duration % 60), 'hour:min');
    }
    if (this.cd !== null && this.cd !== undefined &&
      !(this.cd as ViewRef_).destroyed) {
      this.cd.detectChanges();
    }
  }

