  initCommandModel(cmdAry) {
    let self = this;
    let resCount = 0;

    if (AppConfig.runInfo['isOnline']) {
      let protocolList: any = [];
      let protocolOnLineList: any = [];
      let curDeviceMac;
      let tempDevice = JSON.parse(localStorage.getItem("local_device_list"));

      for (let w = 0; w < tempDevice.length; w++) {
        if (tempDevice[w]["connected"] == true) {
          curDeviceMac = tempDevice[w]["address"];
          tempDevice = tempDevice[w];
          if (tempDevice.protocolList == undefined) {
          } else {
            protocolList = tempDevice.protocolList;
          }
          if (tempDevice.protocolOnLineList == undefined) {
          } else {
            protocolOnLineList = tempDevice.protocolOnLineList;
          }

          break;
        }
      }
      if (protocolList.length > 0) {
        //弹出提示是否更新 最后清空数据
        let msgcontent = this.translate.get("msg.schedule_update_available_for")["value"];
        let msgtitle = this.translate.get("msg.schedule_update")["value"];
        self.commandFactory.showConfirm(msgcontent, () => {
          for (let i = 0; i < cmdAry.length; i++) {

            self.commandFactory.readRemote(cmdAry[i],
              (success) => {
                resCount++;
                let res = success;
                for (let w = 0; w < protocolList.length; w++) {
                  if (res.protocolType == protocolList[w].protocolType) {
                    self.commandFactory.send("zone_mode_site", protocolList[w])
                      .then((success) => {
                        self.commandFactory.editCommand2(protocolList[w]);
                      });
                  } else {
                    self.commandFactory.editCommand2(res);
                  }
                }
                if (resCount == protocolList.length) {
                  self.cleantempDevice();
                  self.init();
                }
              }, null, self.connectedDevice);
          }
        }, () => {
          for (let i = 0; i < cmdAry.length; i++) {
            self.commandFactory.readRemote(cmdAry[i],
              (success) => {
                //AppConfig.consoleLog(success);
                resCount++;
                let res = success;
                self.commandFactory.editCommand2(res);
                if (resCount == cmdAry.length) {
                  self.cleantempDevice();
                }
              }, null, self.connectedDevice)
          }
        }, msgtitle);
      } else {
        for (let i = 0; i < cmdAry.length; i++) {
          if (JSON.stringify(protocolOnLineList).indexOf(ProtocolType[cmdAry[i]]) == -1) {
            self.commandFactory.readRemote(cmdAry[i],
              (success) => {
                //AppConfig.consoleLog(success);
                resCount++;
                let res = success;
                self.commandFactory.editCommand2(res);
                if (resCount == cmdAry.length) {
                  self.cleantempDevice();
                }
              }, null, self.connectedDevice)
          }
        }
      }
    }
  }

