  //根据天（星期）获取已选择的天数
  getWateringDayByWeek(selectWeek) {
    let self = this;
    let wateringDay = "";
    if (self.weekDays.length == selectWeek.length) {
      wateringDay = self.translate.get("common.everyDay")["value"];
      //self.styleMethod(true);

    } else {
      //初始化按天模式
      for (let j = selectWeek.length - 1; j >= 0; j--) {
        for (let i = 0; i < self.weekDays.length; i++) {
          if (j == 1 && selectWeek.length > 5) {
            return wateringDay = wateringDay + "...";
          }
          if (self.weekDays[i].val == selectWeek[j]) {
            wateringDay = wateringDay + " " + self.weekDays[i].day;
            break;
          }
        }
      }
      //self.styleMethod(false);
    }
    return wateringDay;
  }

  //解析天数
  resolveDays(days) {
    let self = this;
    //分解按天模式数字
    let selectWeek = [];
    if (self.findWeekDaysIsInclude(days)) {
      selectWeek.push(days);
    } else {
      let nearlyFloor = null;
      let goWhile = true;
      let countWhile = 0;
      let weekDayVal = days;
      while (goWhile) {
        if (self.findWeekDaysIsInclude(weekDayVal)) {
          goWhile = false;
          selectWeek.push(weekDayVal);
        } else {
          nearlyFloor = self.findWeekDaysNearlyFloor(weekDayVal);
          if (nearlyFloor) {
            selectWeek.push(nearlyFloor.val);
            weekDayVal = weekDayVal - nearlyFloor.val;
          } else {
            goWhile = false;
          }
        }
      }
    }
    return selectWeek;
  }

  //查询当前Val是否包含在weekDays
  findWeekDaysIsInclude(val) {
    let self = this;
    let include = false;
    self.weekDays.forEach((item) => {
      if (val == item.val)
        include = true;
    });
    return include;
  }

  //查找Weekdays中比当前值小的最大值
  findWeekDaysNearlyFloor(val) {
    let nearlyItem: any = null;
    let self = this;
    self.weekDays.forEach((item) => {
      if (item.val < val) {
        nearlyItem = item;
      }
    });
    return nearlyItem;
  }

