  formattemp(t: any = null) {
    let self = this;
    AppConfig.consoleLog(AppConfig.timeFormat);
    if (AppConfig.timeFormat == 12) {
      let temp = t.split(' ');
      if (temp.length > 1) {
        if (temp[1] == self.translate.get("common.am")["value"]) {
          if (temp[0].split(' ')[0].split(':')[0] == 12) {
            return "00:" + temp[0].split(':')[1];
          }
          return temp[0];
        } else if (temp[1] == self.translate.get("common.pm")["value"]) {
          if (temp[0].split(' ')[0].split(':')[0] == 12) {
            return "12:" + temp[0].split(':')[1];
          }
          let temp12 = parseInt(temp[0].split(' ')[0].split(':')[0]) + 12;
          return temp12 + ":" + temp[0].split(':')[1];
        }
      } else {
        return temp[0];
      }
    } else {
      return t;
    }
  }


  formatsoakTimetemp(t: any = null, t1: any = null) {
    let self = this;
    AppConfig.consoleLog(AppConfig.timeFormat);
    let temp = t.split(' ');
    let temp1 = t1.split(' ');
    if (AppConfig.timeFormat == 12) {
      if (temp.length > 1) {
        if (temp[1] == self.translate.get("common.am")["value"]) {
          let temphour = parseInt(temp[0].split(' ')[0].split(':')[0]) + t1.split(' ')[0];
          let tempmin = parseInt(temp[0].split(' ')[0].split(':')[1]) + t1.split(' ')[2];
          return temphour + ":" + tempmin + ":" + t1.split(' ')[4];
        } else if (temp[1] == self.translate.get("common.pm")["value"]) {
          let temphour = parseInt(temp[0].split(' ')[0].split(':')[0]) + 12;
          let tempmin = parseInt(temp[0].split(' ')[0].split(':')[1]);
          temphour += t1.split(' ')[0];
          tempmin += t1.split(' ')[2];
          return temphour + ":" + tempmin + ":" + t1.split(' ')[4];
        }
      } else {
        return temp[0];
      }
    } else {
      let temphour = parseInt(temp[0].split(' ')[0].split(':')[0]);
      let tempmin = parseInt(temp[0].split(' ')[0].split(':')[1]);
      temphour += t1.split(' ')[0];
      tempmin += t1.split(' ')[2];
      return temphour + ":" + tempmin + ":" + t1.split(' ')[4];
    }
  }

  verifyTimeRule(mode: any = null) {
    let self = this;
    let startTime1 = self.formattemp(self.modeStatus.fixedTimeStatus.startTime1);
    let startTime2 = self.formattemp(self.modeStatus.fixedTimeStatus.startTime2);
    let First_d2 = self.commandFactory.readlocalProtocol(ProtocolType.First_d2, self.connectedDevice)

    let runTime = Math.floor(First_d2.duration / 60) + ":" + Math.floor(First_d2.duration % 60)
    // = self.modeStatus.fixedTimeStatus.runTime;
    let endTime1 = self.formattemp(self.modeStatus.circleTimeStatus.endTime1);
    let endTime2 = self.formattemp(self.modeStatus.circleTimeStatus.endTime2);


    //计算开始时间1-结束时间2 合计多少分钟
    let timeSlot = self.commandFactory.formatruntemp(startTime1, startTime2);
    //计算总共运行分钟
    let runTimeAll = self.commandFactory.formatrunTimetemphourmin(runTime);

    //定时
    if (mode == 1) {
      if (new Date("2012-01-01 " + startTime2 + ":00") <= new Date("2012-01-01 " + startTime1 + ":00")
        && startTime1 != "-1:-1"
        && startTime2 != "-1:-1") {
        document.getElementsByName("TimerStartTime2")[0].setAttribute("class", "show-error-msg");
        self.commandFactory.showAlert(self.translate.get("msg.enter_the_earliest_start_time_S1")["value"]);
      } else {
        if (runTimeAll > timeSlot) {
          document.getElementsByName("TimerRunTime")[0].setAttribute("class", "show-error-msg");
          self.commandFactory.showAlert(self.translate.get("msg.run_time_conflict_please_adjust_R_S2")["value"]);
        } else {
          document.getElementsByName("TimerRunTime")[0].setAttribute("class", "item-normal");
        }
        document.getElementsByName("TimerStartTime2")[0].setAttribute("class", "item-normal");
      }

    }
    //循环
    else {
      startTime1 = self.commandFactory.formattemp(self.modeStatus.circleTimeStatus.startTime1);
      startTime2 = self.commandFactory.formattemp(self.modeStatus.circleTimeStatus.startTime2);
      let circleendTime1 = self.commandFactory.formattemp(self.modeStatus.circleTimeStatus.endTime1);
      let circleendTime2 = self.commandFactory.formattemp(self.modeStatus.circleTimeStatus.endTime2);

      let First_e6 = self.commandFactory.readlocalProtocol(ProtocolType.First_e6, self.connectedDevice)
      runTime = First_e6.hour + ":" + First_e6.minute + ":" + First_e6.second
      //runTime = self.modeStatus.circleTimeStatus.runTime;

      let First_e7 = self.commandFactory.readlocalProtocol(ProtocolType.First_e7, self.connectedDevice)
      let First_e7soakTime = First_e7.hour + ":" + First_e7.minute + ":" + First_e7.second;


      //计算开始时间1-结束时间2 合计多少分钟
      let timeSlot1 = self.commandFactory.formatruntemp(startTime1, circleendTime1);
      let timeSlot2 = self.commandFactory.formatruntemp(startTime2, circleendTime2);
      //计算总共运行分钟


      let runTimeAll = self.commandFactory.formatrunTimetemphourmin(runTime);
      let newRunTimeAll1 = self.commandFactory.formatsoakTimetemp(startTime1, runTime, circleendTime1);
      let newRunTimeAll2 = self.commandFactory.formatsoakTimetemp(startTime2, runTime, circleendTime2);
      let soakTime = self.commandFactory.formatsoakTimetempone(First_e7soakTime);

      if (new Date("2012-01-01 " + endTime1 + ":00") <= new Date("2012-01-01 " + startTime1 + ":00")
        && startTime1 != "-1:-1" && endTime1 != "-1:-1") {
        document.getElementsByName("CircleEndTime1")[0].setAttribute("class", "show-error-msg");
        self.commandFactory.showAlert(self.translate.get("msg.enther_the_earliest_start_time_S1_E1")["value"]);
        return;
      } else {
        if (runTimeAll > timeSlot1) {
          document.getElementsByName("CircleRunTime")[0].setAttribute("class", "show-error-msg");
          self.commandFactory.showAlert(self.translate.get("msg.run_time_conflict_please_adjust_R_S2")["value"]);
          return;
        } else {
          document.getElementsByName("CircleRunTime")[0].setAttribute("class", "item-normal");
        }
        document.getElementsByName("CircleEndTime1")[0].setAttribute("class", "item-normal");
      }

      if (((new Date("2012-01-01 " + startTime2 + ":00") <= new Date("2012-01-01 " + startTime1 + ":00") && startTime1 != "-1:-1")
        || (new Date("2012-01-01 " + startTime2 + ":00") <= new Date("2012-01-01 " + endTime1 + ":00") && endTime1 != "-1:-1"))
        && startTime2 != "-1:-1") {
        document.getElementsByName("CircleStartTime2")[0].setAttribute("class", "show-error-msg");
        return;
      } else {
        document.getElementsByName("CircleStartTime2")[0].setAttribute("class", "item-normal");
      }

      if (((new Date("2012-01-01 " + endTime2 + ":00") <= new Date("2012-01-01 " + startTime1 + ":00") && startTime1 != "-1:-1")
        || (new Date("2012-01-01 " + endTime2 + ":00") <= new Date("2012-01-01 " + endTime1 + ":00") && endTime1 != "-1:-1")
        || (new Date("2012-01-01 " + endTime2 + ":00") <= new Date("2012-01-01 " + startTime2 + ":00") && startTime2 != "-1:-1"))
        && endTime2 != "-1:-1") {
        document.getElementsByName("CircleEndTime2")[0].setAttribute("class", "show-error-msg");
        self.commandFactory.showAlert(self.translate.get("msg.enther_the_earliest_start_time_S1_E1")["value"]);
        return;
      } else {
        if (runTimeAll > timeSlot2) {
          document.getElementsByName("CircleRunTime")[0].setAttribute("class", "show-error-msg");
          self.commandFactory.showAlert(self.translate.get("msg.run_time_conflict_please_adjust_R_S2_E2")["value"]);
          return;
        } else {
          document.getElementsByName("CircleRunTime")[0].setAttribute("class", "item-normal");
        }
        document.getElementsByName("CircleEndTime2")[0].setAttribute("class", "item-normal");
      }
      if ((soakTime > newRunTimeAll1) || (soakTime > newRunTimeAll2)) {
        document.getElementsByName("CircleSoakTime")[0].setAttribute("class", "show-error-msg");
        return;
      } else {
        document.getElementsByName("CircleSoakTime")[0].setAttribute("class", "item-normal");
      }
    }

    self.nativeService.detectChanges(self.cd);

  }

