String.prototype["parse2SOne"] = function () {
  let val = this;
  if (!val) return val;
  if (0 <= parseInt(val) && parseInt(val) < 10) return "0" + val.toString().trim();
  return val.toString().trim();
};
Number.prototype["parse2SOne"] = function () {
  let val = this;
  if (0 <= val && val < 10) return "0" + val.toString();
  return val.toString();
};



