import { AppConfig } from './../../../app/appconfig';
import { NavController } from 'ionic-angular';
import { HttpHelper } from './../../../util/HttpHelper';
import { Component, OnInit } from '@angular/core';
import {Helper} from "../../../util/Helper";
import {DatePicker} from 'ionic-native';
import { NativeService } from './../../../util/NativeService';
import { ChangeDetectorRef } from '@angular/core';
import {CommandFactory} from "../../../util/CommandFactory";
@Component({
  selector: 'selector-WateringDayPage',
  templateUrl: 'wateringDay.html'
})

export class WateringDayPage {
  weekDays=[
    {day:null,checked:false},//星期一
    {day:null,checked:false},//星期二
    {day:null,checked:false},//星期三
    {day:null,checked:false},//星期四
    {day:null,checked:false},//星期五
    {day:null,checked:false},//星期六
    {day:null,checked:false}//星期日
  ];
  constructor( private nativeService: NativeService,private httpHelper: HttpHelper, public navCtrl: NavController,public cd: ChangeDetectorRef,private  commandFactory:CommandFactory) {
  }
  ionViewWillEnter(){
    this.weekDays=this.commandFactory.getWeekDays();
  }
  selectedChecked(item) {
    if (item.checked)
      item.checked = false;
    else
      item.checked = true;
  }

  saveData() {
    this.navCtrl.pop();
  }

  goBack() {
    this.navCtrl.pop();
  }
}



