  //region 信号监控

  //信号量默认值
  _signalValue: number = -60;

  /**
   * 启动监控信号强度变化
   */
  startMonitorDeviceSignal() {
    let self = this;
    let timer = window.setInterval(
      function () {
        //清除定时器
        window.clearInterval(timer);
        //启动更新
        self.updateDeviceSignal();
      },
      500
    );
  }


  /**
   * 更新信号量
   */
  updateDeviceSignal() {
    let self = this;

    //画信号量
    self.commandFactory.signalCanvas(self._signalValue, "settinglId");

    //清除定时器
    self.stopMonitorDeviceSignal()

    //创建定时器
    AppConfig.runInfo['timer']['monitor.device.rssi'] = window.setInterval(
      () => {
        self.commandFactory.getCurDeviceRssi()
          .then((success) => {
              self._signalValue = parseInt(success.toString());
              //递归更新信号量
              self.updateDeviceSignal();
            },
            (error) => {
              AppConfig.consoleLog(error);
              //递归更新信号量
              self.updateDeviceSignal();
            });
      },
      2000);
  }

  /**
   * 停止信号强度变化
   */
  stopMonitorDeviceSignal() {
    let self = this;
    if (AppConfig.runInfo['timer']['monitor.device.rssi']) {
      window.clearInterval(AppConfig.runInfo['timer']['monitor.device.rssi']);
      AppConfig.runInfo['timer']['monitor.device.rssi'] = null;
    }
  }

