  //获取月份
  getMonth(val) {
    let self = this;
    let monthS = null;
    switch (val) {
      case "1":
        monthS = self.translate.get("monthShort.january")["value"];
        break;
      case "2":
        monthS = self.translate.get("monthShort.february")["value"];
        break;
      case "3":
        monthS = self.translate.get("monthShort.march")["value"];
        break;
      case "4":
        monthS = self.translate.get("monthShort.april")["value"];
        break;
      case "5":
        monthS = self.translate.get("monthShort.may")["value"];
        break;
      case "6":
        monthS = self.translate.get("monthShort.june")["value"];
        break;
      case "7":
        monthS = self.translate.get("monthShort.july")["value"];
        break;
      case "8":
        monthS = self.translate.get("monthShort.august")["value"];
        break;
      case "9":
        monthS = self.translate.get("monthShort.september")["value"];
        break;
      case "10":
        monthS = self.translate.get("monthShort.october")["value"];
        break;
      case "11":
        monthS = self.translate.get("monthShort.november")["value"];
        break;
      case "12":
        monthS = self.translate.get("monthShort.december")["value"];
        break;
    }

    return monthS;
  }

