import {NavController, NavParams} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {ChangeDetectorRef, Component} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";


declare var $: any;

@Component({
  selector: 'selector-settingStationTime',
  templateUrl: 'settingStationTime.html'
})

export class SettingStationTimePage {
  pandaLoading: any = null;
  public tempData: any = {
    zone: 1,
    zoneName: 'Zone 1'
  }
  curData: any = null;
  connectedDevice: any = null;

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController, public cd: ChangeDetectorRef,
              private  navParams: NavParams, private  commandFactory: CommandFactory, private translate: TranslateService) {

  }

  ionViewWillEnter() {
    let self = this;
    self.tempData.zone = self.navParams.get("zone");
    self.tempData.zoneName = "Zone " + self.tempData.zone;

    if (AppConfig.runInfo["isOnline"] == 0) {
      self.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      self.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }

  }


  getValue() {
    //返回的为数组
    return $('#pageColpicker').coolpicker('getValue');
  }

  ionViewDidEnter() {
    let self = this;
    self.tempData.zone = self.navParams.get("zone");
    let pickerAry = [];

    AppConfig.consoleLog(pickerAry);
    let hourWord = self.translate.get("common.hour")["value"];
    let minutesWrods = self.translate.get("common.min")["value"];
    let second = self.translate.get("common.sec")["value"];

    if (self.tempData.zone == 1) {
      let res_read =  self.commandFactory.readlocalProtocol(ProtocolType.Second_86, self.connectedDevice);
      // self.commandFactory.readRemote1(ProtocolType.Second_86,
      //   (success_read) => {
      //     AppConfig.consoleLog(success_read);
      //     let res_read = success_read;
          if (res_read.zemHour == "1") {
            pickerAry = [];
            let colAry = [];
            for (let i = 0; i <= 1; i++) {
              colAry.push(i.toString());
            }
            pickerAry.push(colAry);
            colAry = [];
            colAry.push("00");
            pickerAry.push(colAry);
            colAry = [];
            colAry.push("00");
            pickerAry.push(colAry);
          }
          else {
            pickerAry = [];
            let colAry = [];
            for (let i = 0; i <= 1; i++) {
              colAry.push(i.toString());
            }
            pickerAry.push(colAry);
            colAry = [];
            for (let i = 0; i <= 59; i++) {
              if (i <= 9) colAry.push("0" + i.toString());
              else colAry.push(i.toString());
            }
            pickerAry.push(colAry);
            colAry = [];
            for (let i = 0; i <= 59; i++) {
              if (i <= 9) colAry.push("0" + i.toString());
              else colAry.push(i.toString());
            }
            pickerAry.push(colAry);
          }


          //设置选择值
          $('#pageColpicker').coolpicker({
            columnSpace: 0,
            onRollCompleted: function (columnIndex, value) {
              AppConfig.consoleLog('column:' + columnIndex + ',value:' + value);
              let timeS = self.getValue();
              if (timeS[0] == "1") {

                pickerAry = [];
                let colAry = [];
                for (let i = 0; i <= 1; i++) {
                  colAry.push(i.toString());
                }
                pickerAry.push(colAry);
                colAry = [];
                colAry.push("00");
                pickerAry.push(colAry);
                colAry = [];
                colAry.push("00");
                pickerAry.push(colAry);

                timeS[2] = "00";
                timeS[4] = "00";
              }
              else {
                pickerAry = [];
                let colAry = [];
                for (let i = 0; i <= 1; i++) {
                  colAry.push(i.toString());
                }
                pickerAry.push(colAry);
                colAry = [];
                for (let i = 0; i <= 59; i++) {
                  if (i <= 9) colAry.push("0" + i.toString());
                  else colAry.push(i.toString());
                }
                pickerAry.push(colAry);
                colAry = [];
                for (let i = 0; i <= 59; i++) {
                  if (i <= 9) colAry.push("0" + i.toString());
                  else colAry.push(i.toString());
                }
                pickerAry.push(colAry);
              }
              $('#pageColpicker').coolpicker(
                'loadData',
                [
                  pickerAry[0],
                  [hourWord],
                  pickerAry[1],
                  [minutesWrods],
                  pickerAry[2],
                  [second]
                ]
              )
              $('#pageColpicker').coolpicker('setValue', [timeS[0], hourWord, timeS[2], minutesWrods, timeS[4], second]);
            }
          }).coolpicker(
            'loadData',
            [
              pickerAry[0],
              [hourWord],
              pickerAry[1],
              [minutesWrods],
              pickerAry[2],
              [second]
            ]
          );
          $('#pageColpicker').coolpicker('setValue', [res_read.zemHour, hourWord, res_read.zemMinute, minutesWrods, res_read.zemSecond, second]);
        //},null,self.connectedDevice);

    }
    else {
      let res_read =  self.commandFactory.readlocalProtocol(ProtocolType.Second_8b, self.connectedDevice);

      // self.commandFactory.readRemote1(ProtocolType.Second_8b,
      //   (success_read) => {
      //     AppConfig.consoleLog(success_read);
      //     let res_read = success_read;
          if (res_read.zemHour == "1") {

            pickerAry = [];
            let colAry = [];
            for (let i = 0; i <= 1; i++) {
              colAry.push(i.toString());
            }
            pickerAry.push(colAry);
            colAry = [];
            colAry.push("00");
            pickerAry.push(colAry);
            colAry = [];
            colAry.push("00");
            pickerAry.push(colAry);
          }
          else {
            pickerAry = [];
            let colAry = [];
            for (let i = 0; i <= 1; i++) {
              colAry.push(i.toString());
            }
            pickerAry.push(colAry);
            colAry = [];
            for (let i = 0; i <= 59; i++) {
              if (i <= 9) colAry.push("0" + i.toString());
              else colAry.push(i.toString());
            }
            pickerAry.push(colAry);
            colAry = [];
            for (let i = 0; i <= 59; i++) {
              if (i <= 9) colAry.push("0" + i.toString());
              else colAry.push(i.toString());
            }
            pickerAry.push(colAry);
          }
          $('#pageColpicker').coolpicker({
            columnSpace: 0,
            onRollCompleted: function (columnIndex, value) {
              AppConfig.consoleLog('column:' + columnIndex + ',value:' + value);
              let timeS = self.getValue();
              if (timeS[0] == "1") {
                pickerAry = [];
                let colAry = [];
                for (let i = 0; i <= 1; i++) {
                  colAry.push(i.toString());
                }
                pickerAry.push(colAry);
                colAry = [];
                colAry.push("00");
                pickerAry.push(colAry);
                colAry = [];
                colAry.push("00");
                pickerAry.push(colAry);

                timeS[2] = "00";
                timeS[4] = "00";
              }else {
                pickerAry = [];
                let colAry = [];
                for (let i = 0; i <= 1; i++) {
                  colAry.push(i.toString());
                }
                pickerAry.push(colAry);
                colAry = [];
                for (let i = 0; i <= 59; i++) {
                  if (i <= 9) colAry.push("0" + i.toString());
                  else colAry.push(i.toString());
                }
                pickerAry.push(colAry);
                colAry = [];
                for (let i = 0; i <= 59; i++) {
                  if (i <= 9) colAry.push("0" + i.toString());
                  else colAry.push(i.toString());
                }
                pickerAry.push(colAry);
              }
              $('#pageColpicker').coolpicker(
                'loadData',
                [
                  pickerAry[0],
                  [hourWord],
                  pickerAry[1],
                  [minutesWrods],
                  pickerAry[2],
                  [second]
                ]
              )
              $('#pageColpicker').coolpicker('setValue', [timeS[0], hourWord, timeS[2], minutesWrods, timeS[4], second]);
            }
          }).coolpicker(
            'loadData',
            [
              pickerAry[0],
              [hourWord],
              pickerAry[1],
              [minutesWrods],
              pickerAry[2],
              [second]
            ]
          );
          //设置选择值
          $('#pageColpicker').coolpicker('setValue', [res_read.zemHour, hourWord, res_read.zemMinute, minutesWrods, res_read.zemSecond, second]);
       // },null,self.connectedDevice);

    }
  }

  saveData() {
    let self = this;
    self.showPandaLoading();
    let timeS = self.getValue();
    AppConfig.consoleLog(timeS);

    //此处添加秒 以前没写。
    let cmdModel: any = null;
    if (self.tempData.zone == 1) {
      cmdModel = self.commandFactory.getCommand(ProtocolType.Second_86);
      cmdModel.zemHour = parseInt(timeS[0]);
      cmdModel.zemMinute = parseInt(timeS[2]);
      cmdModel.zemSecond = parseInt(timeS[4])
    } else {
      cmdModel = self.commandFactory.getCommand(ProtocolType.Second_8b);
      cmdModel.zemHour = parseInt(timeS[0]);
      cmdModel.zemMinute = parseInt(timeS[2]);
      cmdModel.zemSecond = parseInt(timeS[4])
    }
    cmdModel.wIndex = 8;

    if (self.tempData.zone == 1) {
      self.commandFactory.editCommand2(cmdModel);
    } else {
      self.commandFactory.editCommand2(cmdModel);
    }
    self.commandFactory.send_2("settingStation", cmdModel)
      .then((success) => {
        AppConfig.consoleLog(success);
        self.hidePandaLoading();
        self.goBack()

      }, (error) => {
        AppConfig.consoleLog(error);
        self.hidePandaLoading();
      });
  }

  //二次封装loading
  showPandaLoading() {
    let self = this;
    self.commandFactory.showLoadingAsync((resLoading) => {
      self.pandaLoading = resLoading;
      self.pandaLoading.present();
    });
  }

  //二次封装loading
  hidePandaLoading() {
    let self = this;
    self.commandFactory.hideLoadingAsync(self.pandaLoading);
  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }

}



