  /**
   * 初始化浇灌时间表
   * @param item
   */
  initIrrigationTime(item) {
    let self = this;
    if (!item) {
      //未传dom对象，则用户事件触发的源来设置
      item = window.event.target;
    }

    if (this.thisVersion > 3) {
      //region 主页 对接机器获取阀口名称
      if (AppConfig.isDockingMachine) {
        if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone1Name")) {
          this.zone1NameTxt = localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone1Name");
        } else {
          this.zone1NameTxt = "Zone 1";
        }
        if (localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone2Name")) {
          this.zone2NameTxt = localStorage.getItem(self.connectedDevice["address"].replace(/:/g, '') + "Second_90_zone2Name");
        } else {
          this.zone2NameTxt = "Zone 2";
        }
      }
    }

    this.byWeek = $(item).attr('mode') == "byweek";
    if (this.byWeek) {
      //按周
      $('#plWeekContainer').show();
      $('#plMonthContainer').hide();
      $('#spnSchedule .select-zone').hide();
      $('.zone-text').hide();

      //生成周报表
      this.generateWeekReport(new Date(), null);

    } else {
      //按月份
      $('#plWeekContainer').hide();
      $('#plMonthContainer').show();
      $('#spnSchedule .select-zone').show();
      $('.zone-text').show();

      //设置当前出口为出口1
      this.doSelectZone(null)
    }
    $('div.toolbar>.item').removeClass('select');
    $(item).addClass('select');

    //滚动调整菜单位置
    $('#tow_schedule>.scroll-content').on(
      'touchstart',
      function (evt) {
        $('#tow_schedule>.scroll-content').attr('offsetY', $(this).scrollTop());

        ['div.select-month-menu-bymonth', 'div.select-month-menu-byweek', 'div.select-zone-menu'].forEach(
          function (selectitem) {
            var $select = $(selectitem);
            if ($select.css('display') != 'none') {
              try {
                var pos = $select.offset();
                $select.attr('oldX', pos.left).attr('oldY', pos.top);
              } catch (e) {

              }
            }
          }
        );
      }
    ).on(
      'touchmove',
      function (evt) {
        var distance = $('#tow_schedule>.scroll-content').scrollTop() - parseFloat($('#tow_schedule>.scroll-content').attr('offsetY'));

        ['div.select-month-menu-bymonth', 'div.select-month-menu-byweek', 'div.select-zone-menu'].forEach(
          function (selectitem) {
            var $select = $(selectitem);
            if ($select.css('display') != 'none') {
              try {
                $select.offset({
                  left: parseFloat($select.attr('oldX')),
                  top: parseFloat($select.attr('oldY')) - distance
                });
              } catch (e) {

              }
            }
          }
        );
      }
    ).on(
      'touchend',
      function (evt) {
        var distance = $('#tow_schedule>.scroll-content').scrollTop() - parseFloat($('#tow_schedule>.scroll-content').attr('offsetY'));

        ['div.select-month-menu-bymonth', 'div.select-month-menu-byweek', 'div.select-zone-menu'].forEach(
          function (selectitem) {
            var $select = $(selectitem);
            if ($select.css('display') != 'none') {
              try {
                $select.offset({
                  left: parseFloat($select.attr('oldX')),
                  top: parseFloat($select.attr('oldY')) - distance
                });
              } catch (e) {

              }
            }
          }
        );
      }
    );
  }

