  /**
   * 获取浇水历史记录(按周)
   * @param startDate 起始日期
   * @param endDate 终止日期
   */
  requstHistoryByWeek(startDate, endDate) {
    var me = this;
    var strStartDate = startDate.getFullYear() + "-" + me.nativeService.padStart2((startDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(startDate.getDate().toString(), 2, '0');
    var strEndDate = endDate.getFullYear() + "-" + me.nativeService.padStart2((endDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(endDate.getDate().toString(), 2, '0');
    this.onRequstHistory(null, strStartDate, strEndDate, this.onRequstHistoryByWeekComplete);
  }

  /**
   * 获取浇水历史记录(按月)
   * @param startDate 起始日期
   * @param endDate 终止日期
   */
  requstHistoryByMonth(startDate, endDate) {
    var me = this;
    var strStartDate = startDate.getFullYear() + "-" + me.nativeService.padStart2((startDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(startDate.getDate().toString(), 2, '0');
    var strEndDate = endDate.getFullYear() + "-" + me.nativeService.padStart2((endDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(endDate.getDate().toString(), 2, '0');
    this.onRequstHistory(this.currentZone, strStartDate, strEndDate, this.onRequstHistoryByMonthComplete);
  }

  /**
   * 获取浇水调度表（按周）
   * @param startDate 起始日期
   * @param endDate 终止日期
   */
  requestScheduleByWeek(startDate, endDate) {
    var me = this;
    let Second_83 = me.commandFactory.readlocalProtocol(ProtocolType.Second_83, me.connectedDevice);
    AppConfig.zone1interval = false;
    AppConfig.zone2interval = false;
    AppConfig.zone1Loop = false;
    AppConfig.zone2Loop = false;
    // AppConfig.NextInterval = false;
    // AppConfig.NextLoop = false;
    if (Second_83) {
      if (Second_83["suspendWatering"] > 0) {
        startDate = me.utilityService.addDate(new Date(), Second_83["suspendWatering"]);
      }
      var strStartDate = startDate.getFullYear() + "-" + me.nativeService.padStart2((startDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(startDate.getDate().toString(), 2, '0');
      var strEndDate = endDate.getFullYear() + "-" + me.nativeService.padStart2((endDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(endDate.getDate().toString(), 2, '0');

      this.onRequestSchedule(null, strStartDate, strEndDate, this.onRequestScheduleByWeekComplete);
    } else {
      startDate = new Date(startDate.setDate(startDate.getDate()));
      var strStartDate = startDate.getFullYear() + "-" + me.nativeService.padStart2((startDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(startDate.getDate().toString(), 2, '0');
      var strEndDate = endDate.getFullYear() + "-" + me.nativeService.padStart2((endDate.getMonth() + 1).toString(), 2, '0') + "-" + me.nativeService.padStart2(endDate.getDate().toString(), 2, '0');

      this.onRequestSchedule(null, strStartDate, strEndDate, this.onRequestScheduleByWeekComplete);
    }
  }

