import {NavController, IonicModule} from 'ionic-angular';
import {HttpHelper} from '../../../util/HttpHelper';
import {Component, OnInit, ChangeDetectorRef} from '@angular/core';
import {NativeService} from '../../../util/NativeService';
import {AppConfig} from "../../../app/appconfig";

@Component({
  selector: 'selector-appAbout',
  templateUrl: 'appAbout.html'
})

export class AppAboutPage {
  public showMore: boolean = false;
  public entpList: any = [];
  PageSize = 10;
  PageIndex = 1;
  eiPageCount = 0;
  dataLs: any;

  version: any = " " + AppConfig.apkVersion;
  public currentUserInfo: any = {};

  constructor(private nativeService: NativeService, private httpHelper: HttpHelper, public navCtrl: NavController, public cd: ChangeDetectorRef) {

  }

  ionViewWillEnter() {
    //this.serach();
  }

  ionViewDidEnter() {
    //this.navParams.get("")
    //初始化数据
    let self = this;
    if (localStorage.getItem("local_waring_msg")) {
      self.dataLs = localStorage.getItem("local_waring_msg");
    }
  }

  goBack() {
    this.navCtrl.pop();
  }

}



