  /**
   * 查找上一条与下一条历史记录
   * @param history 历史数据记录集
   * @param theFilterDate 指定进间 为yyyy-mm-dd 或 yyyy-mm-dd HH:MM:ss格式
   */
  findClosestHistory(history, theFilterDate) {
    var r = {
      "prev": null,
      "next": null
    };
    try {
      if (history) {
        var filterDate = new Date(theFilterDate);

        var prev = null;
        var next = null;
        history.forEach(
          function (data) {
            var tmpDate = new Date(data.createTime);
            if (tmpDate <= filterDate)
              prev = data;
            if (tmpDate > filterDate && !next)
              next = data;
          }
        );

        r.prev = prev;
        r.next = next;
      }
    } catch (e) {

    }

    return r;
  }

  /**
   * 查找上一条与下一条调度计划(定时器模式)
   * @param theProduct 指定产品  bbt1/bbt2
   * @param theZone    指定站点  zone1/zone2
   * @param theStartDate 起始日期  yyyy-mm-dd
   * @param theEndDate 结束日期 yyyy-mm-dd
   * @param theParams 参数 按指定的参数进行设置，如day,interval,odevity,只设置一种，其它不传或置空
   * @param theFilterDate 指定进间 为yyyy-mm-dd 或 yyyy-mm-dd HH:MM:ss格式
   */
  findClosestTimerScheduler(theProduct, theZone, theStartDate, theEndDate, theParams, theFilterDate) {
    var r = {
      "prev": null,
      "next": null
    };
    try {
      var filterDate = new Date(theFilterDate);

      var schedulers = this.generateTimerScheduler(theProduct, theZone, theStartDate, theEndDate, theParams);
      var prev = null;
      var next = null;
      schedulers.forEach(
        function (scheduler) {
          var tmpDate = new Date(scheduler.triggerTime);
          if (tmpDate <= filterDate)
            prev = scheduler;
          if (tmpDate > filterDate && !next)
            next = scheduler;
        }
      );

      r.prev = prev;
      r.next = next;
    } catch (e) {

    }

    return r;
  }

