  /**
   *获取与蓝牙设备连接状态
   * @param success
   * @param error
   */
  getDeviceConnected(success, error) {
    let me = this;
    if (AppConfig.isDebug) {
      success({connected: true});
    } else {
      me.platform.ready()
        .then(
          () => {
            cordova.plugins.AisBlePlugin.getConnected(
              function (result) {
                if (typeof (success) == 'function')
                  success(result);
              },
              function (errMsg) {
                if (typeof (error) == 'function')
                  error(errMsg);
              }
            );
          }
        );
    }
  }

  /**
   *断开与蓝牙设备连接
   * @param success
   * @param error
   */
  disDeviceConnected() {
    if (AppConfig.isDebug) return;
    let me = this;
    me.platform.ready()
      .then(
        () => {
          cordova.plugins.AisBlePlugin.disconnect(
            function (success) {
              AppConfig.consoleLog(success);
            },
            function (error) {
              AppConfig.consoleLog(error)
            }
          );
        }
      );
  }

