import {NavController, IonicModule, AlertController} from 'ionic-angular';
import {Component, OnInit, ChangeDetectorRef} from '@angular/core';
import {NativeService} from "../../../util/NativeService";
import {CommandFactory, ProtocolType} from "../../../util/CommandFactory";
import {TranslateService} from "ng2-translate";
import {el} from "@angular/platform-browser/testing/src/browser_util";
import {SettingBttsPage} from "../settingBtts/settingBtts";
import {AppConfig} from "../../../app/appconfig";


@Component({
  selector: 'selector-seasonalAdjustment',
  templateUrl: 'settingSeasonalAdjustment.html'
})

export class SeasonalAdjustmentPage {
  global_enabled = false;
  monthly_enabled = false;
  saturation_global = 100;//整体调节值
  saturation_1 = 100;//一月调节值
  saturation_2 = 100;//二月调节值
  saturation_3 = 100;//三月调节值
  saturation_4 = 100;//四月调节值
  saturation_5 = 100;//五月调节值
  saturation_6 = 100;//六月调节值
  saturation_7 = 100;//七月调节值
  saturation_8 = 100;//八月调节值
  saturation_9 = 100;//九月调节值
  saturation_10 = 100;//十月调节值
  saturation_11 = 100;//十一月调节值
  saturation_12 = 100;//十二月调节值
  public MonthlyAdjustment: any = {
    Month_1: 100,//一月调节值
    Month_2: 100,//二月调节值
    Month_3: 100,//三月调节值
    Month_4: 100,//四月调节值
    Month_5: 100,//五月调节值
    Month_6: 100,//六月调节值
    Month_7: 100,//七月调节值
    Month_8: 100,//八月调节值
    Month_9: 100,//九月调节值
    Month_10: 100,//十月调节值
    Month_11: 100,//十一月调节值
    Month_12: 100//十二月调节值
  }
  connectedDevice: any = null;

  constructor(private nativeService: NativeService, public navCtrl: NavController, public cd: ChangeDetectorRef,
              private commandFactory: CommandFactory, private translate: TranslateService) {

  }

  goBack() {
    this.navCtrl.pop({animate: false});
  }


  //调节灌溉时长比例
  ionViewWillEnter() {
    let me = this;
    if (AppConfig.runInfo["isOnline"] == 0) {
      me.connectedDevice = AppConfig.runInfo["selectOfflineDevice"];
    } else {
      me.connectedDevice = AppConfig.runInfo["selectOnlineDevice"];
    }
    let loaclType = localStorage.getItem("homePageTypeId");
    me.nativeService.queryDeviceBasicData("*", "mac = '" + me.connectedDevice["address"] + "' and  typeId='" + loaclType + "' and isChecked = 1 and pageName='SeasonalAdjustmentPage' ", (r) => {
      AppConfig.consoleLog(r);
      if (r.result > 0) {
        if (r.rows.length > 0) {
          let Wateringplans = r;

          me.commandFactory.send_2("OverallAdjustment", Wateringplans.rows[0].jsonDate)
            .then((success) => {
              AppConfig.consoleLog(success);
            });
          //JSON.parse(Wateringplans.rows[0].jsonDate)
          localStorage.setItem("Second_9C", Wateringplans.rows[0].jsonDate);
          let Second_9C: any = null;
          Second_9C = JSON.parse(Wateringplans.rows[0].jsonDate);
          if (Second_9C.isGlobal == false) {
            me.monthly_enabled = true;

            for (var i = 0; i < 12; i++) {
              if (Second_9C.config[i] < 0) {
                Second_9C.config[i] = Second_9C.config[i] + 256;
              }
            }
            me.saturation_1 = Second_9C.config[0];
            me.saturation_2 = Second_9C.config[1];
            me.saturation_3 = Second_9C.config[2];
            me.saturation_4 = Second_9C.config[3];
            me.saturation_5 = Second_9C.config[4];
            me.saturation_6 = Second_9C.config[5];
            me.saturation_7 = Second_9C.config[6];
            me.saturation_8 = Second_9C.config[7];
            me.saturation_9 = Second_9C.config[8];
            me.saturation_10 = Second_9C.config[9];
            me.saturation_11 = Second_9C.config[10];
            me.saturation_12 = Second_9C.config[11];
          } else {
            me.global_enabled = true;
            if (Second_9C.config[0] < 0) {
              Second_9C.config[0] = Second_9C.config[0] + 256;
            }
            me.saturation_global = Second_9C.config[0];
          }

        } else {
          let Second_9C = me.commandFactory.readlocalProtocol(ProtocolType.Second_9C, me.connectedDevice);

          // me.commandFactory.read(ProtocolType.Second_9C, me.connectedDevice).then((r1) => {
          //   AppConfig.consoleLog(r1);
          //   let Second_9C: any = r1;
             let jsonSecond_9C = JSON.stringify(Second_9C)

            let updateTime: string = me.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
            me.nativeService.insertDeviceBasicData("SeasonalAdjustmentPage", jsonSecond_9C, loaclType, 1, updateTime, (r2) => {
              AppConfig.consoleLog(r2);
            })

            if (Second_9C.isGlobal == false) {
              me.monthly_enabled = true;

              for (var i = 0; i < 12; i++) {
                if (Second_9C.config[i] < 0) {
                  Second_9C.config[i] = Second_9C.config[i] + 256;
                }
              }
              me.saturation_1 = Second_9C.config[0];
              me.saturation_2 = Second_9C.config[1];
              me.saturation_3 = Second_9C.config[2];
              me.saturation_4 = Second_9C.config[3];
              me.saturation_5 = Second_9C.config[4];
              me.saturation_6 = Second_9C.config[5];
              me.saturation_7 = Second_9C.config[6];
              me.saturation_8 = Second_9C.config[7];
              me.saturation_9 = Second_9C.config[8];
              me.saturation_10 = Second_9C.config[9];
              me.saturation_11 = Second_9C.config[10];
              me.saturation_12 = Second_9C.config[11];
            } else {
              me.global_enabled = true;
              if (Second_9C.config[0] < 0) {
                Second_9C.config[0] = Second_9C.config[0] + 256;
              }
              me.saturation_global = Second_9C.config[0];
            }
          // })
        }
      }
    })
  }

  clickSwitchGlobal(evl) {
    let self = this;
    if (evl.checked) {
      self.monthly_enabled = false;
    }
  }

  clickSwitchMonthly(evl) {
    let self = this;
    if (evl.checked) {
      self.global_enabled = false;
    }
  }

  //整体调整或月份调整
  clickAdjustment() {
    let me = this;
    let loaclType = localStorage.getItem("homePageTypeId");
    let updateTime: string = me.commandFactory.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
    if (me.global_enabled) {
      var list = [];
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      list.push(me.saturation_global);
      let Second_9C = {"protocolType": "Second_9C", "isGlobal": true, "config": list};
      me.commandFactory.send_2("OverallAdjustment", Second_9C)
        .then((success) => {
          AppConfig.consoleLog(success);
        });
      let jsonSecond_9C = JSON.stringify(Second_9C)
      me.nativeService.insertDeviceBasicData("SeasonalAdjustmentPage", jsonSecond_9C, loaclType, 1, updateTime, (r2) => {
        AppConfig.consoleLog(r2);
      })
      // me.nativeService.updateDeviceBasicData(updateTime, "SeasonalAdjustmentPage", jsonSecond_9C, loaclType, 1, (r2) => {
      //   AppConfig.consoleLog(r2);
      // })

      localStorage.setItem("Second_9C", jsonSecond_9C);

    } else if (me.monthly_enabled) {
      var list = [];
      list.push(me.saturation_1);
      list.push(me.saturation_2);
      list.push(me.saturation_3);
      list.push(me.saturation_4);
      list.push(me.saturation_5);
      list.push(me.saturation_6);
      list.push(me.saturation_7);
      list.push(me.saturation_8);
      list.push(me.saturation_9);
      list.push(me.saturation_10);
      list.push(me.saturation_11);
      list.push(me.saturation_12);

      let Second_9C = {"protocolType": "Second_9C", "isGlobal": false, "config": list};
      me.commandFactory.send_2("OverallAdjustment", Second_9C)
        .then((success) => {
          AppConfig.consoleLog(success);
        });
      let jsonSecond_9C = JSON.stringify(Second_9C)
      // me.nativeService.updateDeviceBasicData("SeasonalAdjustmentPage", jsonSecond_9C, loaclType, 1, updateTime, (r2) => {
      //   AppConfig.consoleLog(r2);
      // })
      me.nativeService.insertDeviceBasicData("SeasonalAdjustmentPage", jsonSecond_9C, loaclType, 1, updateTime, (r2) => {
        AppConfig.consoleLog(r2);
      })
      localStorage.setItem("Second_9C", jsonSecond_9C);
    }
    me.goBack();
  }

  //恢复初始值
  thisReset() {
    let self = this;
    if (self.global_enabled) {
      self.saturation_global = 100;
    } else if (self.monthly_enabled) {
      self.saturation_1 = 100;//一月调节值
      self.saturation_2 = 100;//二月调节值
      self.saturation_3 = 100;//三月调节值
      self.saturation_4 = 100;//四月调节值
      self.saturation_5 = 100;//五月调节值
      self.saturation_6 = 100;//六月调节值
      self.saturation_7 = 100;//七月调节值
      self.saturation_8 = 100;//八月调节值
      self.saturation_9 = 100;//九月调节值
      self.saturation_10 = 100;//十月调节值
      self.saturation_11 = 100;//十一月调节值
      self.saturation_12 = 100;//十二月调节值
    }
  }
}



