import {Injectable} from '@angular/core';
import {Platform, ToastController, AlertController} from 'ionic-angular';
import {AppVersion} from '@ionic-native/app-version';
import {File} from '@ionic-native/file';
import {Transfer, TransferObject} from '@ionic-native/transfer';
import {AppConfig} from "../app/appconfig"
import {HttpHelper} from "../util/HttpHelper"
import {InAppBrowser} from "@ionic-native/in-app-browser";
import {TranslateService} from "ng2-translate";

declare var cordova: any;

@Injectable()

/**
 * APP内部服务
 */
export class UpgradeService {

  /**
   * 构造
   * @param platform
   * @param alertCtrl
   * @param transfer
   * @param appVersion
   * @param file
   * @param inAppBrowser
   */
  constructor(
    private toastCtrl: ToastController,
    private platform: Platform,
    private alertCtrl: AlertController,
    private transfer: Transfer,
    private appVersion: AppVersion,
    private file: File,
    private inAppBrowser: InAppBrowser,
    private translate: TranslateService,
    private httpHelper: HttpHelper
  ) {

  }

  /**
   * 检查app是否需要升级
   */
  detectionUpgrade() {
    var me = this;
    //这里连接后台获取app最新版本号,然后与当前app版本号(this.getVersionNumber())对比
    me.getVersionNumber().then(
      (curVersion) => {
        me.httpHelper.post(
          AppConfig.GetInterFaceUrl() + 'Common/GetUpgradeInfo',
          {
            code: AppConfig.upgradeApkCode,
            version: curVersion,
            osName: '',
            osVersion: '',
            osArchitecture: '',
            deviceModel: ''
          }
        ).then(
          (data) => {
            var objResult = data.json();
            if (objResult.result > 0) {
              var isFinded = false;
              for (var i = 0; i < objResult.rows.length; i++) {
                var curPackage = objResult.rows[i];
                if (curPackage.needSplit) {
                  //暂不支持增量更新
                } else {
                  for (var j = 0; j < curPackage.files.length; j++) {
                    if (curPackage.fileName == curPackage.files[j].srcPath && curPackage.files[j].action == 'setup' && curPackage.fileUrl) {
                      //找到了对应的包
                      //版本号不一样就需要申请,不需要升级就return
                      let btnCancel = this.translate.get("btn.cancel")["value"];
                      let btnOk = this.translate.get("btn.ok")["value"];
                      me.alertCtrl.create({
                        title: this.translate.get("versionBtt.Updatetitle")["value"],
                        subTitle: this.translate.get("versionBtt.UpdatesubTitle")["value"],
                        buttons: [
                          {
                            text: btnCancel,
                            handler: () => {
                              //为强制的则退出系统
                              if (curPackage.isForce)
                                me.platform.exitApp();
                            }
                          },
                          {
                            text: btnOk,
                            handler: () => {
                              me.downloadApp(AppConfig.GetSiteApkUrl() + curPackage.fileUrl, curPackage.isForce);
                            }
                          }
                        ]
                      }).present();

                      isFinded = true;
                      break;
                    }
                  }
                }
                if (isFinded)
                  break;
              }
            }
          }
        )
      }
    );
  }

  /*
   * 安装app
   */
  installApp(apkDownloadUrl: string, content: string, title: string) {
    var me = this;
    me.alertCtrl.create({
      title: (title ? title : '应用安装'),
      subTitle: content,
      buttons: [
        {
          text: '浏览器下载',
          handler: () => {
            me.inAppBrowser.create(apkDownloadUrl, '_system');
          }
        },
        {
          text: '取消'
        },
        {
          text: '确定',
          handler: () => {
            me.downloadAndInstallApp(apkDownloadUrl);
          }
        }
      ]
    }).present();
  }

  /*
   * 下载安装app
   */
  downloadAndInstallApp(apkDownloadUrl: string) {
    var me = this;
    if (me.isAndroid()) {
      let alert = me.alertCtrl.create({
        title: '下载进度：0%',
        enableBackdropDismiss: false/*,
         buttons: ['后台下载']*/
      });
      alert.present();

      const fileTransfer: TransferObject = me.transfer.create();
      //apk保存的目录
      const apk = me.file.externalDataDirectory + 'tmp.apk';

      fileTransfer.download(apkDownloadUrl, apk).then(
        (entry) => {
          me.platform.ready().then(() => {
            cordova.plugins.InstallPlugin.install(
              apk.replace('file://', ''),
              (code) => {
                //成功
                let toast = me.toastCtrl.create({
                  message: '安装成功!',
                  duration: 3000,
                  position: 'middle',
                  showCloseButton: true,
                  closeButtonText: '关闭'
                });
                toast.present();
              },
              (code) => {
                //失败
                let toast = me.toastCtrl.create({
                  message: '安装失败!',
                  duration: 3000,
                  position: 'middle',
                  showCloseButton: true,
                  closeButtonText: '关闭'
                });
                toast.present();
              }
            )
          });
        },
        (error) => {
          alert.dismiss();

          //显示错误信息
          let toast = me.toastCtrl.create({
            message: '下载失败,错误码:' + error.code + ',异常信息:' + error.exception,
            duration: 3000,
            position: 'middle',
            showCloseButton: true,
            closeButtonText: '关闭'
          });
          toast.present();
        }
      );

      fileTransfer.onProgress((event: ProgressEvent) => {
        let num = Math.floor(event.loaded / event.total * 100);
        if (num === 100) {
          alert.dismiss();
        } else {
          let title = document.getElementsByClassName('alert-title')[0];
          title && (title.innerHTML = '下载进度：' + num + '%');
        }
      });
    } else if (me.isIos()) {
      let toast = me.toastCtrl.create({
        message: '不支持ios安装',
        duration: 3000,
        position: 'middle',
        showCloseButton: true,
        closeButtonText: '关闭'
      });
      toast.present();
    }
  }

  /**
   * 下载安装app
   */
  downloadApp(apkDownloadUrl: string, errExit: boolean) {
    var me = this;
    if (me.isAndroid()) {
      let alert = me.alertCtrl.create({
        title: this.translate.get("versionBtt.Update3")["value"] + ' 0%',
        enableBackdropDismiss: false/*,
        buttons: ['后台下载']*/
      });
      alert.present();

      const fileTransfer: TransferObject = me.transfer.create();
      //apk保存的目录
      const apk = me.file.externalDataDirectory + 'android.apk';
      let btnClose = this.translate.get("btn.close")["value"];
      let Updatesuccess = this.translate.get("versionBtt.Updatesuccess")["value"];
      let Updatefail = this.translate.get("versionBtt.Updatesuccess")["value"];
      fileTransfer.download(apkDownloadUrl, apk).then(
        (entry) => {
          me.platform.ready().then(() => {
            cordova.plugins.InstallPlugin.install(
              apk.replace('file://', ''),
              (code) => {
                //成功
                let toast = me.toastCtrl.create({
                  message: Updatesuccess,
                  duration: 3000,
                  position: 'middle',
                  showCloseButton: true,
                  closeButtonText: btnClose
                });
                toast.present();
              },
              (code) => {
                //失败
                let toast = me.toastCtrl.create({
                  message: Updatefail,
                  duration: 3000,
                  position: 'middle',
                  showCloseButton: true,
                  closeButtonText: btnClose
                });
                toast.onDidDismiss(() => {
                  //为强制的则退出系统
                  if (errExit)
                    me.platform.exitApp();
                });
                toast.present();
              }
            )
          });
        },
        (error) => {
          alert.dismiss();

          //显示错误信息
          let toast = me.toastCtrl.create({
            message: this.translate.get("versionBtt.Update1")["value"] + error.code + this.translate.get("versionBtt.Update2")["value"] + error.exception,
            duration: 3000,
            position: 'middle',
            showCloseButton: true,
            closeButtonText: btnClose
          });
          toast.onDidDismiss(() => {
            //为强制的则退出系统
            if (errExit)
              me.platform.exitApp();
          });
          toast.present();
        }
      );

      fileTransfer.onProgress((event: ProgressEvent) => {
        let num = Math.floor(event.loaded / event.total * 100);
        if (num === 100) {
          alert.dismiss();
        } else {
          let title = document.getElementsByClassName('alert-title')[0];
          title && (title.innerHTML = this.translate.get("versionBtt.Update3")["value"] + num + '%');
        }
      });
    } else if (me.isIos()) {
      me.openUrlByBrowser(AppConfig.apkDownloadUrl);
    }
  }

  /**
   * 通过浏览器打开url
   */
  openUrlByBrowser(url: string): void {
    this.inAppBrowser.create(url, '_system');
  }

  /**
   * 是否真机环境
   * @return {boolean}
   */
  isMobile(): boolean {
    return this.platform.is('mobile') && !this.platform.is('mobileweb');
  }

  /**
   * 是否android真机环境
   * @return {boolean}
   */
  isAndroid(): boolean {
    return this.isMobile() && this.platform.is('android');
  }

  /**
   * 是否ios真机环境
   * @return {boolean}
   */
  isIos(): boolean {
    return this.isMobile() && (this.platform.is('ios') || this.platform.is('ipad') || this.platform.is('iphone'));
  }

  /**
   * 获得app版本号,如0.01
   * @description  对应/config.xml中version的值
   * @returns {Promise<string>}
   */
  getVersionNumber(): Promise<string> {
    return new Promise((resolve) => {
      this.appVersion.getVersionNumber().then((value: string) => {
        resolve(value);
      }).catch(err => {
        AppConfig.consoleLog('getVersionNumber:' + err);
      });
    });
  }
}



