  /**
   *连接指定蓝牙设备
   */
  connect() {
    let me=this;
    if(!me.nameOrAddress) {
      me.nativeService.showToast('请输入蓝牙设备名或地址!');
      return;
    }
    me.platform.ready()
      .then(
        () => {
          cordova.plugins.AisBlePlugin.connect(
            me.nameOrAddress,
            function(info) {
              me.nativeService.showToast(info);
            },
            function(errMsg) {
              me.nativeService.showToast(errMsg);
            }
          );
        }
      );
  }

