  _timer:any;
  /**
   * 启用循环请求处理
   */
  loopRequest() {
    var me=this;
    if(!me._timer) {
      me._timer=window.setInterval(()=>{
        me.platform.ready()
          .then(
            () => {
              cordova.plugins.AisBlePlugin.read(
                "First_D2",
                function(info) {
                  AppConfig.consoleLog(info);
                },
                function(errMsg) {
                  AppConfig.consoleLog(errMsg);
                }
              );
            }
          );
      },1000);
    }
  }

