  /**
   * 根据属性查找设备
   * @param attr
   * @param val
   * @param filterMode  //过滤模式 0： 找离线 1：找在线 2：找全部 3：按当前全局的状态找设备（AppConfig.runInfo['isOnline']）
   */
  findDeviceByAttr = (attr: string = null, val: any, filterMode: number = 3) => {
    if (AppConfig.isDebug) {
      if (val == "B4:34:F1:81:08:1A") return this.deviceMode_First;
      return this.deviceModel;
    }

    try {
      //当前离线设备地址
      let tempDevices = JSON.parse(localStorage.getItem("local_device_list"));
      if (tempDevices instanceof Array) {
        for (let i = 0; i < tempDevices.length; i++) {
          switch (filterMode) {
            case 0:     //离线设备
            {
              if (!tempDevices[i]['connected'] && (!attr || (attr && tempDevices[i][attr] == val))) {
                tempDevices[i]["isOnline"] = false
                return tempDevices[i];
              }
            }
              break;
            case 1:     //在线设备
            {
              if (tempDevices[i]['connected'] && (!attr || (attr && tempDevices[i][attr] == val)))
                return tempDevices[i];
            }
              break;
            case 2:     //全部设备
            {
              if (attr && tempDevices[i][attr] == val)
                return tempDevices[i];
            }
              break;
            default:    //按当前全局的状态找设备（AppConfig.runInfo['isOnline']）
              if (AppConfig.runInfo['isOnline']) {
                if (tempDevices[i]['connected'] && (!attr || (attr && tempDevices[i][attr] == val)))
                  return tempDevices[i];
              } else {
                if (!tempDevices[i]['connected'] && (!attr || (attr && tempDevices[i][attr] == val)))
                  return tempDevices[i];
              }
              break;
          }
        }
      }
    } catch (e) {

    }

    return null;
  }

  findCurConnectDevice() {
    let curDevice = this.deviceMode_First;
    let tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
    for (let i = 0; i < tempDevice.length; i++) {
      if (tempDevice[i].connected) {
        curDevice = tempDevice[i];
        break;
      }
    }
    return curDevice;
  }

