  /**
   * 搜索所有设备
   */
  searchDevice = () => {
    let self = this;
    let tmpDeviceAry = [];
    let tmpStoreDevices = [];
    if (AppConfig.isDebug) {
      return new Promise((resolve, reject) => {
        localStorage.setItem("local_device_list", JSON.stringify([self.deviceModel, self.deviceMode_First]));
        resolve(JSON.parse(localStorage.getItem("local_device_list")));
      });
    } else {
      //解析当前设备列表
      try {
        tmpStoreDevices = JSON.parse(localStorage.getItem("local_device_list"));
      } catch (e) {
        tmpStoreDevices = [];
      }
      if (!(tmpStoreDevices instanceof Array))
        tmpStoreDevices = [];

      return new Promise(
        (resolve, reject) => {
          self.deviceBtt.remoteGetJsonDevices(
            (success) => {
              if (success && success.length >= 0) {
                let version = self.translate.get("more.appAbout.version")["value"] + AppConfig.version;
                let storeDeviceChanged = false;
                for (let j = 0; j < success.length; j++) {
                  //忽略第一代设备
                  if (success[j]["name"].toString().indexOf("Spray") >= 0) {
                    continue;
                  }

                  //缓存列表中是否存在
                  let isStoresFinded: boolean = false;
                  for (let c = 0; c < tmpStoreDevices.length; c++) {
                    if (tmpStoreDevices[c]["address"] == success[j]["address"]) {
                      // if (AppConfig.firstLogin == true) {
                      //   success[j]["connected"] = storeDevices[c]["connected"];
                      // }
                      //缓存设置中加载其它属性
                      for (let pn in tmpStoreDevices[c]) {
                        if (!success[j].hasOwnProperty(pn)) {
                          success[j][pn] = tmpStoreDevices[c][pn];
                        }
                      }
                      isStoresFinded = true;
                      break;
                    }
                  }
                  if (!isStoresFinded) {
                    //未在缓存中则设置默认其它字段
                    success[j]["firmware"] = version;
                    success[j]["nickName"] = '';
                    success[j]["password"] = '';

                    //设备发生变化，需要存储到本地缓存
                    storeDeviceChanged = true;

                    //缓存设备列表更新来源
                    tmpStoreDevices.push(success[j]);

                    //将设备数据保存到手机存储设备
                    let updateTime: string = self.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
                    self.nativeService.insertDeviceData(success[j]["name"], success[j]["nickName"], success[j]["address"], success[j]["type"], success[j]["password"], success[j]["firmware"], updateTime, (r) => {
                      AppConfig.consoleLog(r);
                    });
                  }

                  //有效入设备列表
                  tmpDeviceAry.push(success[j]);
                }

                if (storeDeviceChanged) {
                  //设备更新入本地缓存
                  localStorage.setItem("local_device_list", JSON.stringify(tmpStoreDevices));
                  self.storeDevices = tmpStoreDevices;
                }
              }
              resolve(tmpDeviceAry);
            },
            (error) => {
              reject(error);
            }
          )
        }
      );

    }
  }
