  //发送协议数据
  send_3(sessionId: any = null, cmd: any = null, successCall: any = null, errorCall: any = null) {
    let self = this;
    if (AppConfig.isDebug) {
      successCall("发送成功");
    } else {
      let thisVersion = localStorage.getItem("thisversion");
      let protocolModel = cmd;
      if (localStorage.getItem("thisversiontype"))
        self.thisVersionType = localStorage.getItem("thisversiontype");
      let isContainerProtocol = false;
      for (let i = 0; i < self.newVerSingle.length; i++) {
        if (protocolModel.protocolType == self.newVerSingle[i]) {
          isContainerProtocol = true;
          break;
        }
      }
      //判断是否为新版单口同时是否包含双口的协议
      if (self.thisVersionType == '1C' && isContainerProtocol && parseInt(thisVersion) > 3) {
        successCall("发送成功");
      } else {
        self.deviceBtt.remoteSendNore(sessionId, JSON.stringify(cmd), successCall, errorCall);
      }


    }

  }

