  /**
   * 更新日志
   */
  updateLog(zone: string = null) {
    let self = this;
    if (localStorage.getItem("btt2_" + zone + "_manual_log")) {
      let btt2_zone_manual_log = JSON.parse(localStorage.getItem("btt2_" + zone + "_manual_log"));
      let oldUpdateTime: string = btt2_zone_manual_log.updateTime;
      let updateTime: string = self.dateFormat(new Date(), "yyyy-MM-dd hh:mm:ss");
      AppConfig.consoleLog('updateTime：' + updateTime);

      let diffTime = self.getDateDiff(oldUpdateTime, updateTime);
      self.deviceBtt.remoteUpdateLog(zone, diffTime, updateTime, btt2_zone_manual_log.id);
    }

  }

