  //解析天数
  resolveDays(days) {
    let self = this;
    //分解按天模式数字
    let selectWeek = [];
    if (self.findWeekDaysIsInclude(days)) {
      selectWeek.push(days);
    } else {
      let nearlyFloor = null;
      let goWhile = true;
      let countWhile = 0;
      let weekDayVal = days;
      while (goWhile) {
        if (self.findWeekDaysIsInclude(weekDayVal)) {
          goWhile = false;
          selectWeek.push(weekDayVal);
        } else {
          nearlyFloor = self.findWeekDaysNearlyFloor(weekDayVal);
          if (nearlyFloor) {
            selectWeek.push(nearlyFloor.val);
            weekDayVal = weekDayVal - nearlyFloor.val;
          } else {
            goWhile = false;
          }
        }
      }
    }
    return selectWeek;
  }

  //查询当前Val是否包含在weekDays
  findWeekDaysIsInclude(val) {
    let self = this;
    let include = false;
    let weekDays = self.getWeekDays();
    weekDays.forEach((item) => {
      if (val == item.val)
        include = true;
    });
    return include;
  }

  //查找Weekdays中比当前值小的最大值
  findWeekDaysNearlyFloor(val) {
    let nearlyItem: any = null;
    let self = this;
    let weekDays = self.getWeekDays();
    weekDays.forEach((item) => {
      if (item.val < val) {
        nearlyItem = item;
      }
    });
    return nearlyItem;
  }

  //时间格式化输出
  dateFormat(date, fmt) {
    let o = {
      "M+": date.getMonth() + 1, //月份
      "d+": date.getDate(), //日
      "h+": date.getHours(), //小时
      "m+": date.getMinutes(), //分
      "s+": date.getSeconds(), //秒
      "q+": Math.floor((date.getMonth() + 3) / 3), //季度
      "S": date.getMilliseconds() //毫秒
    };
    if (/(y+)/.test(fmt)) fmt = fmt.replace(RegExp.$1, (date.getFullYear() + "").substr(4 - RegExp.$1.length));
    for (let k in o)
      if (new RegExp("(" + k + ")").test(fmt)) fmt = fmt.replace(RegExp.$1, (RegExp.$1.length == 1) ? (o[k]) : (("00" + o[k]).substr(("" + o[k]).length)));
    return fmt;
  };

