  /*
   * 获得时间差,时间格式为 年-月-日 小时:分钟:秒 或者 年/月/日 小时：分钟：秒
   * 其中，年月日为全格式，例如 ： 2010-10-12 01:00:00
   * 返回精度为：秒，分，小时，天
   */
  getTimePatch(num) {
    if (num) {
      if (typeof (num) == "number") {
        if (num < 0) return "00";
        else if (num >= 0 && num < 10) return "0" + num.toString();
        else if (num >= 10) return num.toString();
        else return "00".toString();
      } else if (typeof (num) == "string") {
        if (parseInt(num) < 0) return "00";
        else if (parseInt(num) >= 0 && parseInt(num) < 10) return "0" + num;
        else if (parseInt(num) >= 10) return num.toString();
        else return num;
      } else if (typeof (num) == "undefined") {
        return "00";
      } else return num;
    } else {
      return "00";
    }
  }

  getDateDiff(startTime, endTime, diffType: string = "second") {
    //将xxxx-xx-xx的时间格式，转换为 xxxx/xx/xx的格式
    startTime = startTime.replace(/\-/g, "/");
    endTime = endTime.replace(/\-/g, "/");

    //将计算间隔类性字符转换为小写
    diffType = diffType.toLowerCase();
    let sTime = new Date(startTime); //开始时间
    let eTime = new Date(endTime); //结束时间
    //作为除数的数字
    let divNum = 1;
    switch (diffType) {
      case"second":
        divNum = 1000;
        break;
      case"minute":
        divNum = 1000 * 60;
        break;
      case"hour":
        divNum = 1000 * 3600;
        break;
      case"day":
        divNum = 1000 * 3600 * 24;
        break;
      default:
        break;
    }
    let diffSecond = (eTime.getTime() - sTime.getTime()) / divNum;
    let second: any = null, seconds: any = "00", minute: any = null, minutes: any = "00", hour: any = null,
      hours: any = "00";
    second = Math.floor(diffSecond % 60);
    minute = Math.floor(diffSecond / 60);
    hour = Math.floor(minute / 60);
    minute = Math.floor(minute % 60);
    if (second < 10) seconds = "0" + second.toString();
    else seconds = second.toString();

    if (minute < 10) minutes = "0" + minute.toString();
    else minutes = minute.toString();

    if (hour < 10) hours = "0" + hour.toString();
    else hours = hour.toString();

    return hours + ":" + minutes + ":" + seconds;

  }

  getDateDiff_2(startTime, endTime) {
    let self = this;
    let startTime_s = self.dateFormat(new Date(startTime), "yyyy-MM-dd hh:mm:ss");
    let endTime_s = self.dateFormat(new Date(endTime), "yyyy-MM-dd hh:mm:ss");
    return self.getDateDiff(startTime_s, endTime_s);
  }

