  //绘制电量
  electricityCanvas(electricityNum: number = 0, electricityId: string = "electricityCanvas", electricitycolor) {
    let canvas: any = document.getElementById(electricityId);
    if (!canvas) return;
    var ctx = canvas.getContext("2d");
    var ctxh = 16;
    if (electricityNum == 100) {
      ctxh = 16;
    } else {
      ctxh = 16 / 100 * electricityNum;
    }
    ctx.beginPath();
    ctx.lineJoin = "round";
    ctx.lineWidth = 1;
    ctx.strokeStyle = electricitycolor;
    ctx.rect(0, 5, 11, 19);
    ctx.fillStyle = electricitycolor;
    ctx.fillRect(2, 6 + 16 - (16 / 100 * electricityNum), 7, ctxh);
    ctx.stroke();
    ctx.closePath();
//用closepath结束绘画，否则可能出现黏连；
    ctx.beginPath();
    ctx.lineWidth = 1;
    ctx.strokeStyle = electricitycolor;

    ctx.rect(3, 1, 5, 3);
    // ctx.fillStyle = "#FFFFFF";
    // ctx.fillRect(3, 1, 5, 3);
    ctx.stroke();
    ctx.closePath();
  }


