  formattemp(t: any = null) {
    if (t == undefined) return;
    let self = this;
    AppConfig.consoleLog(AppConfig.timeFormat);
    if (AppConfig.timeFormat == 12) {
      let temp = t.split(' ');
      if (temp.length > 1) {
        if (temp[1] == self.translate.get("common.am")["value"]) {
          if (parseInt(temp[0].split(' ')[0].split(':')[0]) == 12) {
            return "00" + ":" + temp[0].split(':')[1];
          }
          return temp[0];
        } else if (temp[1] == self.translate.get("common.pm")["value"]) {
          if (parseInt(temp[0].split(' ')[0].split(':')[0]) == 12) {
            return temp[0];
          }
          let temp12 = parseInt(temp[0].split(' ')[0].split(':')[0]) + 12;
          return temp12 + ":" + temp[0].split(':')[1];
        }
      } else {
        return temp[0];
      }
    } else {
      return t;
    }
  }


  UTC_monthLength(lpyr, mon) {
    var days = 31;

    if (mon == 1) // feb
    {
      days = (28 + lpyr);
    } else {
      if (mon > 6) // aug-dec
      {
        mon--;
      }

      if ((mon & 1) == 1) {
        days = 30;
      }
    }

    return days;
  }

//c++ utc时间转js日期
  UTC2Date(secTime) {
    var day = secTime % 86400;

    var seconds = day % 60;
    var minutes = Math.floor((day % 3600) / 60);
    var hour = Math.floor(day / 3600);


    var numDays = Math.floor(secTime / 86400);
    var monthLen;
    var year = 2000;

    while (numDays >= this.YearLength(year)) {
      numDays -= this.YearLength(year);
      year++;
    }

    // January.
    var month = 0;

    monthLen = this.UTC_monthLength(this.IsLeapYear(year), month);

    while (numDays >= monthLen) {
      numDays -= monthLen;
      month++;

      monthLen = this.UTC_monthLength(this.IsLeapYear(year), month);
    }

    day = numDays;

    return new Date(year, month, day + 1, hour, minutes, seconds);
    //AppConfig.consoleLog(year+'-'+(month+1)+'-'+(day+1)+' '+hour+':'+minutes+':'+seconds);
  }


