import { Pipe, PipeTransform } from '@angular/core';
import {TranslateService} from "ng2-translate";

/**
 * Generated class for the KeyAryft pipe.
 *
 * See https://angular.io/api/core/Pipe for more info on Angular Pipes.
 */
@Pipe({
  name: '$GrassNotsetft',
})
export class GrassNotsetft implements PipeTransform {
  constructor(private translate:TranslateService){}
  /**
   * Takes a value and makes it .
   */
  transform(value: any, ...args) {
    let notSet=true;
    let valAry=value.toString().split(":");
    if(!value||valAry.length<=0){
      return this.translate.get("common.notSet")["value"];
    }
    else{
      for (let i=0;i<valAry.length;i++){
        if(parseInt(valAry[i].toString())!=0&&parseInt(valAry[i].toString())!=-1){
          notSet=false;
          break;
        }
      }
    }
    if(notSet){
      return this.translate.get("common.notSet")["value"];
    }
    let self=this;
    if (args && typeof (args) == "object" && args.length > 0) {
      let newValAry = [];
      let separator="";
      let valAry = value.toString().trim().split(":");
      let ftAry = args[0].toString().trim().split(":");
      let eachLength = valAry.length > ftAry.length ? ftAry.length : valAry.length;
      for (let i = 0; i < eachLength; i++) {
        if (ftAry[i] == "hh"||ftAry[i]=="mm"||ftAry[i]=="ss") {
          newValAry.push(self.getPatch(valAry[i]));
          separator=":";
        }else if(ftAry[i]=="h"||ftAry[i]=="m"||ftAry[i]=="s"){
          newValAry.push(valAry[i]);
          separator=":";
        }else if(ftAry[i]==this.translate.get("common.hour")["value"]
          ||ftAry[i]==this.translate.get("common.minute")["value"]
          ||ftAry[i]==this.translate.get("common.second")["value"]){
          newValAry.push(self.getPatch(valAry[i])+ftAry[i]);
        }else{
          newValAry.push(valAry[i]);
          separator=":";
        }
      }

      return newValAry.join(separator);
    } else {
      return value;
    }
  }

  getPatch(num){
    if(num){
      if(typeof(num)=="number"){
        if(num<10)return "0"+num.toString();
        else return num.toString();
      }
      else if(typeof(num)=="string"){
        if(parseInt(num)<0)return num.toString();
        if(parseInt(num)<10)return "0"+parseInt(num);
        else return  num;
      }
      else  return num;
    }else{
      return "00";
    }
  }
}





