import {Injectable} from "@angular/core";
import {Headers, Http, RequestOptions, RequestOptionsArgs} from "@angular/http";
import {ToastController} from "ionic-angular/index";
import "rxjs/add/operator/toPromise";

import {App} from "ionic-angular/index";

declare var app:any;

@Injectable()

export class HttpHelper {

  constructor(private http: Http,private toast:ToastController,private app: App) {
  }

  /*
   * 重定向到登陆页
   */
  private redirectLogin() {
    //document.location.href="index.html";
    this.isRedirecting=true;
    if(app)
      app.redirectLogin();
  }
  /**
   * get请求
   * @param url
   * @param paramObj
   * @param options
   * @param showErrorInfo
   * @param ignore403
   * @returns {Promise<T>}
   */
  public get(url:string,paramObj:any,options?: RequestOptionsArgs,showErrorInfo?:boolean,ignore403?:boolean) {
    if(showErrorInfo==undefined)
      showErrorInfo=true;
    if(ignore403==undefined)
      ignore403=false;

    var me=this;
    return this.http.get(url + this.toQueryString(paramObj), this.genHeaderInfo(false,options)).toPromise().then(data=>{
      try {
        var old=me.is403;
        var jsonData=data.json();
        me.is403=(jsonData.result==-403);
        if(me.is403 && !old && !ignore403) {
          me.isRedirecting=false;
          showErrorInfo=false;
          me.redirectLogin();
        }
        if(jsonData.result<1 && showErrorInfo && !me.isRedirecting) {
          //显示错误信息
          let toast = me.toast.create({
            message: jsonData.message,
            duration: 3000,
            position: 'middle',
            showCloseButton: true,
            closeButtonText: '关闭'
          });
          toast.present();
        }
      }
      catch(e) {

      }
      return data;
    });
  }

  /**
   * post请求
   * @param url
   * @param paramObj
   * @param options
   * @param showErrorInfo
   * @param ignore403
   * @returns {Promise<T>}
   */
  public post(url: string, paramObj: any,options?: RequestOptionsArgs,showErrorInfo?:boolean,ignore403?:boolean) {
    if(showErrorInfo==undefined)
      showErrorInfo=true;
    if(ignore403==undefined)
      ignore403=false;

    var me=this;
    return this.http.post(url, this.toBodyString(paramObj), this.genHeaderInfo(true,options)).toPromise().then(data=>{
      try {
        var old=me.is403;
        var jsonData=data.json();
        me.is403=(jsonData.result==-403);
        if(me.is403 && !old && !ignore403) {
          me.isRedirecting=false;
          showErrorInfo=false;
          me.redirectLogin();
        }
        if(jsonData.result<1 && showErrorInfo && !me.isRedirecting) {
          //显示错误信息
          let toast = me.toast.create({
            message: jsonData.message,
            duration: 3000,
            position: 'middle',
            showCloseButton: true,
            closeButtonText: '关闭'
          });
          toast.present();
        }
      }
      catch(e) {
      }
      return data;
    });
  }

  private is403:boolean=false;
  private isRedirecting:boolean=false;
  /**
   * 已验证信息
   */
  public authenticatedInfo:any;
  /**
   * 链式请求结果值
   */
  public requestData:any;
  /**
   * 是否跨域
   */
  public crossDomain:boolean=true;
  /**
   * 是否启用跨域探测
   */
  public enableExplore:boolean=false;

  /**
   * 链式请求
   * @param params
   * @param showErrorInfo
   * @param ignore403
   * [
   *  {
   *    url:'http://192.168.18.143:8082/Test/MD5',                    //请求url
   *    params:{txt:'abc'},                                           //请求参数
   *    isPost:true,fix:function(data){return {md5Txt:data['md5']};}, //url合成函数，data为上次请求的结果json
   *    success:function(data) {alert(data['message']);}              //请求成功回调
   *   },
   *   ...
   * ]
   */
  public request(params:object[],showErrorInfo?:boolean,ignore403?:boolean) {
    var promise:any;
    if(params.length>0) {
      if(params[0]['url']) {
        var pars=[];
        if(params[0]['params']) {
          pars=this.concatParams(pars,params[0]['params']);
        }
        if(params[0]['isPost']) {
          promise=this.post(params[0]['url'],pars).then(
            r=>{
              var n:number=-1;
              for(let j=1;j<params.length;j++) {
                if(params[j]['url']) {
                  n=j;
                  break;
                }
              }
              if(params[0]['success']) {
                params[0]['success'](r);
              }
              if(n<0) {
                this.requestData=r;
              }
              else {
                var npars=[];
                if(params[n]['params']) {
                  npars=this.concatParams(npars,params[n]['params']);
                }
                if(params[n]['fix']) {
                  npars=this.concatParams(npars,params[n]['fix'](r));
                }
                params[n]['params']=npars;
                promise=this.request(params.slice(n,params.length));
              }
            }
          );
        }
        else {
          promise=this.get(params[0]['url'],pars).then(
            r=>{
              var n:number=-1;
              for(let j=1;j<params.length;j++) {
                if(params[j]['url']) {
                  n=j;
                  break;
                }
              }
              if(params[0]['success']) {
                params[0]['success'](r);
              }
              if(n<0) {
                this.requestData=r;
              }
              else {
                var npars=[];
                if(params[n]['params']) {
                  npars=this.concatParams(npars,params[n]['params']);
                }
                if(params[n]['fix']) {
                  npars=this.concatParams(npars,params[n]['fix'](r));
                }
                params[n]['params']=npars;
                promise=this.request(params.slice(n,params.length));
              }
            }
          );
        }
      }
    }

    if(showErrorInfo==undefined)
      showErrorInfo=true;
    if(ignore403==undefined)
      ignore403=false;

    var me=this;
    return promise.then(data=>{
      try {
        var old=me.is403;
        var jsonData=data.json();
        me.is403=(jsonData.result==-403);
        if(me.is403 && !old && !ignore403) {
          me.isRedirecting=false;
          showErrorInfo=false;
          me.redirectLogin();
        }
        if(jsonData.result<1 && showErrorInfo && !me.isRedirecting) {
          //显示错误信息
          let toast = me.toast.create({
            message: jsonData.message,
            duration: 3000,
            position: 'middle',
            showCloseButton: true,
            closeButtonText: '关闭'
          });
          toast.present();
        }
      }
      catch(e) {

      }
      return data;
    });
  }

  /**
   * 依据当前的验证信息生成头信息
   * @param forPost
   * @param options
   */
  public genHeaderInfo(forPost:boolean,options?: RequestOptionsArgs) {
    if(options) {
      if(!options.headers) {
        options.headers=new Headers();
      }
    }
    else {
      options=new RequestOptions(
        {
          headers: new Headers()
        }
      );
    }
    options.withCredentials=this.crossDomain;
    //if(this.enableExplore) {
    //  options.headers.set('X-Requested-With','XMLHttpRequest');
    //}
    if(forPost) {
      options.headers.set('Content-Type','application/x-www-form-urlencoded');
    }

    return options;
  }
  /**
   * 合成请求参数
   * @param obj1 源对象
   * @param obj 目标对象
   * @returns {Array} 合成后的键值对数组
   */
  public concatParams(obj1,obj) {
    let ret = [];
    if(obj1) {
      ret=ret.concat(obj1);
    }
    if(obj) {
      if(obj && obj.constructor==Array) {
        ret=ret.concat(obj);
      }
      else {
        for (let key in obj) {
          key = encodeURIComponent(key);
          let values = obj[key];
          if (values && values.constructor == Array) {//数组
            let queryValues = [];
            for (let i = 0, len = values.length, value; i < len; i++) {
              value = values[i];
              queryValues.push(this.toQueryPair(key, value));
            }
            ret = ret.concat(queryValues);
          } else { //字符串
            ret.push(this.toQueryPair(key, values));
          }
        }
      }
    }
    return ret;
  }
  /**
   * @param obj　参数对象
   * @return {string}　参数字符串
   * @example
   *  声明: var obj= {'name':'小军',age:23};
   *        var obj=['name=abc','age=15']
   *  调用: toQueryString(obj);
   *  返回: "?name=%E5%B0%8F%E5%86%9B&age=23"
   */
  private toQueryString(obj) {
    return '?' + this.concatParams([],obj).join('&');
  }

  /**
   *
   * @param obj
   * @return {string}
   *  声明: var obj= {'name':'小军',age:23};
   *  调用: toQueryString(obj);
   *  返回: "name=%E5%B0%8F%E5%86%9B&age=23"
   */
  private toBodyString(obj) {
    return this.concatParams([],obj).join('&');
  }

  private toQueryPair(key, value) {
    if (typeof value == 'undefined') {
      return key;
    }
    return key + '=' + encodeURIComponent(value === null ? '' : String(value));
  }
}



