import { Pipe, PipeTransform } from '@angular/core';
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../app/appconfig";

/**
 * Generated class for the KeyAryft pipe.
 *
 * See https://angular.io/api/core/Pipe for more info on Angular Pipes.
 */
@Pipe({
  name: '$GrassNotsetft2',
})
export class GrassNotsetft2 implements PipeTransform {
  constructor(private translate:TranslateService){}
  /**
   * Takes a value and makes it .
   */
  transform(value: any, ...args) {
    //console.log(value);
    let notSet=true;
    let valAry=value.toString().trim().split(":");
    let oldValAry=value.toString().trim().split(":");
    if(!value||valAry.length<=0){
      return this.translate.get("common.notSet")["value"];
    }
    else{
      for (let i=0;i<valAry.length;i++){
        if(parseInt(valAry[i].toString())!=-1){
          notSet=false;
          break;
        }
      }
    }
    if(notSet){
      return this.translate.get("common.notSet")["value"];
    }
    let self=this;
    if (args && typeof (args) == "object" && args.length > 0) {
      let newValAry = [];
      let separator="";
      let ftAry = args[0].toString().trim().split(":");
      let eachLength =ftAry.length;
      for (let i = 0; i < eachLength; i++) {
        if (ftAry[i] == "hh"||ftAry[i]=="mm"||ftAry[i]=="ss") {
          if( AppConfig.timeFormat==12&&ftAry[i] == "hh")
          {
            if(parseInt(valAry[i])>12){
              valAry[i]=self.getPatch(parseInt(valAry[i])-12);
            }
            else if(parseInt(valAry[i])==0){//上午12点
              valAry[i]='12';
            }
          }else{
            valAry[i]=self.getPatch(valAry[i]);
          }
          separator=":";
        }else if(ftAry[i]=="h"||ftAry[i]=="m"||ftAry[i]=="s"){
          if( AppConfig.timeFormat==12&&ftAry[i] == "h"&&parseInt(valAry[i])>12)
          {
            if(parseInt(valAry[i])>12){
              valAry[i]=(parseInt(valAry[i])-12).toString();
            }
            else if(parseInt(valAry[i])==0){//上午12点
              valAry[i]='12';
            }
          }else{
            valAry[i]=self.getPatch(valAry[i]);
          }
          separator=":";
        }else if(ftAry[i]==this.translate.get("common.hour")["value"]
          ||ftAry[i]==this.translate.get("common.minute")["value"]
          ||ftAry[i]==this.translate.get("common.second")["value"]){
          newValAry.push(self.getPatch(valAry[i])+ftAry[i]);
        }else{
          newValAry.push(valAry[i]);
          separator=":";
        }
      }


      let showTxt=valAry.join(separator);
      //添加上午下午 单位宝石
      if( AppConfig.timeFormat==12)
      {
        if(parseInt(oldValAry[0])>=0&&parseInt(oldValAry[0])<12){
          showTxt+=" "+self.translate.get("common.am")["value"];
        }else if(parseInt(oldValAry[0])>=12 && parseInt(oldValAry[0])<24){
          showTxt+=" "+self.translate.get("common.pm")["value"];
        }
      }
      return showTxt;
    } else {
      return value;
    }
  }

  getPatch(num){
    if(num){
      if(typeof(num)=="number"){
        if(num<10)return "0"+num.toString();
        else return num.toString();
      }
      else if(typeof(num)=="string"){
        if(parseInt(num)<0)return num.toString();
        else if(parseInt(num)<10)return "0"+parseInt(num);
        else return  num;
      }
      else  return num;
    }else{
      return "00";
    }
  }
}





