import {HttpHelper} from './HttpHelper';
import {Injectable} from '@angular/core';
import 'rxjs/add/operator/toPromise';
import {ToastController, LoadingController} from 'ionic-angular';
import {AppConfig} from "../app/appconfig";

@Injectable()
export class Utility {
  public toast;
  public loading;

  constructor(
    public  toastCtrl: ToastController,
    public loadingCtrl: LoadingController
  ) {
  }

  /*
   弹出信息提示
   message:提示信息
   duration:显示时间毫秒
   position:显示位置["top", "middle", "bottom"]
   */
  showToast = (message: string = '操作完成', duration: number = 2500, position: string = 'top') => {
    this.toast = this.toastCtrl.create({
      message: message,
      duration: duration,
      position: position,
      showCloseButton: true,
      closeButtonText: '关闭'
    });
    this.toast.present();
  };
  /**
   * 关闭信息提示框
   */
  hideToast = () => {
    this.toast.dismissAll()
  };

  /**
   * 加载数据时的友好提示
   * @param content 显示的内容
   */
  showLoading = (content: string = '') => {
    this.loading = this.loadingCtrl.create({
      content: content
    });
    this.loading.present();
  };

  /**
   * 关闭loding
   * 数据加载玩完手动关闭
   */
  hideLoading = () => {
    this.loading.dismiss();
  };


  /*
    获取格式化日期(到天)
    dayNum:默认为0表示今天  小于0表示今天之前多少天，大于0表示今天之后多少天
    formatStr:日期之间的分隔符 默认'/' '2015/05/05'
   */
  getDateStringShort = (dayNum: number = 0, fromatStr: string = '/') => {
    var uom = new Date();
    uom.setDate(uom.getDate() + dayNum);
    return uom.getFullYear() + fromatStr + (uom.getMonth() + 1) + fromatStr + uom.getDate();
  };

  /*
  获取格式化日期(到天)
  dayNum:默认为0表示今天  小于0表示今天之前多少天，大于0表示今天之后多少天
  formatStr:日期之间的分隔符 默认'/' '2015/05/05'
 */
  getDateMonth = (dayNum: number = 0, fromatStr: string = '/') => {
    var uom = new Date();
    uom.setDate(uom.getDate() + dayNum);
    return (uom.getMonth() + 1);
  };
  /*
   获取格式化日期(到秒)
   dayNum:默认为0表示今天  小于0表示今天之前多少天，大于0表示今天之后多少天
   formatStr:日期之间的分隔符 默认'/' '2015/05/05'
   */
  getDateStringLong = (dayNum: number = 0, fromatStr: string = '/') => {
    var uom = new Date();
    uom.setDate(uom.getDate() + dayNum);
    return uom.getFullYear() + fromatStr + (uom.getMonth() + 1) + fromatStr + uom.getDate() + ' ' + uom.getHours() + ':' + uom.getMinutes() + ':' + uom.getSeconds();
  };

  /*
  获取格式化日期(到秒)
  dayNum:默认为0表示今天  小于0表示今天之前多少天，大于0表示今天之后多少天
  formatStr:日期之间的分隔符 默认'/' '2015/05/05' 00:00:00
  */
  getDateStringLongstart = (dayNum: number = 0, fromatStr: string = '/') => {
    var uom = new Date();
    uom.setDate(uom.getDate() + dayNum);
    return uom.getFullYear() + fromatStr + (uom.getMonth() + 1) + fromatStr + uom.getDate() + ' ' + '00:00:00';
  };

  /*
获取格式化日期(到秒)
dayNum:默认为0表示今天  小于0表示今天之前多少天，大于0表示今天之后多少天
formatStr:日期之间的分隔符 默认'/' '2015/05/05' 23:23:59
*/
  getDateStringLongend = (dayNum: number = 0, fromatStr: string = '/') => {
    var uom = new Date();
    uom.setDate(uom.getDate() + dayNum);
    return uom.getFullYear() + fromatStr + (uom.getMonth() + 1) + fromatStr + uom.getDate() + ' ' + '23:59:59';
  };

  /*
  浇水日添加暂停天数，形成新的日期
  返回 时间+ 00:00:00
   */
  addDate(tempdate, days) {
    if (days == undefined || days == '') {
      days = 1;
    }
    var date = new Date(tempdate);
    date = new Date(date.setDate(date.getDate() + days));
    date = new Date(date.setHours(0, 0, 0));
    return date;
  }

  formatTimeStr(timeStr: string) {
    if (timeStr) {
      var tIndex = timeStr.indexOf('T');
      return timeStr.substring(0, tIndex);
    }
  };

  formatTimeStr2(timeStr: string) {
    if (timeStr) {
      timeStr = timeStr.replace("T", " ");
      let date = new Date(timeStr);
      return date.getFullYear() + "年" + date.getMonth() + "月" + date.getDate() + "日";
    }
  };

//时间格式化输出
  dateFormat = function (date, fmt) {
    var o = {
      "M+": date.getMonth() + 1, //月份
      "d+": date.getDate(), //日
      "h+": date.getHours(), //小时
      "m+": date.getMinutes(), //分
      "s+": date.getSeconds(), //秒
      "q+": Math.floor((date.getMonth() + 3) / 3), //季度
      "S": date.getMilliseconds() //毫秒
    };
    if (/(y+)/.test(fmt)) fmt = fmt.replace(RegExp.$1, (date.getFullYear() + "").substr(4 - RegExp.$1.length));
    for (var k in o)
      if (new RegExp("(" + k + ")").test(fmt)) fmt = fmt.replace(RegExp.$1, (RegExp.$1.length == 1) ? (o[k]) : (("00" + o[k]).substr(("" + o[k]).length)));
    return fmt;
  };

  //region 时间戳转换时间格式
  /*
     时间戳转换时间格式
   */
  timestampFormat(timestampF) {
    //shijianchuo是整数，否则要parseInt转换
    var time = new Date(timestampF);
    var y = time.getFullYear();
    var m = time.getMonth() + 1;
    var d = time.getDate();
    var h = time.getHours();
    var mm = time.getMinutes();
    var s = time.getSeconds();
    return y + '-' + this.add0(m) + '-' + this.add0(d) + ' ' + this.add0(h) + ':' + this.add0(mm) + ':' + this.add0(s);
  }

  timestampFormataddRun(timestampF, addRun) {
    //shijianchuo是整数，否则要parseInt转换
    var time = new Date(timestampF);
    time = new Date(time.setSeconds(time.getSeconds() + addRun))
    var y = time.getFullYear();
    var m = time.getMonth() + 1;
    var d = time.getDate();
    var h = time.getHours();
    var mm = time.getMinutes();
    var s = time.getSeconds();
    return y + '-' + this.add0(m) + '-' + this.add0(d) + ' ' + this.add0(h) + ':' + this.add0(mm) + ':' + this.add0(s);
  }

  add0(m) {
    return m < 10 ? '0' + m : m
  }

  //endregion

  //将秒数转换为时分秒格式
  formatSeconds(value) {
    let result = parseInt(value)
    let h = Math.floor(result / 3600) < 10 ? '0' + Math.floor(result / 3600) : Math.floor(result / 3600);
    let m = Math.floor((result / 60 % 60)) < 10 ? '0' + Math.floor((result / 60 % 60)) : Math.floor((result / 60 % 60));
    let s = Math.floor((result % 60)) < 10 ? '0' + Math.floor((result % 60)) : Math.floor((result % 60));

    let res = '';
    if (h !== '00') res += `${h}:`;
    if (m !== '00') res += `${m}:`;
    res += `${s}`;
    return res;
  }

  formatDateBystrdate(strDate) {
    if (AppConfig.isDebug) return strDate;
    else {
      var st = strDate;
      var a = st.split(" ");
      var b = a[0].split("-");
      var c = a[1].split(":");
      var date = new Date(b[0], b[1], b[2], c[0], c[1], c[2]);
      return date;
    }
  }

}




