import {MenuController, NavController, NavParams, Platform, Tabs} from 'ionic-angular';
import {MoreHomePage_1} from "../../more_1/moreHome_1/moreHome_1";
import {HomeBttsPage_1} from "../../btts_1/homeBtts_1/homeBtts_1";
import {OneSchedulePage} from "../../oneExport/oneSchedule/oneSchedule";
import {ChangeDetectorRef, Component, ViewChild} from '@angular/core';
import {CommandFactory} from "../../../util/CommandFactory";
import {bttTestPage} from "../../btts/bttTest/bttTest";
import {TranslateService} from "ng2-translate";
import {AppConfig} from "../../../app/appconfig";

declare var cordova: any;

@Component({
  selector: 'page-nav_1',
  templateUrl: 'nav_1.html'
})

export class NavPage_1 {
  @ViewChild('myTabs') tabRef: Tabs;

  rootPage1: any = HomeBttsPage_1;
  rootPage2: any = OneSchedulePage;
  rootPage3: any = MoreHomePage_1;
  rootPage4: any=bttTestPage;
  tab1Title = " ";
  tab2Title = " ";
  tab3Title = " ";

  constructor(
    public navCtrl: NavController,
    public  menu: MenuController,
    private  platform: Platform,
    public  NavParams: NavParams,
    public cd: ChangeDetectorRef,
    private commandFactory:CommandFactory,
    private translate: TranslateService
  ) {
    AppConfig.consoleLog("tab1Title:"+this.translate.get("nav.tab1")["value"]);
  }
  ionViewDidEnter(){
    // let self=this;
    // self.commandFactory.getConnected()
    //   .then((success)=>{
    //     if(success["connected"]){
    //       this.tabRef.select(1);
    //     }else{
    //       this.tabRef.select(0);
    //     }
    //   },(error)=>{
    //     this.tabRef.select(0);
    //   });
    //
    // let navTimer= setTimeout(()=>{
    //   if(this.translate.get("nav.tab1")["value"])
    //     this.tab1Title=this.translate.get("nav.tab1")["value"];
    //   if(this.translate.get("nav.tab2")["value"])
    //     this.tab2Title=this.translate.get("nav.tab2")["value"];
    //   if(this.translate.get("nav.tab3")["value"])
    //     this.tab3Title=this.translate.get("nav.tab3")["value"];
    //   AppConfig.consoleLog("this.tab1Title:"+this.tab1Title);
    //   AppConfig.consoleLog("this.tab2Title:"+this.tab2Title);
    //   AppConfig.consoleLog("this.tab3Title:"+this.tab3Title);
    //   window.clearTimeout(navTimer);
    // },1500);
    let self=this;
    self.commandFactory.getConnected()
      .then((success)=>{
        if(success["connected"]){
          this.tabRef.select(1);
        }else{
          this.tabRef.select(0);
        }
      },(error)=>{
        this.tabRef.select(0);
      });

  }

  ionViewWillEnter() {
  }

  ionChange(evl){
    this.tabRef.select(evl.index);
    this.cd.detectChanges();
  }

}



